INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8620030501', 'Sirene Segurança 7 Tons Tech One com Microfone - Policia Bombeiro Ambulância', 'Sirene 7 tons TECHONE *** A ÚNICA DO MERCADO QUE VEM COM BOTÃO LIGA E DESLIGA*** Utilizadas nas viaturas de polícia, bombeiros e ambulâncias, as sirenes 7 tons possuem função principal de alerta no trânsito e comunicação com as pessoas que estão na parte de fora sem a abertura dos vidros. Além de seu uso profissional, as sirenes são usadas para proporcionar diferencial sonoro aos carros. Para proporcionar o destaque esperado, esta sirene possui 105dB de pressão sonora, 20W de potência, tensão de operação de 12V, 7 diferentes tons e microfone, que possibilita a dissipação da voz a parte externa do veículo. Especificações técnicas: * Tensão de Operação: 12V * Pressão Sonora: 102dB * 20W de Potência * Consumo em Durante Utilização: 2,5A * Tons gravados: - Advertência 1 - Ambulância 1 - Advertência 2 - Polícia - Bombeiro - Advertência 3 - Ambulância 2 - Botão PTT para falar - Microfone * Fabricação em Plástico Resistente * Acompanha Microfone * Pode Ser Usado em Qualquer Veículo * Utilizado para Alertas no Trânsito * Dimensões de Sirene(AxLxC): 12x12x14cm * Dimensões do Controle(AxLxC): 9x5,5x3cm A Sirene pode ir na embalagem branca ou na embalagem azul, de acordo com a disponibilidade do estoque. Conteúdo da embalagem: 1 Sirene 1 Microfone 1 Suporte para Microfone 1 Botão Universal Liga e Desliga Recomenda-se a instalação da sirene no cofre do motor, protegido da água. Toda instalação deve ser efetuada por um profissional capacitado. Antes de utilizar o item, leia todo o manual de instrução. Indicado para veículos blindados, empresa de segurança entre outras. verifique as leis de sua cidade quanto à utilização, antes de instalar o item. Fio de alimentação estendido para facilitar a instalação, sem a necessidade de emendas.', 114.9, 114.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mig7swscsu81d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288347041%2F8620030501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
