INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394286415', 'O Médico e o Monstro | Robert Louis Stevenson', 'Gabriel John Utterson é um advogado que investiga um caso estranho envolvendo Henry Jekyll e Edward Hyde, repentino beneficiário do testamento de Henry. O advogado descobre acontecimentos que resultam na reclusão repentina de Jekyll. O romance que envolve ficção científica, transtornos psicológicos e terror é um grande clássico do gênero. 23X16 cm 96 Páginas', 15.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-mcz4wxmb5iz29b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22394286415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598047228', 'Colchão Casal Espuma D33 138cm Ouro Umaflex', 'O Colchão Casal Espuma D33 138cm Ouro Umaflex é ideal para quem busca conforto, qualidade e durabilidade para noites de sono mais tranquilas. Produzido com espuma D33, oferece excelente sustentação para o corpo, ajudando a manter o alinhamento da coluna. Seu revestimento em tecido 100% poliéster garante toque agradável e boa resistência ao uso diário. Com certificação do INMETRO, o colchão assegura padrões de qualidade e segurança. Indicado para biotipo de até 90 kg por pessoa, é uma ótima escolha para renovar o quarto com um produto confiável da Umaflex. Características do produto: Biotipo suportado até 90 kg Certificado pelo INMETRO Composição 100% espuma Densidade D-33 Faixa em tecido 100 poliéster Tampo em tecido 100 poliéster Tamanho casal 138 cm Dimensões do produto: Altura: 16 cm Largura: 138 cm Profundidade: 188 cm Peso: 16,1 kg Garantia do fornecedor: 3 meses.', 659.9, 609.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820ll-mpusvmi9atc3ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F23598047228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
