INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693742934', 'Macunaíma: O Herói Sem Nenhum Caráter | Mário de Andrade', 'Às margens do Uraricoera, na Floresta Amazônica, nasce o preguiçoso e vaidoso Macunaíma, que desde pequeno, não hesita em mentir e se transformarem outras pessoas para satisfazer seus desejos.Sua mãe logo o abandona e, em sua nova jornada, ele ganha um talismã da Mãe do Mato, mas o perde.Então, parte para o Sudeste do Brasil em busca do amuleto.Macunaíma é um marco modernista e uma reflexão do autor sobre a cultura brasileira.Mescla os dialetos e costumes de diversas regiões na narrativa e aborda a desigualdade social no país. 16x23cm 144 Páginas', 14.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4d-m6txv8ywgoor43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23693742934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
