INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398298167', 'Tamanco Dakota de Salto Bloco Feminina Y9422', 'Produto marca Dakota. O Tamanco Dakota de Salto Bloco é a combinação perfeita de elegância e conforto para a mulher moderna. Com um design minimalista e sofisticado, ele se destaca pelo recorte sobre o pé e uma tira deslumbrante repleta de brilhos que adiciona um toque de glamour instantâneo aos seus looks. Ideal para o dia a dia ou momentos de lazer, este calçado versátil eleva qualquer produção, do casual ao mais elaborado. Sinta a confiança que um salto bloco de 6,5 cm pode oferecer, garantindo estabilidade e bem-estar durante todo o dia. Feito em material sintético de alta qualidade, este tamanco Dakota é leve e durável, pesando apenas 0,607 kg, o que o torna a escolha perfeita para quem busca praticidade sem abrir mão do estilo. Transforme seus pés e desfrute da sensação de estar sempre impecável, seja em um passeio descontraído ou em um evento especial. Não perca a chance de ter em seu guarda-roupa um item que exala tendência e bom gosto. Adquira agora o seu tamanco Dakota e desperte olhares por onde passar. Este é o investimento certo para mulheres que valorizam conforto, beleza e praticidade, e que desejam expressar sua personalidade vibrante em cada passo. Peso: 0,607 kg Altura do salto: 6,5 cm', 189.9, 179.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-824ia-me7n4wz6ksn57e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F19398298167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393537883', 'Kit com 4 Diga a Eles que os Amo - Joyce Meyer', 'VOCÊ REALMENTE SABE O QUANTO DEUS O AMA ? Talvez você já tenha ouvido diversas vezes: Deus ama você! E as pessoas costumam citar versículos que nos dizem: "Por que Deus amou o mundo de tal maneira"e "Deus é Amor". Mas a questão é: você realmente entende que Deus o ama incondicionalmente, o tempo todo, haja o que houver ? Essa verdade influencia sua vida diariamente, fazendo-o ser livre para ser o que Deus o criou para ser e fazer tudo o que Ele planejou para você ? Neste ensinamento clássico, você poderá: - Mergulhar na profundidade do que a Bíblia realmente diz sobre o amor de Deus - Aprender a receber esse amor e dá-lo a outros - Experimentar os efeitos transformadores que ele traz - Descobrir como viver no amor de Deus diariamente Esta mensagem é vital para todo crente em Cristo que deseja ter um relacionamento pessoal e íntimo com Ele, e cumprir o potencial e o propósito que foi lhe dado por Deus. Não importa se sua fé em Deus é recente ou se colocou sua confiança nele há anos, você aprenderá algo novo que o aproximará mais dele, ao experimentar um amor que é melhor do que jamais imaginou! Uma grande porcentagem das dificuldades que as pessoas enfrentam tem origem na falta do conhecimento de que Deus as ama pessoalmente. Ao ler este livro, leia crendo que Deus revelará ao seu coração o Seu amor por você, um indivíduo muito precioso ao corpo de cristo. Creia que Ele te ama! Creia que você é importante para Deus! 55 Páginas 12x17cm', 49.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7reol-m2mzskdx0y6e56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23393537883', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394652519', 'A Mulher de Branco | Tomo 3 | Wilkie Collins', 'Um inusitado encontro à meia-noite entre o artista Walter Hartright e uma mulher vestida de branco, que parece desesperada para compartilhar um segredo obscuro, deixa no ar uma sombra fantasmagórica. No dia seguinte, Hartright, contratado como mestre de desenho da bela Laura Fairlie e de sua meia-irmã Marian Halcombe, conta aos alunos sobre os estranhos acontecimentos. Determinados a aprender tudo o que puderem sobre a misteriosa mulher vestida de branco, os três logo se veem atraídos por um vórtice arrepiante de crime, veneno, sequestro e intriga internacional.256 páginas15,5x22,6 cm', 20.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821fb-mglq3og42txk90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23394652519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
