INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493480142', 'Fralda Pampers Premium Care Topíssima XG com 120un', 'Conhece o kit exclusivo de fraldas de venda online Pampers Premium Care, que inclui 2 pacotes de 60 fraldas cada. Premium Care oferece o maior cuidado para a pele do seu bebê de Pampers! Graças a nossa exclusiva loção hipoalergênica que ajuda a prevenir assaduras e manter a pele do seu bebê saudável e protegida. Nossas fraldas são suaves como o algodão* e ultra respiráveis, proporcionando conforto e frescor ao seu bebê durante todo o dia. A Pampers Premium Care oferece uma camada de absorção que retém a umidade, mantendo a pele do bebê seca e protegida por até 12 horas. Com sua tecnologia inovadora, essas fraldas se ajustam perfeitamente ao corpo do seu bebê, garantindo um ajuste seguro e confortável. Experimente a Pampers Premium Care.*Não contém fibras de algodão*Suavidade sentida na camada externa da fralda • Máxima absorção de Pampers • Loção Hipoalergênica • Ultra respirável • Suave como algodão° • Ajuste cômodo e flexível: esticam e se ajustam aos movimentos do seu bebê • Barreiras anti-derrames • Novos desenhos para o dia e para a noite!', 312.59, 278.2, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx9-m1iiflvt40cf98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1062557396%2F22493480142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
