INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20725830351', 'Repelente Elétrico Raid Líquido Óleo de Citronela 32,9ml Refil', 'Raid Elétrico Líquido oferece proteção contra os mosquitos por até 45 noites. Disponível nas versões regular, eucalipto e citronela. Utilize sempre um aparelho para cada 10m quadrados. Dica: coloque o aparelho na tomada 30 minutos antes de dormir e deixe sempre uma porta ou janela aberta para repelir os mosquitos do ambiente. 1. Abra a tampa do refil e o introduza no aparelho girando no sentido horário. 2. Plugue o aparelho na tomada bivolt (110-240V), sempre no sentido vertical. 3. Para desligar, retire o conjunto (aparelho + refil) da tomada e troque o refil quando estiver vazio.', 28.39, 28.39, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/c6d5533fee81ce07320bfb8ac2b899a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F20725830351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
