INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20957314906', 'Pivô Fiorino 91 92 93 94 95 A 2013 Inferior Motor Passageiro', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FIAT FIORINO FURG.1.5/1.3/1.3 FIRE/1.3 F.FLEX 1985 até 1994, 2003 até 2013 FIORINO FURGãO 1.0 1993 até 1997, 2000 até 2006 FIORINO FURGãO 1.5 MPI / I.E. 1992 até 2005 FIORINO PICK-UP 1.0 1993 até 1997, 2000 até 2006 FIORINO PICK-UP 1.5 I.E./1.3/1.5/HD 1988 até 1997 FIORINO PICK-UP LX (TODAS) 1988 até 1998 FIORINO PICK-UP TREKKING 1.5 MPI / I.E. 1995 até 1999 FIORINO PICK-UP WORKING 1.5 MPI / I.E. 1996 até 1999 FIORINO 1985 até 1997 Conteúdo Da Embalagem 1 Pivô de Suspensão Cor do Produto No Tipo de Veículo para Carros Marca Pioneirismo, qualidade, compromisso e confiança. Esses são valores que sustentaram e projetam à tradição da Nakata nestes mais de 60 anos de atuação. Uma história feita por pessoas dedicadas e apaixonadas pelo que fazem, que juntas mantém esse sonho vivo, com entusiasmo e determinação. Hoje, 100% comprometida com o mercado de reposição e suas necessidades, a Nakata Automotiva continua com estes mesmos princípios, buscam a cada momento um novo desafio, excelência em tudo que faz e soluções que superam as expectativas de seus parceiros. O Produto O pivô da suspensão é importantíssimo para o correto do funcionamento do sistema de suspensão do carro. A sua função é a de realizar a ligação do chassi e carroceria com o telescópio, manga de eixo e cubo de roda. Durante a aceleração, frenagem e curvas, o pivô da suspensão suporta muito peso e recebe muita força. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia - 12 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7897499915358 Código do Fabricante N6009WN610 Posição Dianteiro Inferior Direção Hidráulica Mecânica Transmissão Manual Posição Dianteiro Inferior', 40.79, 40.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rbmd-llu3ktnpkp7te6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20957314906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18557316089', 'Filtro Óleo Corsa Sedan 1.0 1.6 1.8 96 A 2009 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação CORSA SED CLAS.SUPER 1.6MPFI VHC 8V AUT 2005 CORSA SED CLASSIC SUPER 1.6 MPFI VHC 8V 2004 até 2006 CORSA SED. JOY 1.8 MPFI 8V FLEXPOWER 2005 até 2007 CORSA SED. MAXX 1.8 MPFI 8V FLEXPOWER 2005 até 2007 CORSA SED. PREMIUM 1.8 MPFI 8V FLEXPOWER 2005 até 2009 CORSA SEDAN 1.0 MPFI 8V 71CV 4P 2002 até 2006 CORSA SEDAN 1.8 MPFI 8V 102CV 4P 2002 até 2003 CORSA SEDAN 1.8 MPFI FLEXPOWER 8V 4P 2004 CORSA SEDAN GL 1.6 MPFI 4P 1996 até 2001 CORSA SEDAN GLS 1.6 MPFI 4P 1996 até 2001 CORSA SEDAN SUPER 1.0 MPFI 16V 4P 1999 até 2002 CORSA SEDAN SUPER MILENIUM 1.0 MPFI 16V 1999 até 2002 CORSA SEDAN SUPER/ CLASSIC 1.6 MPFI 8V 4 2001 até 2004 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para Carros Marca A Tecfil é sinônimo de qualidade e garantia da melhor experiência. A mais de 60 anos no mercado, o comprometimento em fazer o melhor para o cliente a garantiu o mais alto patamar de reconhecimento em qualidade e tecnologia. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o filtro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7891342000192 Código do Fabricante PSL619 Combustível Álcool Flex Gasolina >', 12.54, 12.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkn-lltbu04v0mpx41', 'https://shope.ee/an_