INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097457192', 'Cano Refrigeração SCENIC 1999/2006 - 31162 - 087190', 'Cano Refrigeração SCENIC 1999/2006 MOTOR 1.6 16V, O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 52.29, 52.29, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-lnbnyzxnhvbue7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21097457192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698090453', 'Pré Filtro Combustível Fiat Fiorino 1994 a 2002 - 1354966 - T040217', 'Pré Filtro Combustível Fiat Fiorino 1994 a 2002 1354966 T040217 Gasolina - Sistema MarwallO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 33.87, 33.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6a-m7bn2xrjzenkeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20698090453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597777834', 'Filtro de Ar Esportivo Bocal 43mm Kasinski Comet 250 Após 2007', '*BRAÇADEIRA INOX DE BRINDE* Aplicação: *BOCAL DO FILTRO: 43MM* KASINSKI COMET 250 - 2007 --> EM DIANTE KASINSKI MIRAGE 250 - 2006 --> EM DIANTE YAMAHA FAZER 150 - 2013 --> EM DIANTE YAMAHA FAZER 250 - 2007 --> EM DIANTE YAMAHA DT 200 YAMAHA RD 135 YAMAHA DT 180 YAMAHA RX 180 YAMAHA LANDER 150 HONDA NX 200 HONDA TITAN 150 HONDA STRADA HONDA CBX 200 HONDA BIZ 125 HONDA FAN 150 HONDA FAN 125 HONDA CG 150 HONDA XR 200 SUNDOWN FUTURE 125 Especificações: Altura: 62mm Diâmetro Interno: 43mm Diâmetro Externo: 74mm Tipo de Produto: Filtro de Ar Esportivo Referência: FAMT8243S Marca: Japanparts EAN: 7908374407322', 46.9, 46.15, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-m0bo691n9ltcb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F23597777834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097972123', 'Cubo Roda Ford Versailles 1991 a 1996 - 160762 - HFCD01', 'Cubo Roda Ford Versailles 1991 a 1996 160762 HFCD01 (Dianteira) (Forjado) (22 Dentes) (Sem Rolamento) (Encanelado) (4 Furos) Peça responsável por transmitir o livre movimento realizado pelas juntas homocinéticas sem riscos de atrito, o cubo de roda automotivo ainda é encarregado por realizar o suporte do disco de freio, local onde os parafusos das rodas são fixados. O funcionamento do cubo de roda automotivo ocorre quando as juntas homocinéticas, que estão conectadas ao cubo de roda, transmitem a rotação entre eles, gerando, assim, o movimento da roda.', 73.05, 73.05, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Wheels', 'https://cf.shopee.com.br/file/sg-11134201-7rblk-lmrmm7ybact617', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21097972123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097431318', 'Filtro Ar Renault Logan 2017 a 2020 - 830842 - FAP9299', 'Filtro Ar Renault Logan 2017 a 2020 830842 FAP9299 1.0 12v Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 59.06, 59.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbk7-lmtaq2u5pba2f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18097431318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198241213', 'Cabo De Vela ELBA 1.5 8v 1992 Ate 1996 (Injeção) - 86115 - FI46', 'Cabo De Vela ELBA 1.5 8v 1992 Ate 1996 (Injeção) 1.5/1.6 8v - (Injeção)Conduz a alta tensão produzida pela bobina (ou transformador) até as velas de ignição, sem permitir fugas de corrente, garantindo uma ignição sem falhas. Reduz de interferências eletromagnéticas, que podem prejudicar o funcionamento dos componentes eletrônicos do veículo, unidades de comando eletrônico e etc. Cabos resistivos - com o resistor instalado dentro dos terminais. Cabos supressivos - com o supressor instalado dentro do próprio cabo e sua resistividade depende do seu comprimento.', 43.1, 43.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-m6y1w9rmtz8b0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23198241213', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998380646', 'VÁLVULA TERMOSTÁTICA FORD KA 1.0 1.6 8V FLEX - 2008 A 2013 COURIER 1.6 FLEX - 2007 A 2013', 'Aplicação: FORD KA 1.0 8V FLEX - 2008 A 2013 KA 1.6 8V FLEX - 2008 A 2013 COURIER 1.6 FLEX - 2007 A 2013 Especificações: Tipo: Válvula termostática Temperatura de Abertura: 100 °C Referência: GPVA054 Marca: Greenparts EAN: 7908374418168 Números Originais: OEM - 5S6G8575BA', 169.9, 158.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7req9-m8f9hq724rrr03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F794835204%2F23998380646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292981329', 'Filtro Óleo Kia Cadenza 2011 a 2016 - 183637 - WOE913', 'Filtro Óleo Kia Cadenza 2011 a 2016 183637 WOE913 Motor 3.5 24v V6 Gasolina - (Automático) (Refil) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 62.67, 62.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd62-lufcq99tw7rraf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292981329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
