INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299371171', 'Filtro Ar Pulse Compass Renegade 1.3 MANN-FILTER C31028/1', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação Fastback 1.3 16V 2022 a 2024 Pulse 1.3 16V 2022 a 2024 Toro 1.3 16V 2021 a 2023 Commander 1.3 16V 2021 a 2024 Compass 1.3 16 2021 a 2024 Renegade 1.3 16V 2022 a 2024 Conteúdo da Embalagem 1 Filtro de Ar Especificações Combustível: Flex Código da Peça C31028/1 Código de Barras 4011558612214 Código da Montadora 52080841 Garantia de Fábrica 3 Meses > >', 49.58, 49.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rdx9-lzksuztjjd5u7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1340945235%2F20299371171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27041551784', 'Kit Filtro de Torneira Extensor Giratório Filtragem Multicamadas Aço Inox Adaptador Universal', 'O Filtro de Torneira 2025 é a solução ideal para quem busca mais qualidade na água do dia a dia. Com sistema de filtragem multicamadas, ele remove sedimentos, ferrugem, cloro residual e outras impurezas, preservando os minerais essenciais. Seu design giratório 360° facilita o uso em diversas situações, como lavar alimentos, utensílios e até plantas. Características: -Filtragem eficiente com algodão PP e bolas de sulfito de cálcio -Reduz cloro, ferrugem, areia e outras partículas -Melhora o sabor da água e protege a pele e os cabelos -Cabeça giratória 360° para maior praticidade no uso diário -Material durável: corpo em ABS e painel de aço inoxidável -Ideal para cozinhas, banheiros, varandas e áreas externas -Compatibilidade universal com a maioria das torneiras -Instalação fácil, sem necessidade de ferramentas Especificações: -Material: ABS + Aço Inox -Cor: Azul e Branco -Tamanho Aproximado: 3,5 × 3 cm -Tipo de Filtro: Multicamadas (algodão PP + bolas de sulfito de cálcio) Opções de Kit Disponíveis: -Adaptador de torneira+10 filtros refis -Adaptador + extensor de torneira + 1 filtro -10 filtros avulsos -Adaptador + extensor + 11 filtros Recomendações de uso e manutenção: -Substitua o filtro a cada 3 meses ou quando a coloração mudar para amarela/escura -Evite o uso com água quente contínua para preservar a vida útil -Fácil higienização com água corrente; evite produtos abrasivos Imagens e vídeos são meramente ilustrativos. A tonalidade da cor pode variar conforme o monitor.', 37.9, 17.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meoaaurrpslee0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F27041551784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993706666', 'Delet Limpador de Pneus e Borrachas (1,5 L) Vonixx', 'DESCRIÇÃO GERAL Delet é um limpador de alta performance, formulado exclusivamente para remover sujidade severa em pneus e borrachas, garantindo total limpeza, desenvolvendo originalidade e sem deixar aspecto acinzentado. Essa limpeza ajudará a melhorar a performance dos produtos para condicionar os pneus. Precauções Cuidado! Perigosa sua ingestão. Pode provocar danos ao sistema respiratório por exposição repetida ou prolongada. Conserve fora do alcance das crianças e animais domésticos. Evite contato prolongado com a pele, Lavar as mãos após o uso. Em caso de contato com os olhos, lavar com água corrente em abundâmcoa durante 15 minutos. Se inalado em excesso, remover a pessoa para local bem ventilado. Se ingerido, não provacar vômito e consultar de imediato Centro de Intoxicações ou Serviço de Saúde mais próximo, portando a embalagem ou rótulo do produto. Ceatox 0800 722 6001 manter o produto na embalagem original. Proteger o produto do sol e do calor. Não reutilizar a embalagem vazia para outra finalidade. Modo de uso 1- Com o pneu ainda seco, pulverizar a espuma do produto em todo pneu. 2- Deixar o produto agir de 30 a 60 segundos, ou até observar uma mudança de coloração da espuma de branco para cinza, marrom ou preto. Essa mudança de coloração é um indicador de presença de muita impregnação de sujeira. 3- Fazer a esfregação por completo, utilize uma escova para limpeza de pneus. 4- Fazer o enxágue com um jato d''água. 5- Se necessário repita a operação.', 62.53, 62.53, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcdg-m6fvq8yulkbt32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F23993706666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
