INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293844669', 'Conexão Pneumática Reta Fêmea Lisa 06mm X 1/4 Polegadas', '- A Conexão Reta Pneumática Fêmea 1/4 BSP x Tubo 8mm é uma peça essencial para sistemas pneumáticos, projetada para garantir uma ligação segura e eficiente entre componentes que utilizam ar comprimido - Fabricada com materiais de alta qualidade, ela é ideal para instalações em indústrias automotivas, máquinas operatrizes, sistemas de automação e outros equipamentos que dependem de conexões pneumáticas robustas e confiáveis - Essa conexão é ideal para ser utilizada em locais que exigem montagem compacta e de fácil instalação, garantindo a vedação perfeita e a condução segura de ar comprimido - É uma solução prática e eficiente para aplicações em sistemas de controle pneumático, linhas de produção automatizadas e outras configurações industriais que demandam precisão e resistência Ficha Técnica: • Pressão de Trabalho: 0 a 8 BAR • Pressão Negativa: -750mmHg • Pressão Máxima: 10 BAR • Temperatura de Trabalho: 0 a +60°C • Material: Latão niquelado • Conexão: Reta Fêmea • Tubo Diâmetro: 6mm • Rosca Tamanho: 1/4 Pol.', 12.47, 12.1, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-m7glumftk2r4dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F22293844669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
