INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23002819769', 'Câmara de ar 29 Gtsm1 válvula Presta bico fino', 'CÂMARA DE AR GTSM1 ARO 29 • VÁLVULA PRESTA 40MM • ALTA VEDAÇÃO • RESISTENTE • PARA MTB E USO URBANO A Câmara de Ar GTSM1 Aro 29 foi desenvolvida para oferecer excelente vedação, resistência e durabilidade, proporcionando maior segurança e confiabilidade durante as pedaladas. Indicada para bicicletas aro 29, é fabricada em borracha de alta qualidade e equipada com válvula Presta (bico fino) de 40mm, garantindo compatibilidade com a maioria dos aros e calibragem mais precisa. Ideal para uso urbano, passeios e Mountain Bike, é uma excelente opção para reposição ou manutenção da sua bicicleta. ✔ Peso aproximado • 250g • ✔ Capacidade máxima • Conforme especificação do pneu compatível • ✔ Indicação de uso • Bicicletas aro 29 para uso urbano, passeios e MTB 【COMPATIBILIDADE】 Indicada para bicicletas aro 29 • Compatível com pneus nas medidas 29 x 1.95 até 29 x 2.10 • Válvula Presta (bico fino) de 40mm • Compatível com aros preparados para válvula Presta. 【CONSTRUÇÃO】 Fabricada em borracha de alta qualidade • Desenvolvida para proporcionar excelente vedação, resistência a perfurações e maior durabilidade durante o uso. 【DESEMPENHO】 Proporciona retenção eficiente da pressão de ar • Excelente vedação • Maior confiabilidade para pedaladas urbanas, passeios e trilhas leves • Facilita uma rodagem confortável e segura. 【ESPECIFICAÇÕES TÉCNICAS】 Marca GTSM1 • Medida 29 x 1.95 / 2.10 • Material Borracha • Válvula Presta (bico fino) 40mm • Peso aproximado 250g • Conteúdo da embalagem 01 câmara de ar. 【GARANTIA】 Garantia contra defeitos de fabricação conforme política da marca • Produto desenvolvido para oferecer qualidade, segurança e excelente desempenho. 【IMPORTANTE】 Antes da compra, confirme a medida do pneu e o tipo de válvula compatíveis com sua bicicleta. Recomenda-se realizar a instalação com ferramentas adequadas e calibrar a câmara conforme a pressão indicada no pneu para garantir maior durabilidade e melhor desempenho. As imagens são ilustrativas e podem apresentar pequenas variações de acabamento conforme o lote de fabricação, sem alterar a qualidade ou funcionalidade do produto.', 27.9, 25.95, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-22100-2s1hitn5s8ivd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389286080%2F23002819769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
