INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297982943', 'Manta Acústica Forro Do Capo Outlander 2010 2011 A 2012 2013', 'Vantagens de comprar com a Puma Auto Parts: • Compra 100% segura • Compras efetuadas até as 12H são enviadas no mesmo dia. (Considerando dias úteis) • Produto de qualidade e com nota fiscal • Diversas formas de pagamento • Dúvidas no chat Forro do Capô Auto-Colante com Kit de Presilha de Fixação Compatível com: • Outlander 2010 2011 2012 2013 Especificação Técnica: • Feltro Isolante Automotivo de 5mm Espessura • Tratamento Betumado Auto-Extinguível - Parte Escura do Feltro • Isolante Termo Acústico • Camada Adesivada a Base d''água • Acompanha Kit de Presilha para Furos Originais do Capô • Corte a Laser Especifico para cada Carro • Preserva a Pintura do Capô • Diminui o Ruído do Motor • Antichamas • Excelente Qualidade e Resistência • Encaixe Sob Medida • Ideal para Reposição Conteúdo da Embalagem: • 01 Manta para Capô • 01 Kit com Presilhas de Fixação Importante: Garantia de 15 Dias Valor Unitário Imagens Reais do Produto', 165.11, 165.11, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-7reo3-m22jpex1to0t06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1040292502%2F23297982943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894879093', 'Dispenser Ou Quadrado 1,5L Linha Flow', 'ATENÇÃO, NÃO REALIZAMOS VENDAS PARA CNPJ Detalhes do produto • Capacidade de 1,5L para armazenar diferentes produtos de limpeza • Corpo transparente para visualização do nível interno. • Ideal para amaciante, sabão líquido, desinfetante e outras soluções • Facilita a organização e o controle do que precisa ser reposto Informações Técnicas Altura:27 cm Largura:10,5 cm Comprimento:11 cm Peso:0.248 kg Material:PS+SILICONE Capacidade:1,5L O Dispenser Quadrado Flow de 1,5L foi desenvolvido para tornar a rotina da lavanderia mais prática. Ele acomoda uma variedade de produtos de limpeza como amaciante, sabão líquido e desinfetantes, simplificando o dia a dia e deixando tudo visível. Seu corpo transparente permite acompanhar o nível de produto, garantindo mais controle e evitando surpresas durante as tarefas domésticas. Uma solução simples e elegante para quem busca fluidez e organização no cuidado com a casa. Cuidados Sugere-se higienizar com sabão neutro e esponja macia, evitando produtos abrasivos no processo de limpeza Conteúdo da embalagem 1 Dispenser Ou quadrado 1L Linha Flow', 54.9, 54.9, NULL, 'Home & Living > Home Organizers > Laundry Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-82613-mlc4j0o3nwn586', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1477305422%2F22894879093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
