INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41061641527', 'Livro Banho PJ Masks - Cores em Acao - Ciranda Cultural', 'DESCRIÇÃO PJ Masks – Cores em Ação é um livro de banho divertido e educativo com o universo dos personagens favoritos das crianças. Com apenas 6 páginas impermeáveis, permite que os pequenos brinquem durante o banho enquanto aprendem as cores e se divertem com figuras resistentes à água. Ideal para crianças entre 0 e 3 anos, combina aprendizado lúdico com segurança, sendo um presente leve (aproximadamente 50 g), resistente e fácil de limpar após o uso. Uma alternativa inteligente para estimular reconhecimento de cores enquanto a criança se diverte.', 18.93, 18.93, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md1yg3rzn7y97e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F41061641527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
