INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594270920', 'Piscina Inflável Infantil Round Sunset para bebês 61x22cm - Intex Oficial Brasil', 'Piscina Infantil 28 Litros 61x22 Cm Intex Promover a diversão dos pequenos é muito prazeroso e é exatamente isso que a BANHEIRA/ PISCINA INFLÁVEL DINOSSAURO/ URSINHO da marca Intex irá proporcionar ao seu filho/ filha em dias ensolarados na em casa ou praia. Ela é uma ótima opção para garantir a diversão das crianças e dos bebês, ideal para ser utilizada em casa, no jardim, na praia, no sítio ou em qualquer superfície lisa. Com capacidade para até 28 litros de água ou bolinhas, ela vai garantir momentos incríveis de diversão e alegria. Fácil de montar, fácil de transportar, pois a mesma pode ser inflada com a boca, não há necessidade de aparelhos de alta pressão. Produzida em vinil durável e uma base branca acolchoada. Acompanha kit reparo. É recomendada para crianças maiores de 1 ano. Torna as brincadeiras ainda mais divertidas!!!! CARACTERÍSTICAS: - Capacidade 28 litros - Vinil Resistente - Dimensões: 61cm x 22cm (Diâmetro 61 cm , Altura 22 cm) - 3 anéis - Forma redonda - ADESIVO PARA REPARO - Referência do produto: 57106Np - Certificado pelo INMETRO * É recomendada para crianças de 1 à 3 anos IMPORTANTE: Usar somente o nível de água onde a criança possa se manter de pé e não se esqueça que é sempre necessário que a brincadeira esteja sob a supervisão de um adulto. *** Pode ser usado como piscina de bolinhas ** ** Imagens ilustrativas, as cores e desenhos podem sofrer variações **', 119.9, 59.0, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcsoqo8yajoy50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1563768032%2F23594270920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
