INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12809896433', 'Brinco Argola Prata 925 Argolinha Feminino Médio 1.5g', 'Brinco Argola de Prata 925 média Feminino A argola de prata é um brinco que está sempre em alta devido à sua versatilidade para combinar com qualquer roupa e o seu preço sempre acessível! Essa argola tem aproximadamente 2cm de diâmetro e é feita totalmente de prata 925 Todas as nossas peças acompanham um certificado de garantia permanente do teor da prata Garantia: Não cobrimos oxidação, ou quebra do produto. Cobrimos apenas a prata 925. Como evitar o escurecimento da prata: 1. Evite utilizar a joia ao mexer com produtos químicos 2. Ao dormir, tire-a e enrole num papel higiênico 3. Armazene sua joia em um local seco e arejado 4. Não deixe a joia entrar em contato com cosméticos (perfumes, cremes, produtos ou procedimentos químicos do salão de beleza)', 20.9, 20.9, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljlnufdgtr4zdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316436073%2F12809896433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
