INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197662660', 'Kit Whey Iso-X 2kg + Creatina 100g + Bcaa 100g + Coqueteleira 700ml - XPro Nutrition', 'A creatina, conhecida por melhorar o desempenho nos treinos, é essencial para atletas, pois influencia na produção de energia e força. O BCAA é crucial para exercícios intensos, como musculação, por sua contribuição na síntese de glutamina e alanina. Suplementos proteicos em pó, como o whey protein isolado, oferecem benefícios como ganho de massa e força, com rápida absorção. Exemplos de ingredientes incluem proteína isolada do soro do leite, peptídeos bioativos e aromatizantes naturais.', 199.99, 199.99, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfvjanre6zno5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F983753255%2F19197662660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52754685480', 'Chaleira Wood 2,5 Litros Preta Em Aço Inoxidável Mor Cor Preto', 'Chaleira Inox 2,5 Litros Preta A Chaleira Wood 2,5L combina beleza, funcionalidade e segurança para sua cozinha. Fabricada em aço inox, é livre de resíduos nos alimentos, oferecendo durabilidade e resistência. Possui sistema de aviso sonoro que indica quando a água está quente, prevenindo a fervura excessiva e a evaporação. A alça, feita em baquelite, não conduz calor, garantindo segurança no manuseio. Com acabamento que imita madeira, apresenta um gatilho na alça para abrir a tampa do bocal, facilitando o uso sem contato com partes quentes. Disponível em cores preta e bege, adapta-se a diversos estilos de cozinha.', 180.0, 89.47, NULL, 'Home & Living > Dinnerware > Jugs, Pitchers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825zt-mjhg1bvqywp0df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1404215442%2F52754685480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
