INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093263097', 'Sandália Mississipi de Salto Baixo MB202', 'Produto marca Mississipi. A Sandália Mississipi de Salto Baixo da coleção Primavera/Verão 2024 une praticidade, leveza e estilo e está disponível nas cores . Seu design minimalista e detalhes elegantes a tornam ideal para diversas ocasiões. Além disso, o salto baixo de 2 cm proporciona conforto ao caminhar, enquanto o bico quadrado confere um ar moderno e atual. Seu destaque fica por conta da tira larga sobre o pé, com aplicação de zíper metalizado decorativo e detalhe drapeado, que conferem um toque de sofisticação e atemporalidade, assim como as tiras macias sobre o pé e que envolve o calcanhar proporcionando o calce fácil, com detalhe de nó. Já o material sintético garante durabilidade, tornando-a ideal para o uso diário. a versatiliade desse modelo permite criar combinações para qualquer ocasião, garantindo praticidade e elegância! Peso: 0,549 kg Altura do salto: 2,0 cm', 129.9, 119.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mlwg6r55ssgfdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23093263097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599456195', 'Sabonete em barra cremoso Natura Ekos Castanha 100g', 'Limpeza que nutre e hidrata a pele suavemente. Com óleo de castanha, este sabonete em barra cremoso limpa delicadamente a pele enquanto hidrata. A espuma cremosa forma uma camada protetora no corpo, deixando-o macio, aveludado e perfumado. Benefícios: • Rico em ômega-6 e ômega-9, nutre a pele estimulando a produção de proteínas estruturantes até as camadas mais profundas; • Limpeza profunda respeitando o ph natural da pele e muita maciez. Conteúdo: 100g', 13.3, 13.3, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-820n3-mnk6842jx2x079', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F22599456195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
