INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999839768', 'Sapólio Radium Cremoso Cloro 450 ml', 'Modo de uso: Aplique o produto com pano macio e úmido ou com o lado macio da esponja e esfregue.Depois, remova-o completamente. Conservação: Mantenha o produto em sua embalagem original.Manter o frasco fechado. Sapólio Radium Cremoso limpa e renova o brilho sem riscar. Ideal para limpar superfícies esmaltadas, cromadas, fórmicas, panelas e muitas outras. Sapólio, Sapólio Cremoso, Bombril. Dá brilho.Não risca.Limpa.', 28.68, 23.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-820ly-mmvwetzhyjgie7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1506316714%2F20999839768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
