INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399514385', 'Tênis Feminino Casual Chunky Ramarim 2380104', 'Tênis Feminino Casual Plataforma Fly High: Moderno e cheio de personalidade, este tênis feminino Fly High é a escolha perfeita para quem busca conforto e estilo em um único calçado. O visual robusto da sola plataforma acompanha as principais tendências da moda, proporcionando um look urbano e versátil. Desenvolvido com materiais leves e resistentes, conta com forro bactericida que auxilia na redução da proliferação de bactérias e odores, mantendo os pés mais frescos e confortáveis. O acabamento sofisticado e os detalhes exclusivos da marca garantem um visual contemporâneo, ideal para compor produções casuais e despojadas. A sola plataforma com aproximadamente 4 cm oferece leve elevação, mais estabilidade e conforto durante a caminhada. Possui fechamento por cadarço, proporcionando melhor adaptação aos pés e maior firmeza ao caminhar. Principais características: Forro bactericida; Fechamento por cadarço; Solado plataforma leve e resistente; Altura aproximada do solado: 4 cm; Palmilha confortável; Excelente estabilidade ao caminhar; Design casual e moderno. Combina perfeitamente com jeans, leggings, shorts, vestidos e conjuntos casuais, sendo ideal para passeios, trabalho, viagens e atividades do dia a dia. Conservação: Limpar com pano macio levemente umedecido. Secar à sombra e armazenar em local seco e arejado. Palavras-chave: Tênis feminino Fly High, tênis plataforma feminino, tênis casual feminino, tênis confortável feminino, tênis preto feminino, tênis urbano feminino, tênis moderno feminino, tênis para dia a dia, tênis com cadarço feminino, calçado feminino casual.', 269.9, 249.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820l9-mqytfk26p8925a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1011144984%2F23399514385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
