INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54558018876', 'BANCO BIKELETE MOBILETE XR COM PRESILHA + CANOTE 16CM', '🚴‍♂️ BANCO BIKELETE XR – PRATICIDADE E RESISTÊNCIA O Banco Bikelete Mobilete XR com presilha e canote 16 cm é ideal para quem busca resistência, praticidade e instalação rápida em bikes, mobiletes e projetos personalizados. Com estrutura reforçada e fixação direta no canote, proporciona firmeza e segurança durante o uso, sendo uma excelente opção para reposição ou montagem. Seu design compacto é perfeito para uso urbano, bikelete e aplicações específicas. 🔧 PRINCIPAIS BENEFÍCIOS • Acompanha canote 16 cm + presilha • Estrutura resistente e durável • Fácil instalação • Design compacto • Ideal para bikelete, mobilete e projetos 📌 ESPECIFICAÇÕES TÉCNICAS Tipo: Banco com canote Comprimento do canote: 16 cm Fixação: Presilha integrada Material: Base resistente com revestimento sintético Cor: Preto (variações conforme lote) Aplicação: Bikelete / mobilete / bicicleta 🔗 COMPATIBILIDADE ✔ Bikelete e mobilete ✔ Bicicletas adaptadas ✔ Projetos personalizados 📦 CONTEÚDO DA EMBALAGEM • 1 Banco com canote 16 cm • Presilha de fixação ❗ INFORMAÇÕES IMPORTANTES • Produto novo e pronta entrega • Acompanha nota fiscal • Verificar compatibilidade antes da compra ❓ FAQ – DÚVIDAS FREQUENTES Já vem com canote? Sim. Acompanha canote de 16 cm. Serve em bicicleta comum? Somente se for compatível com esse tipo de fixação. É resistente? Sim. Estrutura reforçada para uso diário. É fácil de instalar? Sim. Instalação simples e rápida. RM BIKES', 82.38, 82.38, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-820l6-mmhvubce7htw3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369650932%2F54558018876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
