INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697756842', 'Chaleira A5 Silver 2,5L Fundo Duplo', 'Com design moderno e inovador, a Chaleira Silver 2,5 litros agrega mais requinte e estilo à sua cozinha. Produzida em aço inox, material de grande resistência, ela possui longa durabilidade e é de fácil limpeza, garantindo mais higiene para sua família. A alça é elaborada em baquelite. Características: Capacidade 2,5 litros Cabo baquelite Com apito Fundo duplo Material Aço inoxidável Indicação de uso: Para fogões elétricos, gás, indução e a lenha. Dimensões: Altura: 20 cm Largura: 23,5 cm Profundidade: 18,5 cm Peso: 0,46 kg Garantia do fornecedor de 6 meses Recomendações do fabricante: Para melhor conservação e durabilidade do produto, antes do primeiro uso, lave com uma esponja macia, enxague e seque a peça. Não usar abrasivos para limpeza. Cozinhe em temperaturas baixas ou médias para melhor distribuição de calor. Evite esquentar o produto vazio. Resfrie o produto antes de lavar. Não levar ao micro-ondas. Pode ser lavado em lava louças.', 99.9, 69.9, NULL, 'Home Appliances > Kitchen Appliances > Kettles', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-lzor6ph1yb6w33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22697756842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41728388824', 'Kit 10 Discos Flap Lixa Speedmax 115mm 4.1/2 Grão 40, 60, 80 ou 120', 'Disco Flap Speedmax 115mm (4.1/2") - Kit com 10 Unidades Garanta o melhor rendimento para seus trabalhos de desbaste e acabamento. Este disco flap é desenvolvido com base reta em fibra e conta com 72 folhas de lixa, proporcionando uma vida útil prolongada e um excelente custo-benefício para profissionais e hobbistas. Ideal para: - Aço e Inox - Metais não ferrosos - Plásticos, lacas e madeira - Uso em serralherias e manutenção industrial Especificações Técnicas: - Diâmetro: 115mm - Furo: 22,23mm - Quantidade de lixas: 72 folhas (maior durabilidade) - Perfil: Reto (costado de fibra) ⚠️ Informações Importantes sobre o Pedido: Venda em Kit: O anúncio refere-se ao kit com 10 unidades. Grãos Disponíveis: Escolha entre os grãos 40, 60, 80 ou 120 no momento da compra. Regra de Quantidade: Não é personalizável. O kit é fechado com 10 unidades do mesmo grão. Não fracionamos quantidades diferentes (ex: 5 de um e 5 de outro) dentro do mesmo kit. Dica: Selecione o grão desejado antes de finalizar o pedido para garantir o envio correto! Precisa de mais de um tipo de grão? Adicione os kits desejados individualmente ao seu carrinho de compras.', 52.48, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjzsnebownpcc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064710210%2F41728388824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597774076', 'Fogão 5 Bocas Dako Magister Acendimento Automático', 'Fogão Dako Magister conta com Design moderno, sofisticado e elegante, com design Full Glass, cantoneiras em Inox e puxador em alumínio escovado. Trempes Duplas de Piatina trazem estabilidade e facilidade de transição das panelas entre os queimadores. Com 2 prateleiras, 1 deslizante e 1 auto deslizante. A prateleira inferior auto deslizante facilita a retirada dos alimentos e a prateleira superior com altura ajustável. Forno de 100 litros grande capacidade para preparar receitas para a família toda. Vidro do forno com ampla visão e o acendimento automático, praticidade, rapidez e segurança ao cozinhar. Características: Mesa - Inox Trempe - Dupla de Piatina Acendimento - Automático Tampa mesa - Tampa de Vidro Posição manípulos - Top Control Manipulador removível 5 Queimadores Queimadores - Alumínio com capa esmaltada Tripla/Dupla Chama - 1 Queimador x 3,3 kW Rápido - 2 Queimadores x 2,0 kW Semi-Rápido - 2 Queimadores x 1,7 kW Potência 10,7 kW Capacidade Forno 100L Alimentação - Gás Potência Forno 2,65kW Acabamento Interno do Forno - Esmalte Limpa Fácil Prateleiras - 1 Deslizante e 1 Autodeslizante Luz no Forno Vidro porta do forno - Vidro duplo temperado Puxador - Alumínio escovado Visor porta do forno Válvula de segurança do forno Dimensões: Altura: 96 cm Largura: 76 cm Profundidade: 63,3 cm Peso: 37,70 kg Garantia do fornecedor de 12 meses', 2099.9, 1879.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdww-m009ppglvxjw9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22597774076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
