INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42356272666', 'Cinta Térmica Santa Clara Abdominal - St3', 'Cinta Térmica ST3 Santa ClaraA cinta térmica abdominal Santa Clara é a solução ideal para quem busca redução de medidas, tratamento de gordura localizada, combate à celulite e flacidez. Comprovadamente eficaz, esse produto revolucionário proporciona resultados visíveis em pouco tempo. Atributos do Produto:Marca: Santa Clara Modelo: Cinta Térmica Manta Elétrica Abdominal E Quantidade de Itens: 1 Kit: Não Benefícios da Cinta Térmica ST3:A Cinta Térmica ST3 da Santa Clara é um verdadeiro aliado na busca por um corpo mais saudável e tonificado. Confira alguns dos benefícios que você terá ao adquirir este produto inovador: 1. Redução de MedidasA tecnologia avançada da cinta térmica ST3 estimula a queima de gordura localizada, auxiliando na redução de medidas de forma eficaz e duradoura. 2. Combate à CeluliteAumentando a temperatura local, a cinta térmica contribui para a melhora da circulação sanguínea, reduzindo a aparência da celulite e promovendo uma pele mais lisa e firme. 3. Tratamento de FlacidezAo promover o aumento da absorção dos produtos aplicados na região abdominal, a cinta térmica ST3 ajuda a combater a flacidez, tonificando a pele e proporcionando um aspecto mais jovem e saudável.', 114.46, 96.52, NULL, 'Home & Living > Hand Warmers, Hot Water Bags & Ice Bags', 'https://cf.shopee.com.br/file/sg-11134201-82626-mk2gwt0q2mfccc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1186779187%2F42356272666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42124814401', 'Bíblia Sagrada | ARC | Letra Mega Gigante | Capa Luxo Preta', 'Apresentamos a Bíblia Sagrada, com edição pensada para enriquecer sua experiência espiritual. Essa bíblia possui a renomada tradução Almeida Revista e Corrigida (ARC), uma versão que oferece a compreensão clara e profunda das palavras sagradas, revelando o poder da mensagem divina em cada versículo. Característica: Idioma: Português Acabamento: Capa Flexível em material Couro Soft Medida: 17×24 Páginas: 2.207 ISBN: 9786583094360 Letra Mega Gigante', 140.9, 140.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mfyba6k9uex49b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F42124814401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255952289', 'Jogos Raios Biz 125 110 Dianteiro E Traseiro Inox 3,5mm Allen', 'Raio INOX Allen 3,5mm ( Apenas para Freio a Tambor) Algumas aplicações: Biz 110 Biz 125 Acompanha: Raio Allen INOX 3,5mm (Freio a Tambor) Os Raios Allen são uma opção elegante e de fácil instalação Eles oferecem durabilidade e estilo, melhorando a experiência de pilotagem. Esses raios proporcionam resistência excepcional, estabilidade e tranquilidade durante a pilotagem, tornando-se a escolha ideal para os motociclistas que valorizam segurança e confiabilidade em suas viagens. O QUE VOCÊ IRÁ RECEBER: - 02 Jogos Raio Allen INOX 72 unidades Total BENEFÍCIOS DO PRODUTO: - Melhora a performance - Aumenta a durabilidade - Segurança e confiabilidade - Estilo e aparência AÇO INOX ENFERRUJA? Muitas pessoas se questionam se de fato o aço inox enferruja. De certa forma a resposta é sim, já que esse tipo de metal pode sofrer algum tipo de corrosão. Sobretudo, sob o contato abundante de água ou algum outro tipo de agente agressivo. De qualquer maneira, a possibilidade do material ser comprometido é bem pequena. Isso acontece devido os componentes de sua estrutura. O aço inox é constituído por uma combinação entre cromo e ferro. Essa mistura resiste com mais intensidade a ação de agentes corrosivos. Contudo, não impede totalmente que o material sofra algum tipo de desgaste com o tempo. Afinal, em alguns casos, o material pode apresentar falhas microscópicas em sua composição, ocasionando pequenas corrosões Inter cristalinas. Por isso é fácil constatar a diferença entre os tipos de aço. CARACTERÍSTICAS DO PRODUTO: - Durabilidade - Resistência excepcional - Fácil instalação - Design elegante ESPECIFICAÇÕES: Marca: Allen Material: Aço Inox Espessura: 3.5mm Jogos com 36 unidades Cada 36 raios dianteiro ou Traseiros ------------------------------------------------------------------------------------------------------ Ficou com alguma dúvida ? Faça uma pergunta ! Verifique a compatibilidade com sua moto com o produto antes de efetuar a compra. Não nos responsabilizamos por instalações mal realizadas Garantia de 3 Meses Contra Defeito de Fabricação', 164.9, 164.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-820mg-ml7rbbagz9qdec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F58255952289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
