INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099014000', 'Ring Light 6 Polegadas com Tripé 48 LEDs Luz Fria Quente Morna Dobrável Controle Remoto Oberon OR-1686', 'Ring Light Oberon OR-1686 foi desenvolvida para quem busca qualidade, praticidade e estilo na hora de criar conteúdos com boa iluminação. Compacta, leve e fácil de transportar, conta com rotação de 360°, sendo ideal para fotos e vídeos em diversos ângulos. Possui 3 modos de luz (branco frio, branco quente e branco morno), controle remoto para ajustes rápidos e entrada micro USB para carregamento. Com 48 LEDs distribuídos entre luz quente e fria, proporciona uma iluminação equilibrada e eficiente. Disponível em quatro modelos criativos, combina desempenho com um visual moderno. ESPECIFICAÇÕES: - Modelo: OR-1686 - Marca: Oberon - Entrada: micro USB - Temperatura da cor: 3000K - 6500K - Diâmetro: 6 polegadas - LEDs: 48 unidades (24 branco quente / 24 branco frio) - Potência de LED: 0.2W cada - Rotação: 360° - Altura mínima: 21,5 cm - Altura máxima: 78,5 cm - Dimensões do produto: 22,3 x 17,2 x 7,0 cm CONTEÚDO: 01 Ring Light 01 Tripé 01 Controle Remoto', 83.99, 58.79, NULL, 'Mobile & Gadgets > Accessories > Selfie Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824hf-mfmv0azkd62w36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23099014000', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
