INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18171867349', 'Caneleira Penalty Matis Juvenil X', 'Acompanha 1 par! Evite lesões durante as partidas com a Caneleira Penalty Matis Juvenil X. Seu corte e design é destinado para futebol de campo, society ou futsal. O modelo é perfeito para os futuros craques não fugirem dos confrontos e mostrarem suas habilidades dentro das quatro linhas. Benefícios: Evita lesões durante os choques. Diminuição de impactos. Formato perfeito para as 3 modalidades. Alguns diferenciais técnicos: A Caneleira Penalty Matis Juvenil X conta com a tecnologia Shield Sys garantindo maior proteção durante os impactos e interior com EVA resistente para garantir mais conforto durante o uso.', 24.99, 24.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rblq-llpfsf8rqna1af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F18171867349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22824216348', 'Soquete Estriado Para Chave Catraca Aço Cromo Vanádio Torque Encaixe 1/Pol. 08 - 32mm Profissional', 'COMERCIAL VIPASA DISTRIBUIDORA. Soquete Estriado Para Chave Catraca Aço Cromo Vanádio Torque Encaixe 1/Pol. 08 - 32mm Profissional Soquete Para Chave Catraca Estriado Aço Cromo Vanádio Torque Encaixe 1/2" 08 ao 32mm Profissional ANÚNCIO REFERENTE A UMA VARIAÇÃO DE SOQUETES COM ENCAIXE DE 1/2POL DISPONÍVEL EM VÁRIOS TAMANHOS ESCOLHA NAS VARIAÇÕES DO ANÚNCIO AS MEDIDAS DE SOQUETES DESEJADAS Soquete Estriado Aço Cromo Vanádio Encaixe 1/2" 08 ao 32MM Soquete pode se utilizado junto a cabo de força, catraca, torquímetros, por ser uma ferramenta compatível com várias outras, torna-se a multiuso ideal para qualquer oficina, marcenaria, indústria. O encaixe do soquete é de 1/2" Polegadas e seu revestimento é de níquel-cromo polido e é projetado para montagem de conexões, parafusos, porcas e parafusos. Modelo: Estriado Tamanhos: • 08 MM • 09 MM • 10 MM • 11 MM • 12 MM • 13 MM • 14 MM • 15 MM • 16 MM • 17 MM • 18 MM • 19 MM • 20 MM • 21 MM • 22 MM • 23 MM • 24 MM • 26 MM • 27 MM • 28 MM • 30 MM • 32 MM Os soquetes estriados para chave catraca com encaixe de 1/2 polegada fabricados em cromo vanádio são ferramentas utilizadas em trabalhos mecânicos e de manutenção. Abaixo, descrevo alguns aspectos relevantes sobre esses soquetes: Material: Cromo vanádio é um tipo de aço resistente e durável, conhecido por sua capacidade de suportar impactos e pela resistência à corrosão. Isso torna os soquetes ideais para uso em ambientes desafiadores. Encaixe: O encaixe de 1/2 polegada é uma medida padrão e se refere ao tamanho da extremidade quadrada do soquete, que se conecta à catraca ou a outras ferramentas. Essa medida é comumente usada em conjuntos de ferramentas automotivas e industriais. Estriação: A estriação se refere aos sulcos ou ranhuras na parte interna do soquete, projetados para se encaixar perfeitamente em porcas e parafusos. Essa característica proporciona uma aderência firme e reduz o risco de escorregamento durante o uso. Utilização com Chave Catraca: Os soquetes estriados são frequentemente usados em conjunto com chaves catracas. A chave catraca é uma ferramenta manual ou elétrica que permite apertar ou soltar parafusos e porcas de forma mais eficiente, sem a necessidade de retirar a ferramenta a cada movimento. Acabamento Cromado: A camada cromada na superfície do soquete não apenas proporciona um visual mais atraente, mas também protege contra a corrosão, aumentando a vida útil da ferramenta. Marcas e Tamanhos: Esses conjuntos de soquetes geralmente vêm em kits que incluem uma variedade de tamanhos, permitindo que o usuário escolha o soquete adequado para a aplicação específica. Esses soquetes são essenciais em oficinas mecânicas, indústrias e para entusiastas de automóveis que realizam trabalhos de manutenção e reparo. Eles oferecem versatilidade e durabilidade, sendo peças-chave em uma caixa de ferramentas para uma variedade de aplicações. COMERCIAL VIPASA DISTRIBUIDORA.', 16.99, 16.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-23020-9ugl3nca9inv26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F22824216348', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792936736', 'Tampa Estribo Tapa Chinelo (par) Caminhão Vw Constellation', 'PECA NOVA , COM NF, PLASTICO ABS INJETADO PREMIUM DE ALTA RESISTENCIA. APLICADO EM TODOS OS MODELOS CAMINHÕES CONSTELLATION - MATERIAL PLASTICO ABS DE ALTA DURABILIDADE E PERFORMANCE PRECO REFERENTE AO PAR TAMPA ESTRIBO VW CONSTELLATION TODOS - Par Tampa estribo ou tapa chinelo do 1º Degrau VW Constellation - MODELOS CABINE ALTA OU CABINE BAIXA TODOS - Peça fabricada em plástico - Produto 100% novo e com ótimo acabamento - Valor referente ao par, 2 unidades TAPA CHINELO CONSTELLATION 02 / 03 DEGRAUS - UNIVERSAL PECA VEM PARA PINTURA - NAO VEM EM COR DEFINIDA A DEPENDER LOTE PRODUCAO - SEMPRE EM PLASTICO ABS', 330.22, 330.22, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5edakmu624wbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1219395689%2F23792936736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20528004283', 'Marmita Com Alça Presilhas Plástico Tekcor 1,5L Sem Divisórias Cinza Claro - SOPRANO Original', 'COMERCIAL VIPASA DISTRIBUIDORA.Marmita Térmica Com Alça Presilhas Plástico Tekcor 1,5L Sem Divisórias Cinza Claro - SOPRANOMarmita Térmica Com Alça Presilhas Tekcor 1,5L Sem Divisórias Cinza Claro SopranoMarmita térmica Alça com Presilhas Tekcor 1,5 litros sem Divisórias Soprano Cinza ClaroA mais tradicional e popular marmita do mercado, atendendo suas necessidades na medida certa. Muito utilizado em ambientes corporativos, construção civil, agricultura ou até mesmo no dia-a-dia para buscar comida em restaurantes. Conserva os alimentos em temperatura ideal para consumo. Possui presilhas para fechamento e alça robusta para transporte. Pode ser utilizado no micro-ondas (sem a tampa)Capacidade 1,5 litros.Isolamento térmico em EPS. Livre de Bisfenol (BPA Free).Características:Eficiência Térmica:- Quente: 4 horas- Frio: 4 horasDicas e Instruções de uso:- Lavar o produto antes de utilizar;- Nunca armazenar alimentos por um período prolongado;- Quanto maior a quantidade de alimento, maior será o tempo de conservação da temperatura;- Alimentos como feijão, arroz, massas, purês, alimentos mais consistentes favorecem a conservação de temperatura, principalmente se o produto estiver cheio;- Alimentos como verduras, frutas, favorecem uma menor conservação de temperatura, mas podem ser armazenados sem nenhum problema;- Não leve ao forno ou ao fogo;- Não utilizar objetos abrasivos como esponja de aço ou similares para sua limpeza;- Limpeza interna: se houver cheiro em seu interior, lave-o com água e sabão neutro. Posteriormente, deve-se encher o produto com uma solução de água com uma colher de sopa de Bicarbonato de Sódio;- Limpeza externa: deve ser realizada com sabão, ou detergente, esponja e água.- Usar de acordo com as instruções do fabricante.Foto Original do ProdutoCOMERCIAL VIPASA DISTRIBUIDORA.', 34.99, 29.89, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltwcdxke5r34a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F20528004283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47511760614', 'Boneco Squishy Woody ou Buzz Lightyear Toy Story Antiestresse Sortido e Unitário Toyng - 059498', '*Produto sortido e unitário, será enviado de acordo com a disponibilidade em estoque. O Boneco Squishy Woody ou Buzz Lightyear Toy Story da Toyng é perfeito para fãs do clássico universo Disney Pixar. Inspirado no icônico personagem Woody ou Buzz Lightyear, este brinquedo combina diversão, colecionismo e entretenimento em um formato macio e agradável ao toque. Fabricado em borracha squishy de alta qualidade, o boneco pode ser apertado e retorna lentamente ao formato original, proporcionando uma experiência sensorial divertida e relaxante. Seu design detalhado reproduz as principais características do famoso cowboy de Toy Story ou o astronauta Buzz Lightyear, tornando-o ideal para brincar, decorar ou colecionar. Licenciado oficialmente pela Disney Pixar, o produto é indicado para crianças e colecionadores que desejam levar um dos personagens mais queridos da animação para o dia a dia. Uma excelente opção para presentear fãs da franquia. Destaques: - Produto oficial licenciado Disney Pixar - Personagem Woody ou Buzz Lightyear de Toy Story - Borracha squishy macio e agradável ao toque - Retorna lentamente ao formato original - Ideal para brincar e colecionar - Auxilia em atividades sensoriais - Excelente opção para presente Características: - Marca: Toyng - Modelo: 059498 - Licença: Disney Pixar - Personagem: Woody ou Buzz Lightyear - Linha: Squishy - Material: Borracha Squishy - Tipo: Boneco antiestresse - Idade recomendada: A partir de 3 anos Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 01 Boneco Squishy Woody ou Buzz Lightyear Toy Story', 36.0, 32.28, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-823ob-mp41w5j7l88w4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F47511760614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191414018', 'Eico Pro Óleo Sublime Reparador Shampoo e Condicionador + Máscara Tratamento + Finalizador Leave-in', 'Contém: 1- Shampoo Óleo Sublime Eico Professional 300ml 1- Condicionador Óleo Sublime Eico Professional 300ml 1- Máscara Tratamento Óleo Sublime Eico Professional 300ml 1- Leave-in Finalizador Óleo Sublime Eico Professional 200ml Sem Sal, Sem Parabenos, Sem Petrolatos, Sem Corante - Linha Liberada A linha Óleo Sublime Eico Professional foi desenvolvida para aqueles cabelos quimicamente tratados e cabelos naturais, ótima nutrição para cabelos que estão sem vida, ressecados e sem brilho. Ativos: Pro Elixir Complex, Óleo de Argan, Marula e Abacate Shampoo :Com o cabelo úmido, aplique uma pequena quantidade do Shampoo Óleo Sublime sobre a palma das mãos e massageie suavemente por toda a extensão dos fios, da raiz até as pontas. Enxágue completamente e repita a operação. Remova todo o produto dos fios. Para um melhor resultado utilize a linha completa de tratamento EICO PROFESSIONAL Óleo Sublime. Tratamento:Após lavar o cabelo com o shampoo EICO PROFESSIONAL Óleo Sublime 300g. Enxágue completamente, retire o excesso de água com uma tolha. Aplique uma pequena quantidade do tratamento EICO Óleo Sublime sobre a palma das mãos e massageie suavemente por toda a extensão dos fios evitando a raiz. Enluve mecha por mecha e deixe agir por 10 minutos. Enxágue completamente. Utilize o tratamento ao menos uma vez por semana. Para um melhor resultado utilize a linha completa de tratamento EICO Óleo Sublime. Condicionador :Após lavar o cabelo com o shampoo EICO Óleo Sublime. Enxágue completamente e retire o excesso de água com uma tolha. Aplique uma pequena quantidade do condicionador EICO Óleo Sublime sobre a palma das mãos e massageie suavemente por toda a extensão dos fios evitando a raiz. Enluve mecha por mecha e deixe agir por 3 minutos. Enxágue completamente. Para um melhor resultado utilize a linha completa de tratamento EICO Óleo Sublime. Leave-in: Modo de usar:Sobre os fios limpos, secos ou úmidos, borrife o spray por todo o comprimento e pontas, mas evite a raiz. Penteie o cabelo, modele e finalize como preferir. ResultadoFios controlado, com menos volume, macios, hidratados e sem frizz', 294.6, 159.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rblh-lmrl781zwgcwe9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385344228%2F23191414018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18272218469', 'Torneira Plástico Bica Alta Móvel Bancada Cozinha 1/4 De Volta Abs Cromado Para Pia Lavabo Lavatório', 'COMERCIAL VIPASA DISTRIBUIDORA Torneira Plástico Bica Alta Móvel Bancada Cozinha 1/4 De Volta Abs Cromado Para Pia Lavabo Lavatório DESCRIÇÃO DO PRODUTO: A Torneira Bica Alta Móvel de Bancada para Cozinha com acionamento de 1/4 de volta em ABS Cromado é um dispositivo utilizado em ambientes de cozinha para fornecer água potável para uso doméstico. Fornecimento de Água Potável: A principal função da torneira é fornecer água potável para uso em tarefas domésticas, como lavar louças, alimentos, utensílios de cozinha e as mãos. Design de Bica Alta Móvel: O design de bica alta móvel permite maior flexibilidade e alcance ao redor da pia, facilitando o enchimento de recipientes grandes e a lavagem de itens volumosos, como panelas e travessas. Acionamento de 1/4 de Volta: O mecanismo de acionamento de 1/4 de volta proporciona maior praticidade e facilidade de uso. Com um simples giro de 90 graus, a torneira pode ser ligada ou desligada, controlando o fluxo de água de forma rápida e eficiente. Material em ABS Cromado: O corpo da torneira é fabricado em ABS cromado, um material durável, resistente à corrosão e de fácil limpeza. O acabamento cromado confere um aspecto estético moderno e elegante à torneira, combinando com diversos estilos de decoração de cozinha. Instalação na Bancada: A torneira é instalada diretamente na bancada da pia da cozinha, proporcionando uma conexão segura e estável para o fornecimento de água. Versatilidade: Além de ser utilizada em cozinhas residenciais, essa torneira também pode ser instalada em cozinhas comerciais, restaurantes, lanchonetes e outros ambientes onde seja necessária uma torneira robusta e eficiente. Economia de Água: Alguns modelos podem vir equipados com aerador integrado, que ajuda a economizar água ao misturá-la com ar, mantendo a pressão e o fluxo adequados, mesmo com menor consumo. Fácil Manutenção: A torneira de bica alta móvel é projetada para facilitar a manutenção e a substituição de peças, caso necessário, garantindo assim uma vida útil prolongada do produto. A Torneira Bica Alta Móvel de Bancada para Cozinha com acionamento de 1/4 de volta em ABS Cromado é um dispositivo essencial em ambientes de cozinha, fornecendo água potável de forma eficiente, conveniente e esteticamente agradável. Torneira Bica Alta Móvel Bancada Cozinha 1/4 De Volta Abs Cromado Características do produto: • Jato uniforme, proporciona economia de água. • Bica móvel. • Mecanismo de vedação 1/4 volta com pastilha cerâmica. • Embalagem: saco plástico. Material: em ABS. COMERCIAL VIPASA DISTRIBUIDORA', 38.99, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-23020-vs4sv6jq21mvad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F18272218469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598777111', 'Capa Para Retrovisor para - Cód. 963732329R', 'Somos concessionária autorizada Renault e trabalhamos exclusivamente com peças genuínas Renault. Todas as peças são novas, originais de fábrica, acompanham nota fiscal e possuem garantia. Compre com segurança, procedência garantida e atendimento especializado. Por se tratar de peça original Renault, eventuais atendimentos de garantia podem ser realizados em qualquer concessionária autorizada Renault do Brasil, conforme as condições do fabricante. ITENS INCLUSOS: 1 capa para retrovisor; PRINCIPAIS BENEFÍCIOS: Proteção contra arranhões; Fácil instalação; Design moderno e elegante; DESCRIÇÃO: Proteja o retrovisor do seu Renault com a Capa Para Retrovisor 963732329R. Fabricada com materiais de alta qualidade, essa capa é resistente e durável, proporcionando proteção contra riscos, arranhões e pequenos danos. Além de preservar a integr GARANTIA: 3 meses Antes de realizar a compra, verifique cuidadosamente se a peça é compatível com o seu veículo, considerando modelo, ano e versão. Em caso de dúvida, utilize o campo de perguntas e, se desejar, envie o número do chassi. Nossa equipe poderá consultar e confirmar a compatibilidade da peça com o seu veículo antes da compra.', 116.1, 116.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-mctd8w2xclsec6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1582641115%2F22598777111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293501177', 'Conjunto De Facas 6 Peças Ralador Tesoura Rosa Premium', 'COMERCIAL VIPASA DISTRIBUIDORA. Conjunto Facas De Cozinha Inox 6 PcsSeja bem-vindo(a) ao nosso canal de vendas!Temos como objetivo a satisfação de nossos clientes e a missão de atender bem, trabalhando com profissionalismo nas vendas e no atendimento. Proporcionando assim uma ótima experiencia de compra!Tenha em sua cozinha um kit completo de facas contando com 4 facas, 1 ralador e 1 tesoura com abridor de latas e quebra-nozes. Com este kit você terá cortes rápidos e precisos graças a suas laminas afiadas feitas em aço inoxidável, facilitando no preparo de carnes, peixes, saladas e frutas. Além de tudo, as facas deste kit contam com cabo de alta aderência para melhor manuseio!!ITENS INCLUSOS: - 1 Cutelo Pequeno 8"- 1 Faca Chefe 8"- 1 Faca de trinchar 8"- 1 Faca de aparar 3,5"- 1 Descascador De Alimentos- 1 Tesoura de cozinhaCARACTERISTICAS:- Feito em aço inoxidável- Design moderno- Cabo com boa aderência- Alta resistência e durabilidade- Ideal para cortes de carnes, peixes, saladas e frutas- Tesoura com abridor de latas e quebra-nozes COMERCIAL VIPASA DISTRIBUIDORA.', 84.99, 84.99, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/sg-11134201-7reo7-m1znns6lu58g49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F23293501177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40679662729', 'Copo To Go 400ml Zona Criativa (Escolha o Tema) - Mickey - Sonic - One Piece - Harry Potter - Kuromi', 'O Copo To Go 400ml é ideal para quem busca praticidade, estilo e eficiência no dia a dia. Produzido em aço inoxidável com parede dupla, ele ajuda a manter a temperatura da bebida por mais tempo, sendo perfeito para acompanhar sua rotina em qualquer lugar. Compacto e funcional, possui tampa com vedação que evita vazamentos e sistema de bico duplo com canudo, permitindo escolher a melhor forma de consumo. Além disso, conta com alça para transporte, facilitando o uso em atividades diárias como trabalho, escola, viagens ou lazer. Seu design moderno e resistente garante durabilidade e conforto, sendo uma excelente opção para quem precisa de um copo versátil para bebidas quentes ou frias. Especificações: Capacidade: 400ml Material: Aço inoxidável e plástico Parede dupla: Sim Livre de BPA: Sim Altura: 12cm Largura: 8,5cm Comprimento: 8,5cm Diferenciais: Mantém a temperatura por mais tempo Tampa com vedação para evitar vazamentos Bico duplo com canudo Alça para transporte Compacto e fácil de levar na bolsa ou mochila Ideal para uso diário Cuidados e recomendações de uso: Não colocar na geladeira ou congelador Não utilizar em micro-ondas ou lava-louças Lavar com água, esponja macia e sabão neutro Não utilizar produtos abrasivos Evitar quedas ou impactos Variações disponiveis: - Mickey - Sonic - One Piece - Harry Potter - Kuromi Características: Marca: Zona Criativa Produto importado Conteúdo da embalagem: - 01 Copo To Go 400ml (escolha o personagem)', 119.53, 107.58, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-8260r-mmhti26612bm88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F40679662729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12046361642', 'Ração Úmida Sachê Special Dog Frango Ao Molho - 100G', 'Idade: Adulto Pet: Cachorros Porte de Raça: Pequeno, Gigante, Mini, Grande e Médio Sabor: Frango Tipo: Ração úmida Apresentação: Disponível em embalagem de 100g Composição: Miúdos de suínos, miúdos de aves, carne bovina, plasma sanguíneo suíno em pó, leite desnatado em pó, hemoglobina bovina em pó, gelatina, farinha de trigo, amido de milho, dextrose, proteína isolada de soja, proteína texturizada de soja, gordura de frango, celulose, levedura hidrolisada de cana-de-açúcar, farinha de algas Schizochytrium sp. (0,5%), extrato de Yucca schidigera, hidrolisado de fígado de frango e suíno, cloreto de sódio (sal comum), carbonato de cálcio, cloreto de potássio, água, glicina, vitaminas (A, B1, B2, B3, B5, B6, B7, B9, B12, C, D3, E e cloreto de colina), minerais quelatados (glicinatos: cobre, ferro, manganês e zinco), levedura enriquecida com selênio, iodato de cálcio, sulfato de cobre, sulfato de manganês, sulfato de zinco, goma guar, carragena, tripolifosfato de sódio, EDTA cálcio dissódico, BHA, BHT e corante natural caramelo', 5.56, 5.56, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/4d793c6f3b2400119b3ff86e8926db41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F12046361642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
