INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14033644271', 'Tonalizante sem Amônia Burguesinha Probelle 6.7 LOURO ESCURO MARROM probelle', 'TONALIZANTE BURGUESINHA ,DESCUBRA AS CORES VIBRANTES PROBELLE: Com 6 óleos essenciais e sem amônia, a burguesinha possui uma fórmula luxuosa e sofisticada, com altíssimo poder colorante. Enquanto você consegue a tonalidade dos seus sonhos, a burguesinha irá regenerar os fios, nutrindo-os em profundidade e devolvendo o movimento natural dos mesmos, além de prevenir o surgimento das pontas duplas e de fios ressecados e quebradiços. Cor muito mais viva, intensa e de longa duração. Cabelos ainda mais saudáveis e com um brilho impecável. ATIVOS; Tonalizante sem amônia e com óleos de Argan, Linhaça, Castanha Lótus, Girassol e Semente de Uva', 16.45, 16.45, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-22120-9lcft5ydtmlve6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F14033644271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799551807', 'Blue - Jurassic World Fallen Kingdom Iron Studios', 'Mais velha e única sobrevivente de seu bando, e desde filhote mais inteligente e astuta do que suas irmãs, a Velociraptor fêmea de pele cinza-azulada, marcada com uma característica faixa azul com contornos brancos que segue horizontalmente de sua órbita ocular até a ponta de sua cauda, como a última de sua espécie enfrenta o perigo iminente, na forma de um vulcão em erupção na abandonada Ilha Nublar. Em posição pronta para o ataque, a Iron Studios apresenta a estátua ?Blue - Fallen Kingdom - Art Scale 1/10?, sobre uma base com logotipo do filme no qual a carismática, e por vezes feroz, Raptor fêmea reencontra seu antigo treinador Owen Grady que a procura em uma missão de resgate.', 899.99, 899.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7req5-m28p2s3ejpq0df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191775191%2F19799551807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
