INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22230824271', 'Evangelhos | A história do Homem que Mudou a Historia', 'Evangelhos A história do homem que mudou a historia Os textos integrais dos 4 evangelhos na versão bíblica NVT (Nova Versão Transformadora) acompanhados de um estudo bíblico para sobre autoria, data, conteúdo, destinatários e propósito de cada um deles. Em duas cores. Título: Evangelhos Subtítulo: A história do homem que mudou a historia Acabamento: Capa dura Formato: 20,5 x 13,5 x 0,5 cm Paginas: 96 Capa: Cartão de 1.5 mm revestido de papel couché de 128 g/m2 Papel/miolo: Papel Offset 70 g/m2 Ano edição: 2020 Peso: 350g ISBN: 9781646410873 Editora: Pão Diário', 32.31, 32.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-5ansktymihov28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22230824271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499253866', 'Tênis Ocupacional de Segurança Antiderrapante EVA Flex Clean 103FCLEAN PR FV Marluvas', 'Sapato ocupacional impermeável, confeccionado em EVA, fita polimérica na tarela do calçado e solado antiderrapante. Cabedal: Confeccionado em material polimérico (EVA-Etil Vinil Acetato). OBS: Sem presença de Ftalatos, um conjunto de substâncias químicas restritivas prejudicais à saúde das pessoas, causando efeitos negativos ao Meio Ambiente e à Saúde Humana. Os Ftalatos estão associados à ocorrência de problemas reprodutivos em animais silvestres, em humanos os efeitos podem ser: surgimento de câncer de mama, desregulação hormonal e diminuição da fertilidade. Palmilha higiênica: em EVA composta de micropontos que proporcionam absorção e dessorção do suor. Aprovação NBR ISO 20347:2015. Características: Tênis Marca: Marluvas Modelo: 103FCLEAN-PR-FV-SC Referência: CA-48714 Produto Antiderrapante: Sim Conteúdo da Embalagem: 01 Tênis Ocupacional de Segurança Antiderrapante Marluvas Garantia do Fabricante: 06 meses (Contra defeitos de fabricação, contados a partir da data da emissão da nota fiscal).', 117.53, 117.53, NULL, 'Men Shoes > Boots > Safety Boots', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-luz9jgul2ks65f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395742608%2F20499253866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
