INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699245505', 'Coleção Amor de Filhote Vagabundo - Roma Jensen', 'Coleção Amor de Filhote Vagabundo - Roma JensenA coleção Amor de Filhote Vagabundo traz à vida o adorável Vagabundo, personagem icônico do universo Disney, em uma parceria exclusiva entre Roma e Disney. Com o alto padrão de qualidade da marca Roma e a magia dos clássicos da Disney, este boneco de vinil encantará crianças e colecionadores de todas as idades. Idade recomendada: A partir de 3 anos. Selo Inmetro: 008048/2019 - OCP0003. Diferenciais:Produto licenciado pela Disney, garantindo fidelidade aos detalhes do personagem. Fabricado em vinil resistente e seguro para crianças. Ideal para estimular a imaginação e criar histórias divertidas durante o brincar. Dimensões compactas, facilitando o transporte e armazenamento. Perfeito para presentear os fãs da Disney em todas as ocasiões. Mais sobre o Produto:O boneco de vinil da coleção Amor de Filhote Vagabundo é um item decorativo encantador para o quarto das crianças, além de promover o desenvolvimento criativo e emocional por meio do faz de conta. Perfeito para recriar cenas do filme ou inventar novas aventuras, proporcionando horas de diversão e entretenimento educativo. Dicas de Uso:Use o boneco para contar histórias e estimular a imaginação das crianças. Complemente a coleção Amor de Filhote Vagabundo com outros personagens da série. Crie um cantinho especial na estante ou prateleira dedicado aos colecionáveis Disney. Limpe o boneco regularmente com um pano macio e úmido para mantê-lo sempre impecável. Ficha Técnica:Nome do produto: Coleção Amor de Filhote Vagabundo; Marca: Roma; Idade recomendada: A partir de 3 anos; Selo Inmetro: 008048/2019 - OCP0003; Contém: 1 boneco e 1 certidão.', 79.99, 79.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd51-luf7dy4t2l09ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F20699245505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993408879', 'Tapete de Silicone para Barbearia - Mister Lizz', 'Tapete de Silicone para Barbearia - Mister Lizz Garanta mais organização e higiene em sua barbearia com o Tapete de Silicone para Barbearia da Mister Lizz! Desenvolvido com material resistente e antiderrapante, este tapete é ideal para proteger suas ferramentas de trabalho, como tesouras, máquinas de corte e navalhas, proporcionando mais segurança e praticidade no dia a dia. O design exclusivo de silicone oferece alta durabilidade, além de ser fácil de limpar e manter, prevenindo danos nas bancadas e mantendo o ambiente sempre organizado. Perfeito para barbearias que buscam eficiência e estilo! Características principais: Material de Silicone Resistente: Durabilidade e proteção para suas ferramentas Antiderrapante: Evita escorregamentos e quedas acidentais Fácil de limpar: Praticidade no uso diário Proteção da bancada: Mantém o local de trabalho seguro e organizado Tenha mais conforto e segurança em seu espaço de trabalho com o Tapete de Silicone para Barbearia - Mister Lizz!', 114.9, 89.9, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0xf7lrjvww0cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1180886499%2F22993408879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
