INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23894158602', 'Conjunto Infantil Menina Com Saia Pregas Colorittá Preto', 'O Conjunto Colorittá é composto por blusa em cotton leve e saia em tecido flanelado. A blusa de mangas longas possui bordado frontal com a frase "This is Love", enquanto a saia conta com elástico no cós e short interno, garantindo conforto para todos os momentos. Além disso, os detalhes em pregas dão um charme ao look, assim como o laço na cintura. Ideal para eventos especiais, passeios ou momentos de lazer, invista nesse conjunto encantador que une conforto e elegância!Detalhes da peça: • Conjunto composto por blusa e saia • Feito em cotton leve e tecido flanelado • Com bordado • Elástico no cós • Detalhe em pregas e laço • Possui short interno • Ideal para eventos especiais, passeios ou momentos de lazer', 189.9, 113.94, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8258t-mr1ts4uehx4x0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23894158602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
