INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199197397', 'Bola de Basquete Wilson Gamebreaker #7', 'Bola de Basquete Wilson Gamebreaker Azul #7 Bola de basquete Wilson Gamebreaker com design diferenciado e moderno com superfície para uso indoor e outdoor. Ideal para qualquer tipo de quadra ou na rua. As bolas de basquete Wilson são reconhecidas como uma das melhores bolas do mundo, elas são aprovadas pela NCAA, NBA e pelas melhores ligas de basquete de rua, streetball e quadra. Elas são fabricadas sob os mais altos padrões de qualidade. Fabricada em borracha de alta qualidade. Especificações: Superfície de Jogo: Indoor / Outdoor Inflar: 7-9 lbs Composição: Borracha Circunferência: 74.93cm Peso: 550-590g Cuidados: Limpeza com pano umedecido, não utilizar produtos corrosivos. Tamanho: 7 OFICIAL *REVENDA AUTORIZADA OFICIAL WILSON - PRODUTO ORIGINAL COM GARANTIA DO FABRICANTE*', 87.0, 78.3, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-821dx-mgz0tsx5yps89d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F589442593%2F22199197397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
