INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42717348793', 'Sandalia Feminina Lóris Tamanco Salto Plataforma Anabela Animal Print Vaca 14171', 'A papete plataforma com estampa animal print estilo “cow print” é a escolha perfeita para quem gosta de ousar no visual com muito conforto. Seu solado em madeira sintética traz um toque rústico e moderno, enquanto a tira larga no cabedal garante praticidade e estabilidade ao caminhar. Um modelo versátil que adiciona personalidade a qualquer look. TABELA DE MEDIDAS Tamanho 34 --- 23,0 cm Tamanho 35 --- 24,0 cm Tamanho 36 --- 24,5 cm Tamanho 37 --- 25,0 cm Tamanho 38 --- 25,5 cm Tamanho 39 --- 26,0 cm Altura do Salto: 4 cm Cor: Preto e Caramelo (estampa animal print cow print) Material: Sintético de alta qualidade Solado: Plataforma com efeito madeira Design: Tira larga única no cabedal Palmilha confortável para uso prolongado Estilo: Moderno, ousado e despojado Versátil: combina com jeans, saias, vestidos e looks casuais', 142.99, 99.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me7gkmt7gdmp06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F367507085%2F42717348793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398099740', 'Espatula Para Unha Lunis Encanto Com 1 Inox', '**Produto Original** Espátula Unha Inox Lunis Encanto C/1 – Profissional Características principais: Ponteira dupla: empurra e remove cutículas com precisão Aço inox esterilizável em autoclave Textura aderente no cabo: mais segurança no uso Ideal para uso profissional ou doméstico Alta durabilidade e acabamento de qualidade Descrição detalhada:A Espátula para Unha Lunis Encanto Inox é a ferramenta essencial para quem busca resultados profissionais na remoção de cutículas. Com ponteiras duplas, ela permite empurrar e raspar a cutícula com eficiência, oferecendo mais precisão nos cuidados com as unhas. Fabricada em aço inoxidável, é resistente, durável e pode ser esterilizada em autoclave, garantindo segurança e higiene no uso contínuo. Seu cabo com textura aderente oferece firmeza no manuseio, mesmo com as mãos úmidas. Vantagens: Ponteiras versáteis para diferentes funções Ideal para manicures, pedicures e uso pessoal Pode ser usada com segurança em ambientes profissionais Fácil higienização e reutilização Especificações: Marca: Lunis Material: Aço inox Tipo: Espátula para unhas Esterilizável: Sim, em autoclave Quantidade: 1 unidade Cuide das suas unhas com precisão e segurança com aEspátula Inox Lunis Encanto – qualidade profissional na palma da sua mão!', 15.9, 15.9, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdym-mc6y4z0qre2493', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F20398099740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897089278', 'Aparelho de Pressão Digital Pulso GTech GP400', 'Aparelho de Pressão Digital Pulso GTech GP400 O Aparelho de Pressão Digital de Pulso GTech GP400 é um dispositivo confiável e fácil de usar para monitorar a pressão arterial em casa. Com tecnologia avançada e recursos intuitivos, ele fornece medições precisas e convenientes. Este aparelho de pressão arterial é projetado para ser colocado no pulso, tornando-o conveniente e portátil. Possui uma pulseira ajustável que se encaixa confortavelmente em diferentes tamanhos de pulso. O GP400 utiliza a tecnologia de oscilometria para medir a pressão arterial. Ele infla automaticamente a pulseira e monitora as oscilações da pressão arterial para fornecer resultados precisos e confiáveis. O visor de fácil leitura exibe claramente as leituras da pressão arterial sistólica, diastólica e do pulso. Conteudo da Embalagem 01 Aparelho Digital de Pressão Digital G-tech 01 Braçadeira de pulso tamanho 13 a 20 centímetros (circunferência de Pulso) 01 Manual de Instruções em português 02 Pilhas AA 01 Estojo de Acrílico Importante Registro Anvisa 80275310066', 148.99, 148.99, NULL, 'Health > Medical Supplies > Health Monitors & Tests', 'https://cf.shopee.com.br/file/sg-11134201-7qvf8-li9a259t4hgv74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F19897089278', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
