INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297005861', 'Espaguete Termo Retrátil c/ Cola 6,4mm - Cód.5529', 'Ideal pra proteção e isolação elétrica de fios e cabos com flexibilide no mercado elétrico, eletrônico, comunicação, automotivo e muitos outros. - Tubo de poliolefina, retardante a chama, contração 2x com cola. - Ambientalmente Correto: Livre de substâncias como o PBB''s, PBBO''s, PBBE''s e livre de metais pesados. - Também conhecido como espaguete, termo contrátil ou termo retrátil com cola. - Grande vantagem se comparado ao espaguete de PVC: menor retração longitudinal, maior estabilidade dimensional, maior temperatura de trabalho. - Baixa temperatura de encolhimento e grande resistência mecânica. - Material Vendido por Metro Temperatura de trabalho: -55 °C a 125 °C. Temperatura mínima de encolhimento: 70 °C. Temperatura de encolhimento total: 100 °C.', 18.07, 18.07, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-mcqfdhuvwbnk53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F19297005861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
