INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44861522160', 'Morsa Torno De Bancada Profissional 75Mm Tb-200P N.02 Para Fixação Pesada E Precisa - Motomil', '🔩 Torno de Bancada TB-200P 63mm com Bigorna 💪 Compacto, resistente e ideal para fixação segura de peças! O Torno de Bancada TB-200P é uma ferramenta indispensável para profissionais e hobbistas que necessitam de firmeza e precisão durante trabalhos de montagem, desmontagem, ajustes e reparos. Indicado para ferramentarias, indústrias, serralherias, construção civil e oficinas em geral. Sua estrutura robusta proporciona excelente estabilidade na fixação de peças, garantindo mais segurança e praticidade durante a execução dos trabalhos. ✨ Diferenciais do Produto ✅ Estrutura resistente e durável ✅ Fixação firme para diversos tipos de peças ✅ Ideal para montagem e desmontagem de componentes ✅ Fácil instalação em bancadas ✅ Compacto e prático para o dia a dia ✅ Indicado para uso profissional e doméstico 📋 Especificações Técnicas: • Modelo: TB-200P • Abertura útil: 70 mm • Largura do mordente: 63 mm • Peso: 2,1 kg • Tipo: Torno de Bancada • Aplicação: Fixação de peças em trabalhos de manutenção, montagem e reparos 🔨 Indicado para: • Oficinas mecânicas • Ferramentarias • Serralherias • Construção civil • Manutenções em geral • Uso doméstico e profissional 📦 Conteúdo da Embalagem: • 01 Torno de Bancada TB-200P 🚚 Produto novo e original 📦 Pronta entrega 🔒 Compra 100% segura IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 189.99, 119.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-823q6-moyfqhowkzcx0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F44861522160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
