INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43265550741', 'Grampo de Aperto Rápido Tipo Horizontal – VONDER GHV 225', 'Grampo de Aperto Rápido Tipo Horizontal – VONDER GHV 225 Grampo de aperto rápido tipo horizontal, indicado para fixação e aperto de peças em geral. Fabricado em aço carbono com acabamento zincado, oferece maior resistência à oxidação, durabilidade e praticidade em trabalhos manuais e industriais. Ideal para marcenaria, manutenção e montagens em geral. Itens Inclusos 1 Grampo de aperto rápido tipo horizontal Especificações Técnicas Modelo: GHV 225 Material: Aço carbono com acabamento zincado Ângulo de abertura: 65° Força de retenção: 225 kgf Massa aproximada: 0,249 kg Por que escolher este produto? Produto novo e original. Pronta entrega e envio em até 24 horas. Compra 100% segura com garantia legal de 90 dias.', 80.0, 37.9, NULL, 'Stationery > School & Office Equipment > Staplers & Staples', 'https://cf.shopee.com.br/file/sg-11134201-824gn-mdyyagztmakhf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F43265550741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7867120626', 'Bico de Mamadeira First Choice Advanced Flow Control - NUK', 'Bico de Mamadeira First Choice Advanced Flow Control - NUK O Bico NUK First Choice Advanced é indicado para reposição em mamadeiras da linha NUK First Choice tamanho 2 e é produzido em Silicone Soft Flex, por isso possui uma superfície macia e flexível. O bico conta com parte plana, angulada e totalmente flexível que permite uma ação de sucção apertada. Conta também com a válvula NUK Air System, um sistema de ventilação que reduz a formação e ingestão de bolhas de ar durante a alimentação, possibilitando um fluxo constante de líquido para que a criança se alimente de forma contínua. Corpo arredondado com espaço suficiente para os movimentos da mandíbula durante a sucção. A inclinação força a criança a desenvolver a ação de sucção com a mandíbula. O furo do bico NUK está localizado atrás da curva, e não na ponta do bico, fazendo com que o alimento seja direcionado para o palato da criança, misturando-se com a saliva antes de ser engolido. O MINISTÉRIO DE SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA, PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Tamanho do Bico: Nº 2 (6m+) - Flow Control: A Criança Controla o Fluxo de Líquido - Furo do Bico em Formato de "Y” - Todos os Fluxos de Líquido em um Único Bico: Ralos, Médios, Engrossados e Extra Engrossados - Bico todo em Silicone Soft Flex com Superfície Macia e Flexível - Válvula NUK Air System: Reduz a Ingestão de ar Durante a Alimentação - Livre de BPA - Cor: Transparente. Especificações Técnicas: - Conteúdo da Embalagem: 1 Bico de Reposição First Choice Advanced Flow Control - Nuk - Composição/Material: Silicone - Certificação: Inmetro OCP 006 - CE-PUR/IQB-000611 - Garantia: 30 dias (Contra Defeitos de Fabricação Pelo Fabricante) - Referência do Fabricante: PA7016-2U - EAN: 7896098808436 - Marca: NUK Imagens Meramente Ilustrativas. As cores e estampas podem variar de acordo com o lote do fabricante.', 25.99, 25.99, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/br-11134201-820l8-mqx7e69p0w790e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F7867120626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
