INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699334980', 'Creatina Monohidratada 300g + Cafeína Fire Black - 60 Cápsulas - Max Titanium', 'COMPOSIÇÃO DO ANÚNCIO 1x CREATINE - 300G - MAX TITANIUM 1x FIRE BLACK - 60 CAPS - MAX TITANIUM -----------------------------------------------------------------------//--------------------------------------------------------------------------------------------------------------------------- CREATINA 300G - MODO DE PREPARO/SUGESTÃO DE USO A diluição recomendada é de 3g (2 dosadores) do produto em água ou sua bebida preferida até completa homogeneização. LACTOSE Não contém. ALÉRGICOS Pode conter derivados de leite, ovo e soja. ADVERTÊNCIAS “ESTE PRODUTO NÃO SUBSTITUI UMA ALIMENTAÇÃO EQUILIBRADA E SEU CONSUMO DEVE SER ORIENTADO POR NUTRICIONISTA OU MÉDICO.” “O CONSUMO DE CREATINA ACIMA DE 3g AO DIA PODE SER PREJUDICIAL À SAÚDE.” “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR CRIANÇAS, GESTANTES, IDOSOS E PORTADORES DE ENFERMIDADES.” -----------------------------------------------------------------------//--------------------------------------------------------------------------------------------------------------------------- "ULTIMATE FIRE BLACK - Max Titanium foi desenvolvido especialmente para aumentar o seu nível de energia e melhorar a sua performance durante os treinos. Ultimate Fire Black traz em sua fórmula 420 mg de cafeína pura. Você Sabia? Sugestão de uso: Ingerir de uma a duas cápsulas do Fire Black antes do treino. Não exceder a porção de 2 cápsulas ao dia. Evitar o consumo em até 6 horas antes de dormir. Recomendações:""Este produto não deve ser consumido por crianças, gestantes, idosos e portadores de enfermidades"". ""Este produto não substitui uma alimentação equilibrada e seu consumo deve ser orientado por nutricionista ou médico"" Conservação: Conservar em local fresco, seco, inodoro e ao abrigo da luz. Manter fora do alcance de crianças e animais."', 99.9, 99.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyatfhy62c2de5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F19699334980', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17872447163', 'Pastilha Freio GP TECH 0260SM (D) Intruder 125 / Legion 125 / Green SPORT 150', 'Semi-MetálicaProcesso de Fabricação Prensa térmicaComposição Elementos metálicos, lubrificantes, celulose e resina fenólicaPlaca Aço 1060. Adequada para motos de baixa cilindrada ou para freio traseiro de motos de média cc. (durabilidade média de 10.000 kms) (Tem baixo custo e funciona muito bem em baixas temperaturas e razoavelmente confortável)Pastilha de freio - Organic Semi-MetalComposição Organic Semi-Metal.,Contém 1 jogo para uma 1 pinça de freio.,Garantia somente quando instalada por oficina especializada ou mecânico profissional.,Não pilote se evidenciar qualquer irregularidade nos freios.,Não possuí garantia para moto em competição, quilometragem ou instalação irregular.,Garantia de 90 dias.,Sem amianto.,AplicaçãoAGRALE 125 LEGION 98- DBRANDY 125 FT A FOSTI 97- DFYM 125 FY-19 06- DKASINSKI 125 MAGIK 02- DSUZUKI 125 INTRUDER (BRASIL) 02- DTRAXX 125 FLY 08- TProduto não perecível.Foto IlustrativaModelo Moto: Suzuki', 56.0, 56.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7qvej-ljy33942uqke06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F17872447163', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998553685', 'Hub Multifuncional Usb-C 3.2 Ugreen 4 em 1 10Gbps Preto', 'Hub Multifuncional Usb-C 3.2 Ugreen 4 em 1 10Gbps Preto, Transferência de Dados de 10 Gbps, Plug and Play, Compacto e Leve, Ampla Compatibilidade - 35584 1. O Hub Multifuncional USB-C 3.2 Ugreen 4 em 1 oferece quatro portas USB-C para expandir suas conexões com alta velocidade. Com taxa de transferência de até 10 Gbps, é ideal para quem precisa de rapidez na transferência de arquivos e acessibilidade múltipla. 2. Com design compacto e leve, o hub é fácil de transportar e perfeito para uso em qualquer lugar, seja no escritório, casa ou durante viagens. O sistema Plug and Play permite que seja usado imediatamente sem necessidade de instalação de drivers. 3. Compatível com uma ampla variedade de dispositivos USB-C, como notebooks, tablets e smartphones, facilitando a conexão e a transferência de dados entre eles com praticidade e segurança. 4. Apesar das portas USB-C não suportarem saída de vídeo ou carregamento, o hub é ideal para expandir conexões USB em equipamentos que precisam de múltiplas portas para dispositivos como pen drives, HDs externos, teclados e mouses. 5. Produto com construção robusta e design moderno, desenvolvido para atender às necessidades do dia a dia com eficiência e confiabilidade. Este hub é fácil de transportar, cabendo perfeitamente na sua bolsa. Garantia 90 dias', 222.81, 222.81, NULL, 'Computers & Accessories > Peripherals & Accessories > USB Hubs & Card Readers', 'https://cf.shopee.com.br/file/br-11134275-7r98o-macz4c6mhoy704', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F22998553685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194037262', 'Suporte de Parede Ugreen p Carregamento de Smartphone', 'Ugreen Suporte de Parede para Carregamento de Smartphone/Celular Ampla Gama de Aplicações Carga Máxima Suportada de Até 5 kg/ No Brasil O suporte de parede da Ugreen pode oferecer ao seu telefone uma base segura durante o carregamento e conta com ampla gama de aplicações, podendo ser usado em papéis de parede lisos e uniformes, paredes de cal, ladrilhos, aço inoxidável, vidro, superfície de madeira e metal. Marca: Ugreen Cor do produto: Branco Referência do modelo: 30394 Projetado para ser fixado à parede Carga máxima: Até 5 kg Dimensões: 4,0 x 13,0 x 8,0 cm Peso: 0,078 Itens inclusos 1x Suporte de parede 1x Manual do usuário Garantia: 90 dias', 39.38, 39.38, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9yrw47x0raxa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23194037262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
