INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45512697780', 'Kit Pampers Glicerina Shampoo 350ml + Condicionador 200ml + Loção Hidratante 350ml + Sabonete Líquido 200ml', 'O Kit contém: - 1 Pampers Sabonete Líquido de Glicerina 200ml; - 1 Refil Pampers Loção Hidratante Infantil 350ml; - 1 Refil Pampers Shampoo de Glicerina 350ml; - 1 Pampers Condicionador de Glicerina 200ml; Sabonete Líquido de Glicerina limpeza suave da cabeça aos pés. O Sabonete Líquido Pampers foi criado pensando em um banho suave e seguro. Sua composição não contém nenhum álcool etílico, fenoxietanol, parabenos e corantes, trazendo maior suavidade e mantendo a pele do seu neném macia. Refil Loção Hidratante hidrata a pele já na primeira aplicação. A Loção Hidratante Pampers foi criada pensando em hidratar a pele já na primeira aplicação. Sua composição não contém nenhum álcool etílico, fenoxietanol, parabenos e corantes, trazendo maior suavidade e mantendo a pele do seu neném macia. Refil Shampoo de Glicerina uma limpeza suave e segura. O Shampoo de Glicerina Pampers foi criado pensando em uma limpeza suave e segura. Sua composição não contém nenhum álcool etílico, fenoxietanol, parabenos e corantes, trazendo maior suavidade e mantendo os fios do seu neném macios. Condicionador de Glicerina desembaraça com facilidade os fios e condiciona de forma suave e segura! O Condicionador de Glicerina Pampers foi criado pensando em desembaraçar com facilidade os fios e condicionar de forma suave e segura. Sua composição não contém nenhum álcool etílico, fenoxietanol, parabenos e corantes, trazendo maior suavidade e mantendo os fios do seu neném macios.', 135.34, 135.34, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-824g3-mptqk2z79y4v6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.b