INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199131263', 'Roteador Wi-fi Alto Desempenho W5-1200GS Preto Intelbras', 'O Roteador W5-1200GS é Ideal para planos de internet de até 400 mega*, ampla área de cobertura de até 120m², conexão de até 40 dispositivos simultâneos e tecnologia inMesh. * Valores médios sugeridos dependem de fatores ambientais, como local de instalação, interferências próximas e perfil de uso da rede. Principais Funcionalidades • Cobertura Ampla com Quatro Antenas Externas - O W5-1200GS conta com quatro antenas externas, que ampliam o alcance e a estabilidade do sinal Wi-Fi, proporcionando melhor cobertura mesmo em ambientes com barreiras físicas. • Área de Cobertura de Até 120 m² - Ideal para residências e escritórios de pequeno a médio porte, o roteador cobre até 120 metros quadrados, garantindo sinal forte em diversos cômodos. • Conectividade para Até 40 Dispositivos - Suporta a conexão simultânea de até 40 dispositivos, sendo ideal para famílias com múltiplos usuários e dispositivos como smartphones, notebooks, smart TVs. • Ideal para Planos de Internet de Até 400 Mega - O desempenho do roteador é otimizado para planos de até 400 Mbps, garantindo boa velocidade para streaming, jogos online e videoconferências sem travamentos. • Tecnologia inMesh Integrada - Compatível com a tecnologia inMesh, o W5-1200GS pode ser integrado a outros roteadores compatíveis para formar uma rede Wi-Fi unificada e expansível, com cobertura maior e transição automática de sinal entre os dispositivos.', 257.9, 199.9, NULL, 'Computers & Accessories > Network Components > Modems & Wireless Routers', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mqrno9vgzua38a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859766415%2F23199131263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260626673', 'Conjunto Algodão Menina Blusa Longa E Calça Select Rosa', 'Conjunto infantil feminino Select, ideal para proporcionar conforto e estilo no dia a dia. Confeccionado em cotton 100% algodão, garante toque macio e ótima respirabilidade. O conjunto é composto por blusa de manga longa com estampa em silk e decote redondo, oferecendo um visual moderno e delicado. A calça leg possui estampa rotativa que traz charme ao look e ajuste confortável ao corpo, perfeito para acompanhar as meninas em diversas atividades.', 36.99, 36.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259l-mq3qtddryn0rb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58260626673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
