INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3990060197', 'Organizador vertical Cristal 864.1 Acrimet', 'Organizador vertical Cristal - 864.1 - Acrimet O Organizador de Escritório Vertical Acrimet é a escolha ideal para organizar catálogos, pastas, folders, papéis, arquivos, entre outros. Fabricado em poliestireno, possui 3 compartimentos com paredes espessas que oferece alta durabilidade e facilita a organização dos documentos. Proporciona visibilidade rápida e fácil acesso ao arquivo, além de economizar espaço na área de trabalho. Pode ser usado em superfícies em pé ou deitado, e também possui orifícios na parte traseira, permitindo que o produto seja fixado ou pendurado (suportes para fixação não inclusos). Ótimo para ser utilizado em escritórios, escolas, clínicas médicas, hospitais, bancos, e até mesmo na sua casa. Detalhes: - Dimensões: 24cm (L) x 12cm (P) x 33,5cm (A) - Composição: Poliestireno. - Possui 3 divisórias - Pode ser utilizado deitado ou em pé - Alta qualidade, resistência e durabilidade. - Possui orifícios na parte traseira, permitindo que o produto seja fixado ou pendurado', 132.44, 132.44, NULL, 'Stationery > School & Office Equipment > Folders, Paper Organizers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-lqam80s2qfd1a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F3990060197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
