INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20296912577', 'Makker Maquiador Automotivo Renova Pintura Defeitos Vonixx', 'KIT CONTÉM: MAKKER 2.0 500ML APLICADOR DE ESPUMA VONIXX --------------------------------------------------------------------- MAKKER 2.0 MAQUIADOR AUTOMOTIVO VONIXX 500ML DESCRIÇÃO: É uma maquiagem automotiva desenvolvida exclusivamente para preencher pequenos defeitos e renovar pinturas queimadas ou desbotadas. Pode também ser utilizado para alcançar brilho máximo na pintura. Além de maquiar, deixa um toque extremamente liso e garante proteção de 30 dias. OBS: Se usado com politriz pode corrigir defeitos leves. MODO DE USO: 1. Agite bem antes de usar. 2. Aplique uma pequena quantidade utilizando um aplicador de espuma ou microfibra fazendo movimentos uniformes 3. Aguarde a secagem entre 5 e 30 minutos 4. Remova o produto utilizando uma toalha de microfibra limpa e seca até obter o brilho desejado.', 82.92, 82.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7l1i8h077eq50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20296912577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
