INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294946788', 'Ferrero Rocher', 'Ferrero Rocher oferece uma experiência de sabor única com suas camadas contrastantes: uma avelã inteira, um recheio cremoso de avelã, um wafer crocante coberto com chocolate e pedacinhos de avelã. Cada bombom é embalado individualmente em papel dourado, tornando-o perfeito para presentear. Compartilhe momentos especiais com Ferrero Rocher, seja em datas comemorativas ou como um mimo para você.', 35.99, 35.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mqnkre04chkx05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F23294946788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
