INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999680446', 'Triciclo Carrinho Motoca C/ Guia Passeio e Pedal Avespa Colorido Infantil Empurrador Maral', 'Um triciclo inspirado no estilo clássico, no modelo retrô. Multifuncional...pode ser utilizado nas funções Passear e Pedalar. Na função Passear: o adulto tem controle na direção do triciclo para empurrar. A haste da guia é metálica e fácil de retirar, tem um gancho para pendurar bolsa ou sacola até 1,5 kg. O anel de proteção é removível, e vem com uma peça adicional para dar maior segurança às crianças menores. Guidão com punhos emborrachados e buzina com som divertido! Com 2 porta objetos, um abaixo do assento e um removível para transportar o que quiser... Apoios de pés de fácil remoção. Pedais com eixos de aço. Na função Pedalar: retirando os acessórios (haste-guia, anel de proteção e apoio de pés), a criança pode pedalar e brincar sozinha...desenvolvendo a coordenação motora e o senso de direção. Resistente! Suporta até 25 kg.', 359.9, 258.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8g60ajxsr9t43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504754787%2F20999680446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
