INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693072443', 'Diário de Pilar no Egito (Nova edição)', 'Em mais uma emocionante aventura a bordo da rede mágica, Pilar vai viajar para o Egito com seus inseparáveis companheiros Breno e o gatinho Samba. Ao desembarcar inesperadamente no Vale dos Reis, a menina aventureira encontra Tutancâmon, o jovem faraó que foi enterrado vivo num sarcófago e precisa de ajuda para recuperar seu trono. Nas asas da Fênix, os amigos sobrevoam o deserto e vivem experiências inesquecíveis explorando as pirâmides, enfrentando deuses, feras e seres mitológicos. Navegam o rio Nilo em uma feluca — um barco de madeira com uma única vela —, visitam o templo de Hórus e conhecem a escrita hieroglífica. Indicado para leitores a partir de 9 anos.', 64.78, 64.78, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-lvzd3juqssc668', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23693072443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
