INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21355058650', 'Kit 2 Travesseiros Toque de Pluma Percal 180 Fios Algodão Suporte Médio 70cm x 50cm', 'Como é bom ter uma ótima noite de sono, não é verdade? E nada melhor do que um travesseiro confortável para isso. O produto é confeccionado em Percal 180 fios e seu enchimento em fibra siliconizada com toque de pluma, deixando-o muito mais macio e agradável. SOBRE A EMBALAGEM: O produto é embalado em formato de rolinho, mas não se preocupe. Assim que o tirar da embalagem é só desenrolar e afofar que ele voltará ao seu formato original. Composição da embalagem: 02 Travesseiro Toque de Pluma médio 70 cm x 50 cm Especificações: Tamanho: 70cm x 50cm Cor: Branco Tecido: Percal 180 fios 54% algodão/ 46% poliéster Enchimento: 70% Fibra siliconizada 100% poliéster / 30% Pluma Sintética 100% Poliéster Altura: Baixo Suporte: Médio Gramatura: 550 gramas RECOMENDAMOS - Atenção na descrição do produto acima - Seguir as recomendações de lavagem contidas na etiqueta', 151.9, 151.9, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh0ujh64b0n41c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316749752%2F21355058650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
