INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207914273', 'Popozuda Lisinha Redutor de Pelos Corporais com Telocapil', 'Pele mais confortável depois da depilação, do jeito que deveria ser. O Popozuda Lisinha é um sérum de uso diário desenvolvido para cuidar da pele após a depilação, ajudando a reduzir o desconforto e mantendo a pele mais equilibrada com o uso contínuo. Com ativos como Telocapil 1%, D-Pantenol, Camomila e Vitamina E, ele promove uma sensação imediata de alívio enquanto contribui para uma rotina mais prática e confortável. Indicado para: * Axilas * Virilha (externa) * Pernas e braços O que você pode esperar: * Ajuda a acalmar a pele após a depilação * Sensação de pele mais macia e confortável * Auxilia na manutenção do crescimento dos pelos com uso contínuo Textura leve, rápida absorção e perfeito pra usar todos os dias.', 99.9, 59.9, NULL, 'Beauty > Bath & Body Care > Hair Removal Cream & Wax', 'https://cf.shopee.com.br/file/br-11134207-820lo-mq489zahlqtde6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1643598397%2F58207914273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497726991', 'BTX Capilar Cacau Organic Repositor de Massa Termoativado 1kg', 'A Máscara Cacau Power Nutri nutre e repara os fios secos e ressecados de maneira contínua. Fortalece, protege e reforça a estrutura dos fios, prevenindo o frizz, deixando-os macios e sedosos. Forma um filme protetor que retém os ativos, com resultados ainda mais eficientes. Indicação: Para cabelos secos e ressecados. Ingredientes e benefícios: • MANTEIGA DE CACAU – hidratação e ação emoliente • ÓLEO DE COCO – nutrição e brilho • ÓLEO DE ABACATE – nutrição e maciez • ÓLEO DE GERGELIM – auxilia o crescimento e ação condicionante • ÓLEO DE PALMA – flexibilidade dos fios e brilho • ÁGUA DE COCO VERDE – hidratação e remineralização • AMINOÁCIDOS – prevenção de quebra e ação antifrizz • COLÁGENO VEGETAL – forma filme protetor e antioxidante • D-PANTENOL – nutrição e umectação Modo de Usar: Após lavar os cabelos com o Shampoo e/ou Condicionador, aplique a Máscara Cacau Power Nutri distribuindo o produto do comprimento às pontas dos fios. Deixe agir entre 5 e 10 minutos e enxágue bem. Para melhores resultados utilize o Shampoo e Condicionador Cacau Power Nutri. Resultado: Cabelos nutridos, protegidos, com realce do brilho e efeito de longa duração. Cacau Power Nutri A linha Cacau Power Nutri foi especialmente elaborada para a nutrição dos cabelos secos e ressecados, expostos a tratamentos químicos, piscina, mar e aparelhos térmicos, que necessitam de ajuda extra. Seus ricos ativos: Manteiga de Cacau, Óleo de Coco, Óleo de Abacate, Óleo de Gergelim e Óleo de Palma são fontes de ácidos graxos e lipídeos, associados aos Aminoácidos, Colágeno Vegetal, D-Pantenol e Água de Coco Verde, auxiliam no reforço estrutural dos fios, fortalecendo a barreira protetora da fibra capilar. Juntos, os ricos ativos, promovem multibenefícios com resultados de longa duração para os cabelos e auxiliam na prevenção de danos futuros, conferindo, maciez, reparação de pontas duplas, ação anti frizz e brilho intenso.', 167.89, 109.13, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk1ihs2ahhc0ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513541030%2F18497726991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
