INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498572778', 'Sandália Rasteira Anacapri Corrente Slim New Dourado - Feminino', 'Sinta a leveza e o charme em cada passo! Sandália Rasteira Anacapri Corrente Slim New Dourado - Feminino Ficha Técnica: Marca: Anacapri Cor: Dourado Cabedal: Material tecnológico similar ao couro com tira fina e maxi corrente Gênero: Feminino Palmilha: Confortável e acolchoada no mesmo tom da peça Sola: Emborrachada com leve salto traseiro Fechamento: Fivela ajustável no calcanhar Bico: Arredondado Indicado: Dia a dia e lazer Detalhes: Design slim com corrente maxi na gáspea e acabamento monocromático Com um visual moderno e leve, a Sandália Rasteira Anacapri Corrente Slim New Dourado conquista de cara pelo design elegante e fresh. Porque investir: Seu cabedal fininho com maxi corrente dourada traz um charme sofisticado para o seu dia a dia. Ideal para quem busca conforto sem abrir mão do estilo, ela combina com produções descomplicadas, seja na praia, no passeio ou em momentos de lazer. Experimente o toque macio da palmilha e o ajuste perfeito no calcanhar. Conteúdo da embalagem: 1 par de Sandália Rasteira Anacapri Corrente Slim New Dourado - Feminino Parte superior do formulário', 179.99, 152.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rav6-man5s94t9dg1cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F22498572778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
