INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697762345', 'Jogo de Jantar 20 Peças Ryo Chá Bambu Porcelana Oxford', 'Jogo de Jantar 20 Peças Ryo Chá Bambu Porcelana Oxford Valorizar o imperfeito, o processo de criação até o seu acabamento. Este é o conceito wabi-sabi, uma visão de mundo japonesa praticada desde o século XV e que tem como base os ideais de uma estética que exalta o irregular, o impermanente e o incompleto. Seguindo essa tendência amplamente utilizada em vários itens de decoração, a Oxford apresenta a coleção Ryo: peças únicas que valorizam o trabalho manual e as composições imperfeitas. A decoração da coleção Ryo Bambu tem esta planta em destaque e que sempre está presente na história e cultura do Japão. A estética vintage das peças é alcançada através de uma técnica manual de decoração com esmalte reagente e um filete manual, também reagente, e que confere características únicas à coleção. A coleção Ryo Bambu agora também tem uma variedade de peças complementares, como canecas, travessas e tigelas para completar a sua mesa Descrição do produto Marca: Oxford Modelo: Ryo Coleção: Bambu Material: Porcelana Composição: 4 pratos fundos, 4 pratos rasos, 4 pratos de sobremesa, 4 xícaras, 4 pires Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 852.83, 676.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-ly8foz613aui71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F19697762345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
