INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897506859', 'Pneu Speedmax Aro 17 SPM301 165/40R17 72V', 'Marca: SPEEDMAX Modelo: SPM301 Medida: 165/40R17 Largura: 165 Perfil: 40 Tamanho de Aro: 17 Índice de peso: 72 - 355 kg, 72 Índice de velocidade: V - 240 km/h, V Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: N/A Adesão à àgua: C Eficiência energética: E Ruído externo: 71 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 417.15, 383.78, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-lxlr4pyc2zbc0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22897506859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599307843', 'Pneu Kumho Aro 16 Ecsta HS52 185/55R16 83V', 'Marca: KUMHO Modelo: ECSTA HS52 Medida: 185/55R16 Largura: 185 Perfil: 55 Tamanho de Aro: 16 Índice de peso: 83 - 487 kg Índice de velocidade: V - 240 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: N/A Adesão à àgua: A Eficiência energética: E Ruído externo: 70 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Kumho A marca Kumho foi fundada em 1960 em Gwangju na Coreia do Sul. Os pneus Kumho são mundialmente conhecidos pela alta qualidade e aderência, pois usam matéria prima e processos de produção de primeira categoria. São pneus duráveis e confiáveis, e um ótimo indicativo disso, é que são pneus originais de fábrica de marcas como Hyundai, Kia e Chevrolet, entre outras. Pneu Kumho tem garantia de 5 anos e oferece segurança, conforto e economia na manutenção do seu carro.', 527.6, 485.4, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-lyb3tdipm1roac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20599307843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47806152879', 'Tênis Sapatenis Evoke Street Sandrini Masculino', 'Tênis/Sapatênis Sandrini Evoke Street | REF: SN-360R Sobre o item: O Evoke Street combina visual moderno com conforto leve para o dia a dia. Cabedal em couro sintético na cor preto com detalhe cinza, estilo urbano e acabamento clean que transita do casual ao trabalho, do passeio a pequenos eventos com facilidade. Especificações técnicas: Marca: Sandrini Produto: Tênis/Sapatênis casual Modelo: Evoke Street Material (cabedal): couro sintético Cor: preto com detalhe cinza Benefícios e cuidados: Benefícios: Versatilidade real: combina com jeans, chino e camisas para looks do casual ao social leve, conforto no uso diário: estrutura leve e macia para rotinas urbanas, estilo urbano: design moderno e cores neutras que facilitam composições Cuidados: Limpar com pano macio levemente umedecido; secar à sombra, não usar alvejante ou produtos abrasivos, evitar imersão total em água e fontes de calor direto Tabela de medidas (comprimento do pé, em cm): 39: 27,0 cm 40: 27,5 cm 41: 28,0 cm 42: 29,0 cm 43: 29,5 cm Dica: meça do calcanhar até o dedo mais longo e selecione o número correspondente. Política de devolução: Aceitamos a devolução dentro dos prazos previstos pelo marketplace, com o produto sem uso e em perfeitas condições, com etiquetas/embalagem originais. Não realizamos alterações de cor/tamanho após a confirmação do pedido. FAQ: O produto é original? Sim, todos os produtos são 100% originais. Acompanha nota fiscal? Sim, todos os produtos com nota fiscal e garantia de procedência. Posso trocar minha escolha depois de finalizar a compra? Não é possível alterar após a compra. Os itens são enviados exatamente conforme selecionado. É couro legítimo? Não. O cabedal é em couro sintético, conforme informado. Serve para corrida/treino? Não é modelo de performance esportiva. Indicado para uso urbano (casual, trabalho, passeio). Sobre a Sandrini: A Sandrini é referência desde 2011 em moda masculina, esportes e saúde, com foco em qualidade, conforto e satisfação total. Atuamos com tênis, cuecas, shorts/bermudas, camisetas e itens de esporte (bolas e chuteiras), além de saúde (meias de compressão e bota ortopédica). Reconhecida pela excelência no atendimento e pela variedade, fomos premiados em 2022 como a maior loja do marketplace. Imagens ilustrativas. As cores podem variar de acordo com o lote ou sua tela/Monitor. Garantia do vendedor: 30 dias', 162.5, 78.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81ztz-mkmrw6fq6kn7b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1035548531%2F47806152879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42414193053', 'Coroa Folhas de Louro Dourada Tiara pra Fantasia Deus Grego ou Deusa Grega', 'Itens inclusos 01 Coroa De Louro Especificações Técnicas Produto: Novo, na embalagem. Cor: Dourado Produto a pronta entrega! Linda coroa dourada circular de tamanho único, repleta de folhas de louro. De metal, resistente e durável, para você usar várias vezes com o sua fantasia cosplay. A coroa de louro é um símbolo majestoso dos deuses gregos e romanos da mitologia clássica. Esta deslumbrante peça de arte é meticulosamente confeccionada em metal dourado, com detalhes em folhas de louro. Material Resistente Cosplay Deuses Gregos Metal Dourado', 34.99, 34.99, NULL, 'Fashion Accessories > Hair Accessories > Headpieces, Tiaras & Flower Crowns', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-mdnetyeivfng7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F42414193053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
