INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49505661902', 'O grupo de apoio para garotas finais por Grady Hendrix, Intrínseca', 'Elas já escaparam da morte uma vez. E vão precisar fazer isso de novo. Nos filmes de terror, a “garota final” é aquela que ainda está de pé quando os créditos começam a subir. Aquela que lutou, derrotou o assassino e vingou a morte dos amigos. Aquela que resistiu. Mas depois que o público sai do cinema, o que acontece com essa garota? Há vinte e dois anos, Lynnette Tarkington sobreviveu a um massacre, e desde então sua vida nunca mais foi a mesma. Ela não foi a única a passar por isso, inclusive. Há mais de uma década, participa de um grupo de apoio com uma terapeuta e outras cinco garotas finais, também vítimas de ataques terríveis, que precisam reconstruir a vida. Até que, certo dia, uma das integrantes falta a uma reunião sem avisar, e uma série de acontecimentos põe em xeque a credibilidade de Lynnette, fazendo com que seus maiores medos se tornem realidade: alguém sabe sobre os segredos confessados no grupo e está determinado a acabar com a vida de todas elas. Com tantos fãs de assassinos em série por aí, compartilhando desejos doentios e idolatrando criminosos cruéis, em quem confiar nessa corrida contra o tempo para provar a própria inocência e impedir que uma nova onda de assassinatos aconteça?', 74.9, 59.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134275-81ztc-mj8yvxrlgflt3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F49505661902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
