INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210122297', 'Tênis Feminino Esportivo Corrida Leve Flexível Ramarim 2675131', 'Tênis Feminino Esportivo Confortável Leve para Caminhada e Corrida Performance, conforto e estilo em um só modelo para acompanhar sua rotina ativa. Design moderno e versátil: Com visual esportivo e contemporâneo, esse tênis é perfeito para quem busca praticidade no dia a dia sem abrir mão do estilo. Combina com looks fitness e também com produções casuais. Respirabilidade e conforto: Produzido em tecido macio e transpirável, permite melhor circulação de ar, mantendo os pés mais frescos durante o uso, inclusive em atividades físicas. Amortecimento que faz a diferença: A sola em EVA garante leveza, maciez e excelente absorção de impacto, proporcionando mais conforto em caminhadas e corridas. Mais segurança ao caminhar: Conta com detalhes em borracha na sola, que aumentam a aderência e ajudam a evitar escorregões. Cuidado extra com seus pés: Possui forro bactericida, auxiliando na prevenção de odores e mantendo maior sensação de higiene. Principais características: Material em tecido macio e respirável; Sola em EVA: leve, flexível e com amortecimento; Detalhes em borracha para maior aderência; Indicado para caminhada e corrida leve; Forro bactericida Versátil para o dia a dia: Ideal para academia, caminhadas, corridas leves ou até mesmo para compor looks confortáveis no dia a dia. Dica de conservação: Limpar com pano úmido e deixar secar à sombra. Evitar lavagem em máquina para preservar a estrutura do produto. Palavras-chave estratégicas: tênis feminino esportivo, tênis para caminhada feminino, tênis leve confortável, tênis para corrida leve, tênis com amortecimento Perfeito para quem busca leveza, conforto e desempenho em todos os momentos!', 269.9, 249.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820mb-mnvi4tz4tvcx58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1011144984%2F58210122297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23995671720', 'Volante Esportivo cruze preto logo fiat vermelho para Uno Fire Mile Palio Marea Brava Siena Strada', 'ESPECIFICAÇÃO TÉCNICA • Diâmetro de 370mm; • Profundidade de 120mm. MODELOS COMPATÍVEIS • CV109 • Uno • Fire • Mille • Marea • Palio • Brava • Idea • Siena • Strada • Punto • Stilo • Ducato • Doblô 2001 em diante Caso não tenha encontrado o modelo do seu veículo neste anúncio, nos consulte. IMPORTANTE • Garantia de 3 Meses; • Somos FABRICANTES ESPECIALIZADOS no segmento automotivo, seguimos um processo rigoroso de fabricação e qualidade; • Entrega ágil e rápida após sua compra; • Enviamos todos os nossos volantes com CUBO ADAPTADOR; • Após a instalação, perde-se a função AIRBAG; • RECOMENDAMOS QUE A INSTALAÇÃO SEJA FEITA POR PROFISSIONAL ESPECIALIZADO. • Fabricamos volantes em POLIURETANO RESISTENTE; • Nossos volantes possuem similaridade ao original com acabamento texturizado e acionamento da buzina. Sua satisfação é nossa maior recompensa! Estamos à disposição e teremos o imenso prazer em atendê-lo!', 224.99, 180.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lgkz6e1s65j35b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F23995671720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
