INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210127273', 'Michelob Ultra Light Lager Sem Glúten', 'Michelob Ultra é uma cerveja light lager superior, ideal para quem busca uma vida equilibrada. Com apenas 85 calorias e 2,6g de carboidratos, ela oferece leveza e refrescância sem abrir mão do sabor. Seu teor alcoólico é de 4,2%. Perfeita para quem gosta de uma rotina ativa e aprecia os momentos de pausa. Michelob Ultra é feita com lúpulo Herkules e grãos integrais, resultando em um aroma cítrico e final refrescante. Além disso, não contém glúten.', 6.79, 6.79, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-823pw-moo4indfbnrf7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F58210127273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10951192794', 'Kit brinco e colar gota ponto de luz prata 925 verde esmeralda', 'Itens inclusos: - conjunto brinco, corrente e pingente em formato de gota -cor: Verde esmeralda tamanho da corrente: 45cm tamanho do pingente: 6mm tamanho do brinco: 6mm - 1 Termo de Garantia Esta linda peça, fabricada em Prata legítima, teor 925, além de linda trás a simplicidade e a elegância da beleza feminina. A Prata com teor 925, é o metal mais precioso, depois do ouro. Sua legitimidade pode ser confirmada através de sua marcação nas peças e pelo certificado de garantia que oferecemos. Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Acompanha certificado que garante teor 925 do produto.', 84.0, 65.0, NULL, 'Fashion Accessories > Accessories Sets & Packages', 'https://cf.shopee.com.br/file/br-11134207-820ln-mneococb435s9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F10951192794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51752600625', 'Azeite de Oliva Extravirgem 500ml - Ouro Da Terra', 'O Azeite de Oliva Extra Virgem Português 500ml Ouro Da Terra é um produto de alta qualidade, obtido por extração a frio, preservando o sabor e as características naturais do azeite. Com acidez máxima de 0,5%, é puro, sem processos químicos, além de não conter glúten nem gorduras trans. Versátil e saboroso, é ideal para cozinhar, temperar saladas ou finalizar pratos no dia a dia. Uma opção saudável para quem busca o autêntico sabor do azeite português. Ingrediente: Óleo de Oliva Extra Virgem. NÃO CONTÉM GLÚTEN. PRODUTO DE PORTUGAL', 41.97, 41.97, NULL, 'Food & Beverages > Cooking Essentials > Oil', 'https://cf.shopee.com.br/file/br-11134207-820lg-moe22manftvneb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F51752600625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
