INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498187065', 'Escapamento Pop 100 2007 e 2008 F1 Esportivo Cromado Fortuna', '🏍️ Escapamento F1 Esportivo Cromado – Pop 100 (2006 a 2010) | Fortuna Distribuído por HB Moto Peças e Acessórios – Loja oficial dos produtos Fortuna Ofereça à sua Pop 100 mais potência, som grave e visual esportivo com o escapamento F1 Fortuna, desenvolvido com materiais de qualidade e acabamento cromado de alto padrão. ✅ Compatibilidade: ✔️ Honda Pop 100 📆 Anos: 2007 e 2008 🔧 Pronto para instalação – encaixe perfeito, sem adaptações 📋 Características Técnicas: Marca: Fortuna Modelo: F1 Esportivo Código: AF676 Material: Aço Carbono Cor: Cromado com curva cromada Linha: Honda Condição: Novo ⭐ Diferenciais: Som grave com estilo esportivo Alta durabilidade e resistência Produto com matéria-prima de primeira qualidade Compra 100% segura, com nota fiscal digital (PDF) Envio imediato com atendimento especializado Fortuna Escapamentos é sinônimo de tecnologia, inovação e qualidade no segmento de escapamentos para motos. HB Moto Peças e Acessórios garante o melhor atendimento, entrega rápida e confiança de quem é apaixonado por duas rodas! 📦 Adquira já o seu escapamento Fortuna e transforme sua pilotagem!', 267.99, 259.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rd3t-m6tlx0ujex2q0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398614987%2F22498187065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292117143', 'Kit Bule Térmico Plástico 700ml e Suporte para Filtro de Café 102 Preto Termic Sanremo', 'Olha que excelente solução para o seu dia a dia ou então para um belo presente: conjunto de bule com suporte para café. Um bule de extrema qualidade. Possui alta manutenção de temperatura, 12 horas gelado e 6 horas quente -, além de bico direcionador que evita aqueles pingos desagradáveis. O suporte para o filtro tem o mesmo padrão estético e forma uma peça única, seja para a sua casa ou ambiente de trabalho. Para melhor conservação de temperatura utilize a capacidade total deste bule: 700ml Todos os produtos Sanremo são atóxicos: livres de BPA.', 119.9, 79.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7reos-m8xhpdzyxyl5cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22292117143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19545710451', 'Pisca Natal 100 Led Colorido 9M 8 Funções - 110v', 'Pisca de Led Colorido - 110v Enfeite a sua casa, árvore de Natal, árvore de jardim, sacadas, janelas, vasos ou qualquer outro ambiente com essas lindas luzes de Natal com 8 funções. Possui 8 Funções:1 - Combinações2 - Em Ondas3 - Sequencial4 - Lenta Slow5 - Perseguindo o Flash6 - Desaparecer Lentamente7 - Flash de Brilho8 - FIXO Função: Parada - Comprimento 9 metros- Composto por 100 LED´s de alto brilho- Fio branco transparente- Luzes pisca cor colorido- Isolação dos fios transparente- Uso interno ou externo (para uso externo é preciso proteger o controle eletrônica da umidade).- Longa durabilidade.- Melhor efeito visual - Ref: NTL2100C127V- Voltagem: 110 volts- Potência máxima: 2W- Conteúdo: 1 pisca pisca Led com 100 leds, 9 metros e 8 funções', 19.49, 15.11, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/f8d0e08c2f54a48942592d165fc4860e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F19545710451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593807390', 'Kit Cuidados Higiene Manicure para Bebês com Estojo Savanna Blue KikkaBoo', 'O conjunto de manicure Savanna foi criado para atender às necessidades de cuidados dos bebês e dos pais, garantindo cuidados seguros e delicados desde o nascimento. • Higiene versátil - Ideal para as necessidades do bebê e dos pais, tornando a higiene uma experiência agradável para ambos. • Conjunto completo - Inclui tesoura, cortador de unhas e uma lixa, fornecendo todas as ferramentas essenciais para o cuidado das unhas. • Alta qualidade e segurança - Feito de materiais seguros e de alta qualidade, garantindo durabilidade e segurança para seu bebê. • Adequado desde o nascimento - Projetado para ser suave e eficaz para recém-nascidos e bebês. Mantenha as unhas do seu bebê sempre bem aparadas e bem cuidadas com o Conjunto de Manicure Savanna, que combina praticidade e segurança em um único conjunto completo.', 39.9, 19.9, NULL, 'Mom & Baby > Bath & Body Care > Baby Grooming Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd4l-m6zwtv2pjes265', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1419417476%2F22593807390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
