INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20935511216', 'Chave Combinada Jogo 6 a 32 MM com 12 Peças NOVE54', 'JOGO CHAVE COMBINADA 6-32MM AÇO CARBONO COM 12 PEÇAS SUPORTE PLÁSTICO Conteúdo da embalagem 1 Jogo de chaves combinadas, composto por um suporte plástico com 12 peças, sendo: 6 mm, 7 mm, 8 mm, 10 mm, 11 mm, 13 mm, 14 mm, 17 mm, 19 mm, 22 mm, 27 mm e 32 mm Aplicações e dicas de uso Indicado para apertar e soltar porcas e parafusos sextavados. Nunca utilizar prolongadores sobre as chaves, pois isso aumentará o torque aplicado e diminuirá a vida útil das ferramentas. Uso leve. Destaques e diferenciais Possui acabamento cromado fosco, proporcionando maior resistência contra oxidação/corrosão. Combina na mesma chave um lado fixa e outro estrela, possibilitando aplicações em locais de difícil acesso. *Imagens meramente ilustrativas', 221.63, 221.63, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/f4a08fda2169ca7f441a4b76eaf2a3d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F20935511216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694228913', 'Meia para Corrida HUPI Run, Cor Preto/Cinza, Tamanho 36-42', 'Meia para ciclismo e corrida! Conforto, design, tecnologia e qualidade são adjetivos que descrevem perfeitamente as meias HUPI. Testado e aprovado por atletas de diversas modalidades, a meia HUPI é um item indispensável para você. Praticar esportes com conforto e máximo desempenho é o seu objetivo, e também o nosso. Por isso a meia HUPI apresenta diversos destaques que fazem dela um item fundamental. O material utilizado na fabricação da meia é importado da Alemanha. Os fios de elastano e poliamida formam um conjunto cheio de vantagens. O principal destaque é o conforto, proporcionado pela transpiração que a meia oferece, deixando os pés secos e bem protegidos. A combinação da matéria prima assegura a flexibilidade oferecendo maior liberdade de movimento, sem que a peça laceie, perdendo sustentação. Na região dos dedos e calcanhar, os fios são dispostos em direções diferentes do restante da meia, fazendo com que a modelagem se torne muito mais anatômica, acompanhando o desenho dos pés. Esta característica também prolonga a durabilidade, impedindo o desgaste. Características: Cano médio de 15 cm; Composição: 95% Poliamida | 5% Elastano; Conteúdo: 1 par; Tamanho único: Veste do 36 ao 42.', 74.28, 69.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-mc6tm8ytcnu6f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F22694228913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
