INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46502617604', 'Álcool Bicarbonato Tradicional Barbarex 1 L', 'Limpeza profunda com o poder do bicarbonato! O Álcool Bicarbonato Barbarex é a escolha ideal para quem busca uma limpeza eficaz e versátil no dia a dia. Sua fórmula combina álcool com bicarbonato de sódio, potencializando a remoção de sujeiras e odores, além de deixar as superfícies com brilho e sensação de frescor. Indicado para a limpeza de pisos, azulejos, bancadas, móveis e outras superfícies laváveis, ele é perfeito para manter o ambiente limpo com praticidade. Benefícios: Ação desodorizante com bicarbonato Remove sujeiras e odores com facilidade Brilho e limpeza sem enxágue Ideal para a manutenção diária Instrução de uso Aplique o produto diretamente com um pano limpo ou flanela sobre a superfície desejada. Evite o uso em superfícies sensíveis ao álcool, como áreas enceradas, envernizadas, pintadas ou laqueadas.', 11.29, 11.29, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-820lk-mpdxbp7dpceec8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1504881529%2F46502617604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593989626', 'O Casamento de Narizinho | Monteiro Lobato', 'O livro da coleção "Trenzinho", conta algumas histórias curtas, recomendadas para crianças menores, de um dos maiores escritores da literatura infantil Monteiro Lobato. Os livros contam histórias clássicas e marcantes do escritor, com Tia Nastácia, Narizinho, Emília, Pedrinho, Visconde e entre outros, contando com dez títulos na coleção. Idade recomendada: 3 a 5 anos 29 x 22 cm 20 páginas', 13.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfgi-m9upkoujpt49bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22593989626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
