INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197453659', 'Bóia Combustível FUSCA 1959/1977 - 17747 - T090001', 'Bóia Combustível FUSCA 1959/1977 TODOS - (SEM PESCADOR – GAS.) O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 60.9, 60.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rbko-lmx65wcre6a33d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20197453659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45964412424', 'Enxaguante Bucal Colgate Plax Zero Álcool Melancia 1L Leve Mais Pague Menos', 'O Enxaguante Bucal Colgate Plax Respira e Refresca Melancia possui fórmula inovadora oferece um sabor perfeitamente equilibrado entre a doçura da melancia e o frescor da menta, entregando uma sensação de limpeza prolongada e hálito deliciosamente fresco. Com intensidade soft, ele é ideal para quem busca eficácia diária com máxima suavidade. Sem álcool e sem açúcar, o enxaguante Plax protege sua boca sem agredir ou queimar. Ele atua de forma preventiva contra os principais problemas bucais, ajudando a evitar a formação de tártaro dental, placa e cárie, graças à sua ação que elimina até 99,9% das bactérias e protege por até 12 horas. Leve para sua rotina o frescor inigualável do Colgate Plax Melancia e respire aliviado todos os dias.', 37.34, 37.34, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqwbfbl1vksjce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F45964412424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997461948', 'Palheta Limpador Para-Brisa Vw Golf 1993 a 1998 - 198401 - PVT13', 'Palheta Limpador Para-Brisa Vw Golf 1993 a 1998 198401 PVT13 13" traseira - Conexão gancho Os limpadores combinam duas tecnologias mecânicas. A primeira delas é uma combinação de motor elétrico com engrenagem redutora. Ela é responsável por gerar a força necessária para acionar os limpadores. A segunda delas é um inteligente sistema de transmissão por hastes, ela converte a rotação de saída do motor no movimento dos limpadores para de um lado para o outro.Elas funcionam como uma espécie de rodo. Estas hastes arrastam uma fina tira de borracha com a função de retirar a água.', 21.5, 21.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbn2-ln0lwt9v5iwn21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18997461948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40020149598', 'Vitamina D3 Shark Pro 2000UI 60 Cápsulas', 'Leve agora sua Vitamina D3 Shark Pro e mantenha uma rotina de cuidado simples, com dose clara, 60 cápsulas e compra segura. Você quer cuidar melhor da sua saúde, mas não quer ficar em dúvida sobre dose, quantidade ou procedência do produto. A Vitamina D3 Shark Pro 2000 UI foi pensada para deixar esse cuidado mais simples: uma cápsula, uma rotina, uma decisão fácil de entender. Com 60 cápsulas e 2000 UI de vitamina D por porção, ela ajuda a organizar a suplementação diária sem complicação. O uso indicado pela Shark Pro é de 1 comprimido ao dia, preferencialmente junto a uma refeição, ou conforme orientação profissional. A vitamina D tem alegações reconhecidas de auxílio à formação de ossos e dentes, absorção de cálcio e fósforo, funcionamento do sistema imune, funcionamento muscular e manutenção dos níveis de cálcio no sangue. Por isso, a comunicação correta é sempre “auxilia”, sem prometer cura, prevenção ou resultado garantido. Dose clara em cada cápsula 2000 UI de vitamina D3 por porção. Rotina simples 1 cápsula ao dia junto a uma refeição, conforme orientação do rótulo. 60 cápsulas por embalagem Mais organização para a rotina de suplementação. Compra com menos dúvida Avaliações destacam que o produto chegou certinho e igual ao anúncio. Informação segura Use linguagem responsável: vitamina D auxilia funções do organismo, sem promessas médicas.', 59.9, 29.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820m3-mptchrojt5he04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662618933%2F40020149598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099030412', 'Reparo Molas Sapata Gm C10 1972 a 1989 - 204119 - 222/227', 'Reparo Molas Sapata Gm C10 1972 a 1989 204119 222/227 (1 RODA - TRASEIRA) (DIREITA/ESQUERDA) (SISTEMA BENDIX) Função: É responsável pelo retorno das sapatas após a frenagem. Aplicação: Normalmente nas rodas traseiras. Mas pode ser aplicado nas rodas dianteiras em modelos com freio a tambor dianteiro. Funcionamento: Trabalha exercendo força contrária ao cilindro de roda. Também é responsável pela fixação e alinhamento das sapatas no espelho. Características: Molas fabricadas em aço com alto teor de carbono (SAE 1070)', 43.18, 43.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rbks-ln00gp8jad1457', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18099030412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094186897', 'Limpador Perfumado Lavanda Sanol 500 ml', 'Traga mais leveza e perfume à sua rotina de limpeza com o Limpador Perfumado Lavanda Sanol 500 ml. Com fórmula versátil e fragrância clássica de lavanda, ele remove sujeiras como gordura e poeira com facilidade, deixando os ambientes limpos e com um aroma suave e relaxante que dura por horas. Compacto e eficiente, é ideal para o uso diário em pisos, azulejos, pias, bancadas, fórmicas, geladeiras, fogões e até vidros. Sua composição à base de água garante uma aplicação segura e sem cheiro forte, tornando a limpeza mais agradável e tranquila. 🪻 Destaques do Produto • Limpeza eficaz com perfume prolongado • Fragrância de lavanda com toque floral relaxante • Fórmula à base de água, sem cheiro forte • Ideal para superfícies laváveis em geral • Embalagem prática de 500 ml 🧴 Modo de Uso - Para limpeza leve: dilua 100 ml em 5 litros de água - Para sujeiras mais difíceis: aplique puro com pano ou esponja - Enxágue se necessário - Não misture com outros produtos 📋 Informações Técnicas Marca: Sanol Produto: Limpador Perfumado Linha: Lavanda Fragrância: Lavanda Volume: 500 ml Aplicação: Uso geral em superfícies laváveis ✨🏠 Perfume, praticidade e cuidado em cada aplicação. Experimente o Limpador Perfumado Lavanda Sanol 500 ml e transforme sua casa com frescor e bem-estar. Adquira agora!', 9.66, 9.66, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7ra1v-mbmgwb3iid2fdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1457212056%2F23094186897', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44160808184', 'Livro Blocão de colorir Natan por aí - Cores iradas', 'Do Youtube para as páginas, Natan chega com um convite bem especial para você:Separe seus lápis de cor e deixe a imaginação voar enquanto pinta com muitas cores cada página deste livro. Vamos lá, colmeia? _x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Paloma Blanca_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 35.00 x A 27.00 x E 0.20_x000D_ ISBN: 9786526123164_x000D_ Coleção: Meu blocão de colorir_x000D_ Linha Editorial: Ciranda Cultural - Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Colorir, Amizade, Descoberta, Diversão, Pintura, Cores, Brincadeira, Youtube, Youtuber_x000D_ BISAC: Não Ficção Infantil / Não Ficção Infantil / Mídia Tie-in_x000D_ Linha de Produto: Blocão de colorir_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdy9-mcs8cbe6ykg07f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F44160808184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594369043', 'GIN ROCKS STRAWBERRY 1000ML', 'O Gin Rock’s Strawberry é obtido pela destilação de um composto alcoólico, na presença de bagas de zimbro, carregando em seu fluxo os aromas e caracteristicas dessa matéria prima, que combinado com o toque levemente rosa, aroma e sabor do morango o torna um produto único. Quanto à maneira de beber, em geral, é servido no tradicional drink gin-tônica: água tônica, uma ou duas doses de gin, rodelas de limão e bastante gelo. O gin também pode compor diversos outros coquetéis, misturado com vermute ou licor de menta, por exemplo, sempre com bastante gelo.', 42.99, 33.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me8qbemc9hc091', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23594369043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094650304', 'Forno Elétrico Philco PFE65 65L Preto/Inox', 'Forno Elétrico 65L Philco Dupla Resistência PFE65 O Forno Elétrico 65L Philco Dupla Resistência PFE65 é a escolha perfeita para quem busca versatilidade e eficiência na cozinha. Com sua generosa capacidade de 65 litros e alta potência, ele garante o preparo de suas receitas favoritas com facilidade e precisão. Desfrute de um cozimento uniforme e resultados impecáveis, seja assando, grelhando ou descongelando. Sua tecnologia de dupla resistência e controle de temperatura oferece a flexibilidade necessária para explorar um mundo de sabores, economizando tempo e garantindo refeições deliciosas para toda a família. Principais Atributos: Capacidade de 65 Litros: Espaço interno amplo, ideal para assar grandes pratos e atender a toda a família. Controle Preciso de Temperatura: Seletor de temperatura de 90°C a 230°C, perfeito para diversos tipos de receitas. Resistência Dupla com Seletor: Permite escolher entre aquecimento superior, inferior ou ambos, para um cozimento personalizado. Timer de 120 Minutos: Com sinal sonoro, oferece conveniência e evita que seus pratos passem do ponto. Lâmpada Interna: Facilita a visualização do alimento durante o preparo, sem a necessidade de abrir a porta. Caracteristicas: Marca: Philco Modelo: PFE65 Cor do Produto: Painel em aço e corpo em preto Composição: Plástico, aço e vidro Tipo de Forno: Bancada Capacidade: 65L Temperatura de Funcionamento: 90°C a 230°C Timer: 120 minutos com sinal sonoro Número de Resistências: Dupla Funções: Aquece, assa, tosta, gratina, grelha e descongela Sistema de Abertura de Porta: Manual Tamanho do Cordão: 95cm Peso do Produto: 8,06 Kg Dimensões do Produto: Altura 34,90 cm x Largura 58,30 cm x Comprimento 45,30 cm Dimensões do Produto Embalado: Altura 37,50 cm x Largura 63,50 cm x Comprimento 48,40 cm Itens Inclusos: Forno Elétrico PFE65, grelha deslizante, coletor de resíduos e Manual de Instruções Garantia: 12 meses do Fabricante Atenção: 1. Verifique a voltagem do produto antes de realizar a compra para certificar-se de que corresponde à da sua região. 2. Este produto possui plugue de 3 pinos. Certifique-se de que sua tomada é compatível com este padrão.', 809.9, 804.9, NULL, 'Home Appliances > Kitchen Appliances > Ovens', 'https://cf.shopee.com.br/file/sg-11134201-8257v-mgclltrgswlpb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1060724397%2F22094650304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21672678473', 'Livro Maria Clara e JP - É hora de brincar!', 'Maria Clara é uma garota esperta e animada! João está sempre animado e gosta de vários jogos diferentes! Pegue seus lápis de cor e prepare-se para muita diversão com as atividades e os desenhos de colorir dessa duplinha!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2022_x000D_ Autor: Marina Evangelista_x000D_ Idioma: Português_x000D_ Páginas: 16_x000D_ Dimensões: L 21.00 x A 28.00 x E 1.60_x000D_ ISBN: 9786526100288_x000D_ Coleção: Atividades e diversão_x000D_ Linha Editorial: Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Super-herói, Diversão, Aventura, Colorir, Pintar, Aprendizado_x000D_ BISAC: Literatura Infantil / Mídia Tie-in_x000D_ Linha de Produto: Grampeado com lápis de cor_x000D_ Encadernação: Grampeado_x000D_ Acabamento: Não se aplica_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-23020-79piidzcm0mv6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21672678473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8472222472', 'Livro - Alfabeto - Ciranda Cultural', 'Neste livro, você vai aprender a escrever todas as letras do alfabeto, bem como treinar a coordenação motora. Contorne, siga os pontilhados e veja como aprender pode ser divertido. Editora: Ciranda Cultural Edição: 2, 2020 Autor: Flaper Idioma: Português Páginas: 32 Dimensões: L 26.80 x A 20.10 x E 0.10 ISBN: 9786555001242', 9.9, 6.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/79e572cf321af87f124e94bea4083ca7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8472222472', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27786944935', 'Livro Cartonado Uma padaria deliciosa', 'Venha conhecer a padaria de Julieta e aprender muitas palavras com este livro colorido e cheio de ilustrações._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Kathryn Selbert_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 15.00 x A 24.00 x E 1.40_x000D_ ISBN: 9786526121221_x000D_ Coleção: Minha rua animada_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Palavras, Primeiros conceitos, Aprendizado_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Conceitos / Palavras_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Cartonado', 44.9, 44.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rav3-ma8ixmfkh4kn1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F27786944935', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994913743', 'GA.MA ITALY Secador Gama G-Evo X 2000W Nac', 'DESCRIÇÃO SECADOR G-EVO X O G-EVO X foi desenvolvido para quem busca resultados de salão com o máximo de conforto. Compacto e ergonômico, ele combina 2000W de potência com a tecnologia Ultra Ion, garantindo um acabamento profissional e livre de frizz. Destaques de Performance: • Motor Profissional X8: Uma nova geração de motores AC que proporciona um fluxo de ar potente e constante para uma secagem ultrarrápida. Desfrute da eficiência de um secador de salão no conforto da sua casa. • Tecnologia 3D Therapy Ultra Ion: Ultra emissão de íons negativos que restauram a estrutura molecular do cabelo de dentro para fora, devolvendo a umidade natural, garantindo brilho, maciez e efeito antifrizz duradouro. Versatilidade e Conforto: • Controle Total: 3 temperaturas e 2 velocidades para personalizar a secagem de acordo com o seu tipo de cabelo e estilo desejado. • Jato de Ar Frio Instantâneo: Fixe o penteado e adicione um brilho extra com um toque de ar frio no final da secagem. • Filtro Removível: Facilita a limpeza e manutenção, prolongando a vida útil do seu secador. • Cabo de 3 Metros: Total liberdade de movimento! O cabo longo e flexível permite que você se movimente livremente sem se sentir presa à tomada. Ideal para quem valoriza praticidade e facilidade de uso. • Design Leve, Compacto e Ergonômico: Manuseio confortável e sem fadiga, mesmo durante o uso prolongado', 449.9, 329.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-82616-mmg9e8s30ah1a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F964602453%2F23994913743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092353299', 'Kit com 3 Sutiãs sem Aro e sem Bojo Demillus 61196/61096 Taça B', 'Detalhes DeMillus Kit com 3 Sutiãs Olimpo Bourbon DeMillus 61196 Ótima sustentação. Taças em elastano cotolê duplo, sem aro e sem espuma. Clássico e confortável para o dia-a-dia. Observação: Esse modelo substitui os antigos 78096 e 61096, agora as taças são maiores e mais confortável, o cós mais longo na dimensão aproximada do 61818, o elástico do cós é liso e sem o relevo com logotipo DeMillus. Características: Sutiã sem aro e sem bojo em tecido duplo. Alças largas e reguláveis. Costas com fecho em colchetes duplo de tripla regulagem. Com toque macio, suave e super confortável. Ótima sustentação. Outros Detalhes: Taça B. Cores Branco:Todos branco Vinho:Todos vinho Bege:Todos bege Preto:Todos preto Composição: 93% Poliamida e 17% Elastano.', 178.7, 178.7, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/sg-11134201-7rbkh-llf4lkxw8rrv2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F770021950%2F23092353299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698054478', 'Almofada Apoio Halter Mini Grid - Loja Fom', 'A almofada Halter Mini Grid foi desenvolvida com inclinações que acompanham a curvatura do corpo em toda sua extensão, oferecendo um apoio anatômico, firme e confortável. A cintura do meio acomoda o pescoço, ou a coluna lombar, preenchendo espaços vazios entre o encosto e o corpo. A almofada ergonômica Halteres também é ótima para dormir, podendo ser usada entre os joelhos, quando deitado de lado; sob os joelhos, quando dormindo de barriga para cima; ou sob o abdômen e dorso dos pés, se deitado de bruços. Em todas as posições, o uso de uma almofada nas pernas alivia a pressão, alinhando o quadril e a coluna.', 198.0, 198.0, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-m6rcyl8mk1az13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1366041969%2F18698054478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206327145', 'RETENTOR BENGALA PAR GSF BANDIT 600 N 00 A 04', 'PAR DE RETENTORES DE BENGALA Compatibilidade: SUZUKI GSF BANDIT 600 N de 2000 até 2004 Alta qualidade, vedação precisa e maior durabilidade: retentor de bengala ORIGINAL Parts é produzido em NBR de alto desempenho, desenvolvido para resistir a atrito, calor e contato com o fluido da suspensão. Produto novo, à pronta entrega, com garantia, compatível exclusivamente para os anos descritos abaixo. SUZUKI GSF BANDIT 600 N 2000 SUZUKI GSF BANDIT 600 N 2001 SUZUKI GSF BANDIT 600 N 2002 SUZUKI GSF BANDIT 600 N 2003 SUZUKI GSF BANDIT 600 N 2004 Este produto refere-se a: 2 (duas) unidades de retentor de bengala com mola dupla, marca ORIGINAL Parts SKU: RTK-1513 MEDIDAS NOMINAIS: Medida nominal do retentor: DC 41 * 53 * 8/9.5 (Mola Dupla) Marca da suspensão OEM na montadora: KAYABA Tipo de suspensão: Telescópica convencional O QUE É? O retentor de bengala é responsável por evitar o vazamento do fluido interno da suspensão dianteira, garantindo o funcionamento correto, a vedação precisa e a durabilidade do sistema. SERVE EM OUTRA MOTO? Não. Mesmo que outras motos tenham peças parecidas, as medidas podem ser diferentes. Este produto é exclusivo para o modelo de moto e anos indicados acima. Se tiver dúvidas, entre em contato com nosso suporte técnico antes da compra. Consulte também a política de trocas e devoluções. MEDIDAS CONFIÁVEIS As medidas seguem rigorosamente o padrão original da moto e são 100% calibradas. Você pode confiar na precisão técnica dos nossos retentores. GARANTIA Este item tem 90 dias de garantia contra defeitos de fabricação. Fatores externos como mau manuseio ou montagem sem ferramentas adequadas, que possam danificar o produto, não são cobertos pela garantia, configurando mau uso. RECOMENDAÇÃO IMPORTANTE Ao substituir este item, verifique também os demais componentes da suspensão da sua moto. Consulte nossa linha ORIGINAL Parts TECHCILINDROS para um reparo completo e seguro. SOBRE A MARCA A TECHCILINDROS atua desde 2008, oferecendo qualidade e variedade em tubos de bengala para motos de média e alta cilindrada, atendendo mais de 90% do mercado nacional. Em 2018, lançou a marca ORIGINAL Parts, com componentes premium de vedação e suspensão, garantindo mais segurança e durabilidade.', 36.05, 36.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-82606-mlgpxbxbgwlccb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609848355%2F58206327145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393410668', 'Sofás 2 Lugares Larissa Preto', 'Que tal o Sofá Larissa?A sua sala de estar só está completa na presença de um bom sofá e nada mais gostoso do que receber a família ou curtir os seus momentos de descanso junto com o modelo Larissa! Pensado para quem quer aliar bom gosto + uma estrutura reforçada para o uso diário, a peça tem madeira reflorestada na composição e revestimento de toque agradável com o corpo para garantir que a receptividade seja plena. Já o visual elegante de coloração tradicional a esse tipo de móvel fecha com chave de ouro os benefícios que ele oferece para o seu doce lar ;) Garantia em Meses: 3 Cores do Produto: Preto Instruções/Cuidados: Limpar com pano úmido com água. Conteúdo da Embalagem: 1 Sofá (Acompanha 2 almofadas) - Entregue em: 1 Volume Modelo: Comum Número de Volumes: 1 Material: O sofá Larissa tem sua estrutura em madeira reflorestada (eucalipto e pinus) e chapa OSB, com enchimento do assento em espuma D33 e encosto em D23, já o revestimento é revestimento sintético. Material para Filtro: Madeira de Reflorestamento Descrição do Tamanho: Altura: 88 cm | Largura: 174 cm | Profundidade: 94 cm Altura do Produto (cm): 88 Largura do Produto (cm): 174 Comprimento do Produto (cm): 94 Produto precisa de Montagem?: Não Tipo de Encosto: Fixo Quantidade de Peças: 1 Tipo de pé: Fixo Altura do assento até o chão (cm): 46 Acompanha banco/puff: Não É giratório: Não Material da estrutura: Madeira de Reflorestamento Material do enchimento do assento: Espuma D33 Material do enchimento do encosto: Espuma D23 Material do Revestimento: Revestimento Sintético Possui Baú?: Não Tipo de assento: Fixo PROFUNDIDADE x LARGURA x ALTURA: 94 x 174 x 88 Fornecedor: Linoforte Móveis Ltda É com chaise: Não É de canto: Não É sofá-cama: Não Tipo de produto: Sofá Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Is Fragile: Não Tipo do Sofá: Número da peça: Não Produto: Sofá Inclui manual de montagem: Não 0: null', 1149.88, 973.1, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rd5h-m6s78xj3kwf5e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F23393410668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299192886', 'Kit Limpeza E Hidratação Motul Capacete Mc Care M1 + M2 antibactericida', 'Loja Ofical MOTUL A Motul é uma empresa francesa com mais de 165 anos de experiência na produção e distribuição de lubrificantes e fluidos de qualidade para motores. Ela é pioneira em inovação, tendo desenvolvido o primeiro lubrificante automotivo 100% sintético do mundo. Presente em mais de 160 países, a Motul chegou ao Brasil em 1992 e é conhecida por sua participação em competições automobilísticas de renome mundial. As pistas de corrida são o laboratório principal da empresa, onde seus produtos são testados em condições extremas antes de serem lançados no mercado. Representante OFICIAL MOTUL: BROOKLIN RACE uma das principais lojas de São Paulo referência no segmento automotivo em vendas de lubrificantes, pneus e acessórios para o segmento, com forte presença na Shopee. Nosso compromisso é proporcionar uma experiência de compra excepcional, oferecendo produtos de alta qualidade a preços competitivos. Valorizamos o suporte ao cliente, estando disponíveis para auxiliar tanto na pré-venda quanto no pós-venda, garantindo que todas as dúvidas sejam esclarecidas e quaisquer problemas sejam prontamente resolvidos. Estamos empenhados em superar suas expectativas e tornar sua jornada conosco memorável. COMPRANDO ATÉ ÀS 16:00+ DESPACHAMOS NO MESMO DIA. MOTUL MC CARE M1 HELMET & VISOR CLEAN 250 ML Características: Condição do item: Novo Marca: Motul MPN: 102992 Número de peça: 102992 Número de registro/certificação INMETRO: - OEM: 102992 "Limpador neutro e não-agressivo para o exterior e viseiras de capacetes. Limpa o exterior do capacete e viseira sem deixar marcas." Limpeza capacete MOTUL MC CARE M2 HELMET INTERIOR CLEAN Características: Condição do item: Novo Marca: Motul MPN: 105504 Número de peça: 105504 Número de registro/certificação INMETRO: - OEM: 105504 Limpador bactericida para o interior do capacete. Limpa e neutraliza profundamente os odores. Garantia do vendedor: 3 meses', 142.43, 128.19, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqnc35370vtz6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F18299192886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093099302', 'Brinquedo infantil casa da masha e urso com atividades Cotiplas 2401', 'A casinha da masha e o urso mais querido do momento, a Casinha da Masha é uma excelente opção para seu bebê poder se entreter nas brincadeiras. Contém blocos didáticos para encaixar e a bolinha desce pela chaminé, é super divertido! Um ótimo brinquedo para desenvolver coordenação motora, auxilia a distinção de formas, cores e som. Vem embutido também uma alça para transportar a casinha da Masha. Características: - Marca: Cotiplás - Modelo: 2401 Imagens meramente ilustrativas Ficha Técnica: - Dimensões: (A x L x C) 25 x 29 x 33 cm - Produto 100% seguro para o seu bebê. - Certificação: CE-BRI/0228 NM 300/2002 - Peso: 890 gramas - Altura montado: 37cm Conteúdo da Embalagem: - 1x Casinha - 1x Bolinha - Peças geométricas - Masha - Urso - Atividades - Casa - Brinquedo - Cotiplás - Infantil - Didático - Desenho - Bebê - Encaixar - Educativo', 92.0, 92.0, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rd51-lwfu7erluqoqb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F22093099302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497982390', 'Kit 3 Geleias Linea Sabor Pimenta Vermelha, Frutas Vermelhas e Mirtilo de 230g', 'Geleia Linea é cremosa, sem adição de açúcares, repleta de sabor e pedaços da fruta. Essa delícia é 64% menos calórica que geleias com açúcar. Uma explosão de doçura saudável para transformar suas refeições. 1 KIT COMPOSTO POR: -1 Geleia De Pimenta Vermelha Linea 230g -1 Geleia De Frutas Vermelhas Linea 230g -1 Geleia De Mirtilo Linea 230g INGREDIENTES GELEIA DE PIMENTA VERMELHA: pimenta biquinho triturada*, suco de limão, concentrado de pimenta dedo de moça, edulcorantes: maltitol, eritritol e glicosídeos de steviol, estabilizante pectina, aromatizantes,, conservador sorbato de potássio e agente de firmeza fosfato tricálcico. *fornece quantidades não significativas de açúcares. NÃO CONTÉM GLÚTEN. INGREDIENTES GELEIA DE FRUTAS VERMELHAS: morango, amora, framboesa, edulcorantes: sorbitol e sucralose, estabilizador de pectina, regulador de acidez ácido cítrico, conservador sorbato de potássio, agente de firmeza fosfato tricálcico e antioxidante ácido ascórbico. INGREDIENTES GELEIA DE MIRTILO: mirtilo triturado, edulcorantes: sorbitol e sucralose, estabilizante pectina, acidulante ácido cítrico, conservador sorbato de potássio, agente de firmeza fosfato tricálcico, antioxidante ácido ascórbico.', 101.99, 69.35, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Jam & Spread', 'https://cf.shopee.com.br/file/sg-11134201-7rdyw-m1itpx83rn7s80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F22497982390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594847289', 'BUCHA GUIA BENGALA PAR CB 500 97 A 05', 'PAR DE BUCHAS GUIA DE BENGALA Compatibilidade: HONDA CB 500 de 1997 até 2005 Alta qualidade e maior desempenho: bucha guia de bengala ORIGINAL Parts produzida com revestimento em PTFE (teflon), garantindo baixo atrito, maior durabilidade da suspensão e proteção do cromo da bengala. Produto novo, à pronta entrega, com garantia, compatível exclusivamente para os anos descritos abaixo. HONDA CB 500 1997 HONDA CB 500 1998 HONDA CB 500 1999 HONDA CB 500 2000 HONDA CB 500 2001 HONDA CB 500 2002 HONDA CB 500 2003 HONDA CB 500 2004 HONDA CB 500 2005 Este produto refere-se a: 2 (duas) unidades de bucha guia da bengala com PTFE (teflon) interno, marca ORIGINAL Parts SKU: GBK-1283 MEDIDAS NOMINAIS: Medida nominal da bucha guia: 37 * 41 * 15 Marca da suspensão OEM na montadora: SHOWA Tipo de suspensão: Telescópica convencional O QUE É? A bucha guia de bengala é responsável por alinhar e sustentar o tubo interno dentro da suspensão dianteira, reduzindo o atrito e garantindo o deslizamento suave das hastes. É essencial para preservar o cromo e manter o funcionamento correto da suspensão. SERVE EM OUTRA MOTO? Não. Mesmo que outras motos tenham peças parecidas, as medidas podem ser diferentes. Este produto é exclusivo para o modelo de moto e anos indicados acima. Se tiver dúvidas, entre em contato com nosso suporte técnico antes da compra. Consulte também a política de trocas e devoluções. MEDIDAS CONFIÁVEIS As medidas seguem rigorosamente o padrão original da moto e são 100% calibradas. Você pode confiar na precisão técnica das nossas buchas guia. GARANTIA Este item tem 90 dias de garantia contra defeitos de fabricação. Fatores externos como mau manuseio ou montagem sem ferramentas adequadas, que possam danificar o produto, não são cobertos pela garantia, configurando mau uso. RECOMENDAÇÃO IMPORTANTE Ao substituir este item, verifique também os demais componentes da suspensão da sua moto. Consulte nossa linha ORIGINAL Parts TECHCILINDROS para um reparo completo e seguro. SOBRE A MARCA A TECHCILINDROS atua desde 2008, oferecendo qualidade e variedade em tubos de bengala para motos de média e alta cilindrada, atendendo mais de 90% do mercado nacional. Em 2018, lançou a marca ORIGINAL Parts, com componentes premium de vedação e suspensão, garantindo mais segurança e durabilidade.', 41.03, 41.03, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-8260p-mk2fy29sqqde76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609848355%2F22594847289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597797751', 'Bíblia em Ordem Cronológica | NVI Letra Normal | Capa Luxo Vermelho / Mostarda', 'Bíblia NVI em Ordem Cronológica A Bíblia em ordem cronológica é uma ferramenta indispensável para os estudiosos da Palavra de Deus. Em vez de se deter nos meticulosos recortes das Escrituras, o leitor terá diante de si um bem engendrado quebra-cabeça dos acontecimentos históricos. Nunca a linha dos acontecimentos históricos relacionados à Bíblia esteve tão bem representada. O esforço de ordenar a Bíblia cronologicamente representa mais um degrau para uma melhor compreensão das Escrituras. Desfrute desta valiosíssima ferramenta para conhecer com maior profundidade a Palavra de Deus.', 180.09, 180.09, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgpezfdbtm2o8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F20597797751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
