INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43350906272', 'Livro Meu Primeiro Livrinho de Banho | Livro Contraste | Números', 'Meu Primeiro Livrinho de Banho | Livro Contraste | Números Meu Primeiro Livrinho Contraste de Banho - Números é ideal para apresentar os números aos bebês de forma lúdica e segura. Com imagens contrastantes e páginas à prova d''água, ele estimula o desenvolvimento sensorial e torna o banho um momento educativo e divertido! Especificações do livro Meu Primeiro Livrinho de Banho | Livro Contraste | Números: Título: Meu Primeiro Livrinho de Banho | Livro Contraste | Números Subtítulo: Livro Contraste | Numeros 1-2 Ano de Edição: 2024 Capa: Almofadada Acabamento: Laminação Fosca Miolo: Resistente à Água Páginas: 8 Dimensões: Altura: 15,5 cm Largura: 15,5cm Profundidade: 3 cm Peso: 0,048 kg ISBN: 9786561262705 Editora: Online', 13.13, 13.13, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kp69xj894p9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43350906272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398317453', 'Kit 2 Chupetas Dia e Noite Brilha no Escuro 6m+ Lilás Lillo', 'Kit 2 Chupetas Dia e Noite Brilha no Escuro 6m+ Lilás – Lillo O Kit 2 Chupetas Dia e Noite Lillo acompanha duas chupetas com estampas exclusivas. Especialmente desenvolvidas com bordas arredondadas, bico em silicone macio e flexível e livre de BPA. Seus desenhos são divertidos, coloridos e a versão noite da chupeta possui tecnologia que brilha no escuro podendo ser encontrada facilmente, sem precisar acender a luz. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Tamanho do Bico: Nº2 (6m+) - Bordas arredondadas - Livre de BPA - Bico em Silicone macio e flexível - Possui argola que permite o uso de prendedores. - Brilha no Escuro. Especificações Técnicas: - Conteúdo da Embalagem: 02 Chupetas Tamanho 2. - Composição/Material: Polipropileno e Silicone - Garantia: 90 Dias (Contra Defeito de Fabricação Pelo fabricante) - Certificação: CE-PUR /IQB-000637 - Código do Fabricante: 637630 - EAN: 7896033201797 - Marca: Lillo Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 27.9, 27.9, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/sg-11134201-824h9-mf4g876k4etof5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624228750%2F19398317453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22130824733', 'Mangá Messias - Será que Ele veio para salvar...ou destruir o mundo?', 'Mangá Messias Será que Ele veio para salvar...ou destruir o mundo?Diretamente das páginas do livro mais vendido do mundo... vem a história mais grandiosa que já se ouviu... sobre o homem mais polêmico que já existiu sobre a face da Terra... e que aqui é contada no formato gráfico mais genial do planeta. Baseado exclusivamente em histórias bíblicas, este volume aborda os 4 evangelhos. O MANGÁ MESSIAS É TODO COLORIDO! O estilo mangá nasceu no Japão. Lá, a palavra mangá quer dizer apenas gibi. Mas, fora daquele país, o conceito de mangá está vinculado ao desenho característico dos gibis japoneses, um estilo que ganhou popularidade fenomenal e se espalhou pelo mundo afora. Título: Mangá Messias - português Código: 12221 Autor: Editora Next Editora: Vida Nova Páginas: 288 Formato: 14 x 21 cm Peso: 330 g. Acabamento: Brochura/Colorido ISBN: 9788527504003 Categorias: Mangá - Jovens - Adolescentes Edição: 2008', 51.91, 51.91, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/br-11134201-23030-56zddisnihovfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22130824733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698077918', 'Estojo de Brocas 3 a 8mm com 15 Peças Mini X-line 2607017504 BOSCH', 'Estojo de Brocas 3 a 8mm com 15 Peças Mini X-line BOSCH O Estojo de Brocas 3 a 8mm com 15 Peças Mini X-line BOSCH é a escolha ideal para quem busca versatilidade e eficiência em diferentes tipos de perfuração. Com um conjunto completo de brocas de alta qualidade, esse kit atende às mais diversas necessidades, proporcionando um desempenho excepcional em madeira, metal e alvenaria. O estojo inclui brocas com diâmetros variados entre 3,0mm e 8,0mm, garantindo ampla cobertura para diferentes tipos de trabalhos, seja em ambientes domésticos, profissionais ou industriais, as brocas de aço rápido são projetadas para aplicações em metal, oferecendo resistência ao desgaste e alto poder de perfuração. Já as brocas com ponta de metal duro são ideais para trabalhos em alvenaria, proporcionando cortes precisos e maior durabilidade mesmo em materiais mais rígidos. Além disso, o kit conta com brocas de três pontas para madeira, garantindo perfurações limpas e sem rebarbas, facilitando ainda mais o trabalho com esse tipo de material, acompanha um estojo compacto e robusto que permite armazenar e transportar todas as peças de forma organizada e segura. Esse design inteligente evita perdas e facilita o acesso às brocas, otimizando o tempo de trabalho. Além disso, a caixa possui um encaixe preciso para cada peça, garantindo que as brocas fiquem bem acomodadas e protegidas contra impactos e desgastes. Indicado para uso em furadeiras e parafusadeiras, o Estojo de Brocas Mini X-line BOSCH se destaca pela sua compatibilidade e praticidade. Com esse conjunto, é possível realizar trabalhos com mais eficiência e precisão, seja na montagem de móveis, instalações elétricas, reformas ou construção civil. A qualidade Bosch, reconhecida mundialmente, assegura um produto durável, resistente e confiável, sendo um investimento essencial para quem precisa de ferramentas de alto desempenho no dia a dia, seja para uso profissional ou doméstico, esse jogo de brocas proporciona uma solução completa para diversas aplicações, garantindo perfurações precisas e seguras em diferentes tipos de materiais. Com um excelente custo-benefício e um design funcional, o Estojo de Brocas 3 a 8mm com 15 Peças Mini X-line BOSCH é a escolha perfeita para quem busca praticidade, organização e eficiência em um só produto. VANTAGENS E BENEFÍCIOS Versatilidade para Diferentes Materiais: Inclui brocas para madeira, metal e alvenaria, permitindo uma ampla variedade de aplicações. Alta Qualidade e Durabilidade: Brocas de aço rápido e com ponta de metal duro para maior resistência ao desgaste e vida útil prolongada. Perfuração Precisa e Eficiente: Brocas projetadas para cortes limpos, minimizando rebarbas e garantindo acabamentos profissionais. Estojo Compacto e Organizado: Design robusto que protege e acomoda todas as peças, facilitando o transporte e evitando perdas. Compatibilidade Universal: Ideal para furadeiras e parafusadeiras, atendendo tanto a profissionais quanto a usuários domésticos. Fácil Identificação e Acesso: Encaixe preciso para cada broca no estojo, garantindo praticidade na hora do uso. Desempenho Superior em Materiais Rígidos: Brocas reforçadas para perfuração eficiente em superfícies mais resistentes. Custo-benefício Excelente: Combina qualidade Bosch com um conjunto completo para diversas necessidades de perfuração. DADOS TÉCNICOS Tipo de Fixação: Haste Cilíndrica Quantidade Peças: 15 Aplicação: Metal, Madeira e Concreto Acabamento: Retificado Revestimento: Não Tipo de Canal: Helicoidal Direção Corte: Direito 5 Brocas para Metal: Ø3/4/5/6/8mm 5 Brocas para Concreto Ø3/4/5/6/8mm 5 Brocas para Madeira Ø3/4/5/6/8mm Medidas da embalagem (AxLxC)(cm): 31,5 x 27 x 35 Peso: 0,307Kg Garantia: 6 meses Referência: 2607017504-000 Marca: BOSCH * Imagens meramente ilustrativas.', 85.9, 74.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd69-m7s9uqkx1wcjc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F21698077918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53055785821', 'Caixa Com 10 Bíblias Salvos Rosa Arc - Bíblia Evangelismo', 'Caixa com 10 Bíblias | Exclusivas Plenitude Bíblias Pequenas | ARC | Capa Brochura Salvos Pela Graça RosaFormato compacto (10,5x14,5cm), ideal para levar na bolsa Esta caixa contém 10 unidades da Bíblia Sagrada, uma opção prática e elegante para evangelismo ou para carregar na bolsa. Com a renomada tradução da versão ARC (Revista e Corrigida) de João Ferreira de Almeida, a mais amplamente utilizada pelos evangélicos do Brasil, ela oferece uma experiência única e reverente de leitura das Escrituras Sagradas. A tradução, realizada pelo missionário português João Ferreira de Almeida, é fiel aos textos originais e se destaca pela sua linguagem nobre e culta, permitindo ao leitor uma imersão profunda na Palavra de Deus. Características especiais: Palavras de Deus em Azul: Um toque especial para destacar a comunicação direta do Senhor.Palavras de Jesus em Vermelho: As preciosas palavras do Salvador em destaque vibrante.Promessas em Destaque: Frases inspiradoras que trazem conforto e esperança, reforçando a mensagem divina.Perfeita para quem deseja levar a Palavra de Deus para onde quer que vá, com a qualidade e a reverência que ela merece. Especificações da Bíblia: Título:Bíblia Sagrada Linguagem:Almeida Revista e Corrigida | ARCCapa:Capa Brochura RosaPáginas:640 (cada)Letra:PequenaFormato:10,5 x 14,5 x 2,5 cmPeso:2.140 kgISBN:9786583509055Editora:Plenitude Distribuidora', 99.95, 99.95, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825zk-mk9txf6qvrpc5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F53055785821', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19807533123', 'Dicionário Bíblico Universal | A , R , Buckland', 'Dicionário Bíblico Universal Esta obra procura guiar o leitor a um exame cuidadoso da Bíblia auxiliando o nos seus estudos por meio de artigos sobre o texto das Sagradas Escrituras as suas versões a crítica e a inspiração Aborda também doutrinas de caráter essencial como a Trindade a expiação a justificação a regeneração e assuntos semelhantes Com este dicionário você vai conhecer melhor a Bíblia seus personagens principais o ambiente em que atuaram as doutrinas fundamentais da fé cristã livros datas autores e muito mais Um instrumento valioso que já ajudou milhares de leitores em todo o mundo Está tudo aqui descobertas que podem mudar a maneira como você se vê e vive a vida; é também um guia prático para a aplicação dessas descobertas Descubra como aplicar sua surpreendente ordem de atributos pessoais de forma a produzir confiança liberdade esclarecimento e significado que podem vir somente do seu Criador Título Dicionário Bíblico Universal Autor A R Buckland Páginas 624 Formato 21 x 14 x 1 cm Peso 0 770 kg ISBN 9788573679861 Editora Vida', 68.01, 68.01, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/765f585cb1e2b50dcdbc192d6f249256', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19807533123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
