INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203584923', 'CONJUNTO COLAR E BRINCO PONTO DE LUZ ALICE ZIRCÔNIA FOLHEADO A OURO 18K', 'O conjunto Alice foi desenvolvido para mulheres que buscam sofisticação, brilho e versatilidade em uma única joia. Com corrente veneziana folheada a ouro 18K, ele traz um caimento delicado e moderno, enquanto o pingente e os brincos de ponto de luz em zircônia cristal garantem luminosidade impecável, elevando qualquer look – do casual ao mais elegante.&Lt;br> Cada peça é cuidadosamente acabada para oferecer durabilidade, conforto e um brilho que se mantém ao longo do tempo. O design minimalista torna o conjunto perfeito para uso diário, além de ser uma excelente escolha para presentear alguém especial. A combinação do ouro 18K com o cristal cria um visual clássico e atemporal, ideal para quem deseja compor um porta-joias com peças de alta qualidade e estilo. Adicione o conjunto Alice ao seu look e sinta a diferença que uma semi joia exclusiva Piuka pode fazer na sua presença. Garanta o seu agora e ilumine cada momento!&Lt;br><br> Dados Tecnicos:&Lt;br> Material: Metal e zircônia.&Lt;br> Banho: Ouro 18K.&Lt;br> Tamanho: 43 cm.&Lt;br> Extensor: 4 cm.&Lt;br> Peso: 5,3 gr.&Lt;br><br> Observações:&Lt;br><br> - Garantia de 3 meses quanto ao banho.&Lt;br> - É uma peça hipoalergênica, pois não contém níquel em sua composição.&Lt;br> - Dica da Piuka: Para fazer a limpeza dos seus acessórios, use nossa flanela mágica, ela ajudará a manter suas peças sempre brilhantes.', 179.88, 179.88, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-8261o-mjo75qnkywaqc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F762167039%2F58203584923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497127236', 'Óleo Mágico de Rícino - DaBelle Hair 45ml', 'O Óleo de Rícino DaBelle fortalece e revitaliza cabelos fracos e quebradiços, promovendo força e vitalidade aos fios. O que éÉ um óleo capilar formulado com óleo de rícino, conhecido por suas propriedades fortalecedoras e nutritivas, ideal para cabelos danificados e sem brilho. Ações Fortalecimento: Reforça a fibra capilar, prevenindo a quebra e promovendo o crescimento saudável. Nutrição Profunda: Hidrata intensamente os fios, restaurando a vitalidade e o brilho. Proteção: Forma uma barreira contra agressões externas, como poluição e raios UV. Resultado no cabelo Cabelos mais fortes, hidratados, com brilho intenso, maciez e aparência saudável. Modo de uso Aplique uma pequena quantidade do óleo nas mãos e distribua uniformemente pelo comprimento e pontas dos cabelos úmidos ou secos, evitando a raiz. Reaplique sempre que desejar. Para umectação, aplique uma quantidade maior do meio até as pontas e deixe agir durante a noite; pela manhã, lave normalmente. Os óleos também podem ser utilizados em misturas com cremes de pentear ou ativadores de cachos. Com proteção térmica e UV, são ideais para aplicação antes do uso de fontes de calor ou exposição ao sol.', 29.9, 26.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82601-ml5lqgxfz216a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F23497127236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
