INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392983676', 'Sensor Rotação Ford Fiesta 2001 a 2007 - 839885 - 7050', 'Sensor Rotação Ford Fiesta 2001 a 2007 839885 7050 1.6 8v - 2 Pinos Sua principal função é medir a velocidade de rotação do motor (RPM), através de pulsos digitais captados em cima da roda dentada (fônica) do virabrequim do mesmo motor repassando essa informação a central. Ele é um componente vital no sistema de injeção eletrônica do seu carro a ponto de, em alguns modelos, o carro sequer ligar. Este sensor é um ímã enrolado em uma bobina dentro de um recipiente cilíndrico e selado. Ou seja: não tem conserto, levando a troca da peça quando apresentar defeito.', 96.05, 96.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-luie1m4utffxce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22392983676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299204497', 'Cafeteira Elétrica 0.6ml Telefunken Verona', 'A Cafeteira Elétrica 0.6mL Telefunken Verona faz até 0.600 mL de café ou de 4 a 8 xícaras; sua jarra de vidro possui marcas de medição e sua placa de aquecimento antiaderente é fácil de limpar. Filtro cônico removível e lavável incluído: não há necessidade de filtro de papel. Principais Características Capacidade 0.600 mL Filtro removível e lavável Indicador de nível de água Jarra de vidro Desliga automaticamente Placa de aquecimento que mantém o café quente Luz indicadora de funcionamento Itens da Caixa 1 (uma) Cafeteira Elétrica 0.600 mL Telefunken Verona Manual do usuário Certificado de garantia Especificações técnicas Tipo: Cafeteira Elétrica 0.600 mL Telefunken Verona Potência: 650W Frequência: 60Hz Voltagem: 110V ou 220V Cor: Preta Consumo: 0,65 KWh Material do produto: Plástico Informações adicionais: Função de desligamento automático Dimensões Aproximadas da Caixa (AxLxC): 25,5x19x15,1 cm Peso do Produto + Caixa: 0,7 kg Garantia: 6 Meses do fabricante, para defeitos de fabricação', 99.99, 99.99, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rcdo-lrspyq4ocyir34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1187363154%2F18299204497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19822458104', 'Difusor Aromatizador Original Porcelana com Essência Aroma - 10ml', 'Seja Bem-Vindo à loja Oficial Via Aroma! O Aromatizador Elétrico Original é um difusor de Essências e Óleos Essenciais que garante praticidade, economia e segurança. Desenvolvido para facilitar a difusão de óleos essenciais e essências, este aparelho é uma invenção original da Via Aroma para trazer mais bem-estar, inspiração e cuidado ao seu dia a dia Certificado pelo Inmetro; Feito de porcelana; Bivolt (127-220V); Difusor de óleos essenciais e essências; Baixo consumo de energia; Temperatura constante; Plug rotativo (se ajusta a posição da tomada); 2 anos de garantia. A Essência Bamboo Via Aroma traz uma sensação de leveza e bem-estar ao ambiente. Seu cheirinho refrescante de folhas verdes é bem equilibrado com o toque cítrico do bamboo, deixando um clima mais agradável no seu espaço. Notas de saída: Bergamota, Jacinto Notas de corpo: Jasmim, Muguet, Cedro Notas de fundo: Musk, Madeira Tek, Âmbar MODO DE USO Com essência: adicione 15 gotas de Essência Via Aroma, ajuste o plug e conecte na tomada para aromatização do espaço de 30m² por até 4 horas. Com óleo essencial: adicione 5 gotas de Óleo Essencial Via Aroma + 10 gotas de água, ajuste o plug e conecte na tomada para difusão ambiental. Não recomendamos o uso com outras substâncias. PRECAUÇÕES: Manter fora do alcance de crianças e animais domésticos. Atenção, durante o funcionamento do aparelho a bacia poderá estar quente, evite o contato. Posicionar o plug sempre no sentido da tomada. Evitar uso de adaptadores sem o selo do Inmetro em conjunto com o produto. Usar somente com o agente odorizante recomendado.', 69.9, 61.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-7qveo-lf5eu17fddim5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545693995%2F19822458104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
