INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260060865', 'Sylvanian Families Família dos Pássaros Cítricos - Epoch', 'A encantadora Família dos Pássaros Cítricos da Sylvanian Families traz ainda mais cor, delicadeza e diversão para o universo das miniaturas. Produzida pela Epoch, esta adorável família é composta por personagens cheios de personalidade, com detalhes delicados, acabamento caprichado e roupinhas encantadoras. Perfeito para criar histórias cheias de imaginação, estimular o faz de conta e ampliar sua coleção com personagens únicos e especiais. Cada integrante possui um visual carismático que torna as brincadeiras ainda mais divertidas e encantadoras. Ideal para crianças, colecionadores e fãs do mágico universo Sylvanian Families! Fabricante: Epoch Ref.: 5860 Código Barras: 5054131058602 Idade recomendada: Acima de 3 Anos Dimensões da Embalagem (AxLxC): 11X18X6cm Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 269.99, 249.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-820ln-mntyj3ikclj542', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F58260060865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259456162', 'Bala Beijos Fini', 'Se um Beijo é bom, imagine um pacote inteiro de Beijos Fini! Clássico super macio, cremoso e docinho, com sabor de morango e nata, na cor rosa e branco. É muito amor envolvido! * Sabor delicioso de morango * Textura macia e irresistível * Perfeito para compartilhar com amigos e família', 8.99, 8.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-82594-mqnel3a0e9kxf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259456162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259463037', 'Limpa Vidros Veja Vidrex com Álcool 500ml Oferta', 'Veja Vidrex Secagem Rápida com Álcool é a solução ideal para quem busca vidros limpos, brilhantes e sem marcas em poucos instantes. É só passar um Veja para eliminar sem esforço manchas, marcas de dedos e poeira, deixando as superfícies impecáveis. Sua fórmula com álcool garante secagem rápida, sem deixar resíduos ou embaçar o vidro. Pode ser utilizado em todos os tipos de vidro, como janelas, espelhos, boxes, mesas e vitrines, trazendo mais praticidade e brilho para a limpeza do dia a dia. Brilho imediato: valoriza a aparência dos ambientes, deixando os vidros com aspecto limpo e bem cuidado. Antes de usar, leia as instruções do rótulo.', 14.79, 14.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-825at-mqnekx5cbi0x93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259463037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198542134', 'Par Suporte Farol Milha Auxiliar Sandero Stepway 15 16 2017', 'CARACTERÍSTICAS: Produto Novo de Ótima Qualidade Fabricado em Plástico Resistente Cor Preto OPÇÕES DISPONÍVEIS: Lado Esquerdo (Motorista) Lado Direito (Passageiro) * VALOR ANUNCIADO É REFERENTE AO PAR. ESPECIFICAÇÕES TÉCNICAS: Com furo para farol de Milha COMPATÍVEL COM OS MODELOS: Sandero Stepway 2015 até 2017 IMPORTANTE: Não nos responsabilizamos por instalação mal realizada A instalação deve ser feita por um profissional especializado', 97.94, 97.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rave-ma99do4r3ti91d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1324075682%2F23198542134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298195180', 'Kit Bíblia Sagrada | NVI | Jardim da Fé + Bíblia Sagrada | NVI | Leão Judá', 'Descubra a Bíblia Sagrada NVI Explore as Escrituras de maneira clara e acessível com a Nova Versão Internacional (NVI) da Bíblia! Publicada pela Sociedade Bíblica Internacional, a NVI é uma tradução moderna que mantém a fidelidade aos textos originais, oferecendo uma leitura envolvente e compreensível. Por que escolher a Bíblia NVI? Linguagem contemporânea para fácil compreensão. Fidelidade aos manuscritos originais. Inclui Antigo e Novo Testamento para uma experiência completa. Amplamente Utilizada e Amada A Bíblia NVI é apreciada por comunidades cristãs de língua portuguesa, oferecendo uma visão abrangente das Escrituras. Seja você um estudioso da Bíblia ou alguém buscando inspiração, a NVI é para todos. Experimente a Palavra de Deus de uma Nova Maneira com a Bíblia NVI. Seja Inspirado e Transformado! Um pouco sobre o texto da NVI: A Bíblia NVI refere-se à "Nova Versão Internacional", uma tradução da Bíblia para a língua portuguesa que busca oferecer uma leitura clara e compreensível, utilizando uma linguagem contemporânea. A NVI foi publicada pela Sociedade Bíblica Internacional e foi lançada em 1993. Ela é resultado de um trabalho de equipe de diversos estudiosos e especialistas em línguas bíblicas. A ideia por trás da NVI era proporcionar uma tradução que fosse ao mesmo tempo precisa e acessível ao público em geral. Ela se esforça para manter a fidelidade aos manuscritos originais, ao mesmo tempo em que utiliza uma linguagem mais contemporânea para facilitar a compreensão do texto por parte dos leitores. A NVI inclui tanto o Antigo Testamento quanto o Novo Testamento, proporcionando uma visão abrangente das Escrituras. Ela tem sido amplamente utilizada em diversas comunidades cristãs de língua portuguesa, sendo apreciada por muitos por sua clareza e acessibilidade. Palavras chaves: Bíblia NVI; NVI; Nova Versão Internacional; Escrituras em Português; Tradução Moderna da Bíblia; Palavra de Deus; Antigo Testamento; Novo Testamento; Sociedade Bíblica Internacional; Leitura Inspiradora; Experiência Bíblica Completa; bíblia capa dura; Palavras de Cristo; Experiência Transformadora; Versão Atualizada da Bíblia;', 49.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5oe82sjfgwgb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F22298195180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
