INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593401785', 'Kit Lixeira + Porta Escova de Dente com Tampa + Dispenser Sabonete Liquido 9063 - Arthi', 'Kit Lixeira + Porta Escovas com Tampa + Porta Sabonete Liquido 9063 - Arthi Transforme seu banheiro em um ambiente moderno e sofisticado com o Kit Lixeira 5 litros, Porta Escovas com tampa e Porta Sabonete Líquido da Arthi. Este conjunto é ideal para quem deseja aliar funcionalidade e design em um só produto. A Lixeira Black Arthi, com sua capacidade de 5 litros, se destaca pelo design elegante e minimalista, oferecendo praticidade no descarte de resíduos e mantendo o ambiente sempre organizado. Seu acabamento refinado garante que o acessório se integre harmoniosamente a qualquer decoração, trazendo um toque de sofisticação ao seu banheiro. O Porta Escova e Pasta com Tampa Transparente complementa o kit com sua praticidade e estilo. O design clean e a tampa transparente permitem que você visualize e proteja os itens de higiene pessoal com facilidade, mantendo a pia sempre arrumada e funcional. Ideal para quem valoriza a organização sem abrir mão da estética, este porta escovas é um verdadeiro aliado na rotina diária. Para completar o conjunto, o Porta Sabonete Líquido Arthi de 500 ml segue a mesma linha moderna e funcional. Com um design que otimiza o espaço, este acessório é perfeito para manter o sabonete líquido sempre ao alcance, proporcionando praticidade e estilo ao seu banheiro. Feito com materiais de alta qualidade, o kit garante durabilidade e resistência, sendo uma excelente opção para quem busca produtos que aliam beleza e eficiência no dia a dia. Especificações: Marca: Arthi Lixeira 5 Litros: Diâmetro: 19 cm Altura: 25 cm Porta Sabonete Líquido 500 ml: Diâmetro: 8,8 cm Altura: 17 cm Porta Escova e Pasta com Tampa: Diâmetro: 8,8 cm Altura: 17 cm', 118.9, 47.56, NULL, 'Home & Living > Bathrooms > Toothbrush Holders & Toothpaste Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx0-m0vlobq0kllacc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F23593401785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
