INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255853521', 'Garrafinha Infantil Fresh Buba Verde Canudo Retrátil e Tampa', 'Garrafinha Fresh Infantil Buba Canudo de Silicone Retrátil e Tampa Higiênica Protetora Capacidade: 300 ml Canudo em Silicone Tampa retrátil higiênica BPA free +12 Meses Dados da Embalagem - Contém: 1 Garrafa com canudo - Composição: PP, PE e Silicone - Livre de BPA e ftalatos. - Produto 100% atóxico. Recomendações: Este produto pode ser esterilizado em água fervida e pode ir à lava-louças. Lave bem antes do primeiro uso com água corrente e sabão neutro. Manter em local seco, longe do alcance do sol. Examine regularmente o estado de todas as peças do produto. Se apresentar dano ou sinal de desgaste, descarte o produto imediatamente. Realizar o descarte adequado dos sacos plásticos, das fitas adesivas, dos fechos, etc. Este produto poderá apresentar variação de cores e detalhes. Guarde esta embalagem para eventuais consultas. Este produto não é um brinquedo, utilizar sempre sob supervisão de um adulto.', 33.44, 27.19, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-8261w-ml5u03kfvqq5e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58255853521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
