INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28885549233', 'IELGY Mules Femininos De Verão Relaxados E Respiráveis De Malha Voadora', 'Marca: IELGY Altura do salto: cerca de 1-3 CM 1cm=0,393pol (Medição Manual, erro de 1-3 cm pertence à faixa normal) O pacote de sapatos inclui: um par de sapatos Nota: O produto não possui caixa de sapatos Padrão de listras: padrão de listras: listras Altura superior: cano baixo Altura do salto: salto baixo (1-3CM) Forma do salto: salto plano Material da sola: PVC Volume de Embalagem: regular Elementos populares populares de cores: correspondência de cores Estilo: sapatos de pano Método de fechamento: tampa do pé Material da palmilha: EVA Cenário de Cenário: Diariamente Forma do dedo do pé: cabeça redonda Material superior: tecido voador Estilo de uso: manga Função de função de respirável: Respirável Estilo do Casual Obs: Chinelos são geralmente maiores e mais confortáveis, caso não tenha certeza de qual tamanho é semelhante, por favor pegue um tamanho maior Tamanho do sapato: largura do pé ou dedo do pé pequeno ou salto alto, de acordo com sua própria situação e o tamanho do sapato habitual é recomendado para escolher um tamanho maior.', 173.63, 120.57, NULL, 'Women Shoes > Flats > Slip Ons, Mary Janes & Mules', 'https://cf.shopee.com.br/file/sg-11134201-7rfhq-m96ye7f07puxdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217877619%2F28885549233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198027673', 'Garrafa Térmica Camp Super Mario 600ml Aço Inox Zona Criativa - 10073185', 'Você passou o dia tentando salvar a princesa Peach, mas precisa de uma mãozinha na hora de se hidratar? A gente te ajuda! Com 600ml de capacidade, essa é a companhia perfeita para você sobreviver e conseguir passar de fase! Com um detalhe em bamboo na tampa e uma alça, você consegue carregá-la por todas as fases! Não importa onde é a aventura, essa garrafa te acompanha em todos os lugares! O produto é importado, feito em aço inox e bamboo, possui detalhes incríveis que vão fazer você se apaixonar! Com 600ml de capacidade, é a companhia que você precisa para sobreviver o dia! Com uma parede dupla, garante que sua bebida fique gelada por até 24h e quente por até 12h, além de possuir tampa com rosca, que não vaza na sua mochila e uma alça para te ajudar a transportar a garrafa para onde você quiser! Especificações: Altura: 25cm| Largura: 7cm| Comprimento: 7cm| Capacidade: 600ml| Material: Aço Inox e Bamboo| Térmica: 24h gelada, 12h quente Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos. Especificação - TÉRMICA (H): 24 horas gelado 12 horas quente - ALTURA (CM): 25 - MATERIAL: METAL (AÇO INOXIDÁVEL) - LARGURA (CM): 7 - CAPACIDADE (ML): 600 - COR PREDOMINANTE: AZUL - FORMATO: GARRAFA CAMP - COMPRIMENTO (CM): 7 Características: - Marca: ZONA CRIATIVA - Modelo:10073185 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Garrafa Térmica Camp Super Mario 600ml garrafa termica - garrafa termica camp - garrafa super mario - super mario', 166.93, 149.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rens-m271epdyo7na4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F22198027673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
