INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594302683', 'Alto Falante Subwoofer Triton AK 6.0 15 Polegadas 3000W RMS 4 Ohms Branco', 'Acompanhando as inovações tecnológicas, tendência musical e pensando no compromisso e responsabilidade com seu cliente, a Triton alto-falantes desenvolve o AK 6.0 de 15 polegadas. O AK 6.0 15" apresenta 6000W de programa musical e disponível na versão de 4 Ohms. O grande destaque está em sua qualidade sonora, que realça as frequências baixas sem perder o ataque. Potente e controlado fluxo magnético. Sistema de refrigeração com direcionamento do fluxo de ar, que prioriza a dissipação do calor que é produzido na bobina. Informações Técnicas • Potência Máxima Contínua: 3000W RMS • Impedância Nominal: 4 Ohms • Material da Bobina Móvel: Cobre • Diâmetro de Corte do Baffle: 360 mm • Diâmetro Nominal: 15” • Ressonância Nominal: 49,01 Hz • Sensibilidade: 96,04 dB SPL (1W@1m) • Diâmetro da Bobina Móvel: 4” • Xmax: 11,7 mm • Fs: 49,01 Hz • Re: 3,0 O • Qms: 12,12 • Qes: 0,31 • Qts: 0,30 • Vas: 67,21 • Sd: 9.08E-02 • Bl: 23,06 T/m • Peso Líquido: 22,50 kg • Peso com Embalagem: 23,70 kg • Dimensões da Embalagem (LxAxP): 43 x 23 x 43 cm • Volume Ocupado Pela Embalagem: 42,5 L', 2305.0, 2305.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md63nh916rr505', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229977598%2F23594302683', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
