INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7273226662', 'Par Palheta Limpador Parabrisa Nissan Tiida 2008 ATÉ 2013', 'ACOMPANHA: 02 PALHETAS DIANTEIRAS APLICAÇÃO: NISSAN TIIDA ANO 2008 ATÉ 2013 INFORMAÇÕES TÉCNICAS MEDIDAS DIANTEIRAS: 16 POLEGADAS - 450 MM - ENCAIXE GANCHO 22 POLEGADAS - 550 MM - ENCAIXE GANCHO Essencial para os dias de chuva, a palheta do seu automóvel deve estar em boas condições para limpar perfeitamente seu para-brisa, ajudando a ter uma visibilidade melhor e assim evitando acidentes. Obs: É recomendável a troca de palhetas do seu automóvel a cada 6 meses. - MELHORA A LIMPEZA E PROPORCIONA UMA MELHOR VISIBILIDADE EM DIAS CHUVOSOS - FEITA DE SILICONE NÃO ENFERRUJA E NÃO RISCA SEU VIDRO - SÃO FLEXÍVEIS - NÃO CAUSA BARULHO E TEM MAIOR DURABILIDADE QUE AS DA CONCORRÊNCIA - FÁCIL APLICAÇÃO/INSTALAÇÃO - MELHOR QUALIDADE - SATISFAÇÃO GARANTIDA', 34.9, 23.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0ptjoyqvsm88b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F7273226662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
