INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299086792', 'Kit Pedreiro 12 X 24cm com 4 Unidades', 'Loja do Mecânico - O que você precisa, nós temos! Kit pedreiro de alta qualidade para você. - Especificações Técnicas: :: Colher de Pedreiro: 8" :: Caixa de Massa: 20L :: Desempenadeira: 12 X 24cm - Conteúdo da Embalagem: :: 1 unidade caixa de massa 20l :: 1 unidade desempenadeira 12 x 24cm dentada :: 1 unidade colher de pedreiro 8” reta :: 1 unidade bloco de espuma - Garantia: 1 Ano - 7897937437640 Ref.: MOMFORT-600000 Marca.: MOMFORT', 103.99, 77.07, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lnndsjh06x8of0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F20299086792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294400020', 'Massa Resina Termoplástica PCL Polycaprolactona Artesanato Restauração', 'ENVIAMOS O PRODUTO NO MESMO DIA DA COMPRA SEU PEDIDO VAI BEM EMBALADO E COM NOTA FISCAL Esse é o Termoplástico mais famoso do Mercado! O Polycaprolactone é um termoplástico moldável e seguro. Ideal para reparos e preenchimento de espaços vazios. Veja como é fácil usar: 1 - Coloque cerca de 10 a 20 bolinhas em água fervente até que se tornem transparentes e se unam 2 - Retire a massa transparente da água com uma colher e modele com a mão. 3 - Aguarde até a massa ficar branca por completo e dura. Esse processo acontece em cerca de 1 minuto. Para adiantar você pode passar a massa em água fria, ela ficará na cor branca como antes. 4 - Molde no local desejado como preferir. Para moldar novamente, basta repetir o mesmo processo. MATERIAL: Polietileno Termoplástico PCL COR: BRANCA Produto vendido em gramas.', 34.9, 19.0, NULL, 'Stationery > Art Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfo9ouqa330n2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F554865709%2F22294400020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
