INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4289883607', 'Kettlebell Emborrachado 06kg - Treinamento Funcional - Halter, Pesos, Musculação, Crossfit', 'O Kettlebell é uma modalidade de exercícios físicos que vem ganhando cada vez mais espaço, trata-se de uma bola de ferro com uma alça que permite uma grande variedade de movimentos, os exercícios com o kettlebell proporciona diversos benefícios como: - Queima de calorias - Aumenta a capacidade cardiovascular - Propicia uma maior estabilidade da coluna - Melhora da potência, força, resistência aeróbia, coordenação, equilíbrio, concentração e flexibilidade Características: - Ferro Fundido - Emborrachado', 120.0, 120.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/4e46a1e5e140e6b9ceb8ee64e2a10ef0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F4289883607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194955976', 'Geladeira Philco French Door Frost Free Inverter 523L PRF53A Inox 110V', 'Geladeira Philco French Door Frost Free Inverter 523L Smart Cooling Turbo PRF53A Inox 110V Organize seus alimentos com a geladeira Philco PRF53A French Door, ideal para uso doméstico com ampla capacidade. Com 523L de capacidade total, sistema Frost Free e tecnologia Inverter, oferece praticidade e desempenho eficiente no dia a dia. O Smart Cooling contribui para manter a temperatura interna mais estável, ajudando na conservação dos alimentos, enquanto o painel digital externo facilita o ajuste das funções. Iluminação em LED e prateleiras de vidro temperado favorecem a visualização interna e a organização de bebidas, legumes e frutas. O acabamento inox combina com cozinhas modernas e diferentes estilos de decoração, mantendo o ambiente funcional. A tradição da Philco em eletrodomésticos reforça a confiabilidade no uso contínuo do produto. Vantagens e diferenciais Capacidade de 523L: acomoda compras maiores, bebidas e alimentos da família com mais organização. Frost Free: evita acúmulo de gelo e dispensa descongelamento manual, trazendo praticidade no dia a dia. Tecnologia Inverter: otimiza o funcionamento do compressor para desempenho eficiente no uso doméstico. Smart Cooling: ajuda a manter a temperatura interna mais estável para melhor conservação dos alimentos. Painel digital externo: permite ajustar funções e temperatura sem abrir a porta, facilitando o uso. Iluminação em LED: melhora a visualização interna sem aquecer o interior da geladeira. Especificações Técnicas Marca: Philco Modelo: PRF53A Tipo de refrigerador: French Door Capacidade total: 523L Capacidade do refrigerador: 365L Capacidade do freezer: 158L Tecnologia: Inverter Degelo do freezer: Frost Free Painel de controle: Digital externo Tipo de controle de temperatura: Digital Quantidade de níveis de temperatura: 3 Iluminação interna: LED Material das prateleiras: Vidro temperado Função Turbo: Sim Modo Economia: Sim Observações importantes As cores do produto podem variar de acordo com a calibração e resolução do monitor ou tela utilizada. As imagens são meramente ilustrativas. O produto real pode apresentar pequenas variações de tonalidade, formato ou acabamento. Verifique a voltagem informada no título do produto antes de efetuar a compra.', 6038.89, 6038.89, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-820mo-mnxcmviuqx3748', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23194955976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
