INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256867985', 'Jibbitz™ Coração Bolha Iridescente Único', 'Os maravilhosos Jibbitz™ Charms são acessórios que você coloca nos seus Crocs. Eles são fáceis de colocar e retirar, para que você possa mudar seus estilo a qualquer momento. Adicione os encantos dos Jibbitz™ Charms aos seus Crocs para mostrar que seu estilo e criatividade são únicos! De personagens conhecidos a emojis populares. Tem algo a dizer? Diga! Se ama alienígenas e unicórnios? Mostre! Fácil de colocar e ser removido, combina com qualquer look, companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a crianças menores de 3 anos de idade. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 34.99, 34.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-82603-mlrvw1d0rjlsfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F58256867985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999666233', 'Kit 20 Cadeiras de Jantar Roma para Sala e Cozinha', 'Cadeira de Jantar Roma para Sala e Cozinha Apresentamos a Cadeira de Jantar Roma, uma peça que combina estilo moderno com o máximo de conforto para transformar suas refeições em momentos ainda mais especiais. Esta cadeira é a escolha perfeita para quem busca sofisticação e funcionalidade na decoração da sala de jantar. A Cadeira de Jantar Roma apresenta um design contemporâneo que se destaca pela simplicidade elegante. Sua tonalidade suave traz luminosidade ao ambiente, complementando diferentes estilos de decoração. Os detalhes cuidadosamente pensados elevam o visual da Cadeira de Jantar Roma, transformando-a em um destaque na decoração da sua casa. O assento e o encosto levemente inclinado oferecem suporte, garantindo conforto máximo durante as refeições prolongadas. A Cadeira de Jantar Roma foi pensada para criar uma experiência agradável à mesa. A Cadeira de Jantar Roma também possui o benefício de ser confeccionada com materiais de alta qualidade. Feita 100% em polipropileno, material que assegura alta durabilidade e qualidade ao produto. Especificações Técnicas: Material: 100% Polipropileno Resistência: Aconselhável até 120,00kg Peso: Aproximadamente 6,00kg Dimensões: > Altura total(cm): 81,00 > Altura do Assento(cm): 45,50 > Largura do Assento Parte Menor(cm): 36,00cm > Largura do Assento Parte Maior(cm): 41,00cm > Profundidade do Assento(cm): 41,00 > Altura do Encosto(cm): 26,00 > Largura do Encosto(cm): 39,00 > Profundidade Total(cm): 39,00 > Largura Total(cm): 41,00 Importante: Produto enviado montado acondicionado em caixa de papelão reforçada > Observações de Entrega: Os entregadores não são autorizados: > Entrar no domicílio, sem estar acompanhado pelo cliente; > Entrar ou subir desacompanhado em prédio residencial ou comercial, o cliente precisa receber o pedido na portaria; > Entregar por meios alternativos (exemplo: içar produto por janela, subir escadas); > Entregar em edifícios, entrega será realizada apenas na portaria; > Realizar montagens, instalação ou manutenção de produtos; > Abrir a embalagem do produto; > Realizar entrega em endereço diferente do que consta na Nota Fiscal; > Garantia: 03 Meses Contra Defeitos de Fabricação. > Marca: Magazine Decor', 5799.99, 2879.0, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mftqa9ugq8zu71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347781606%2F20999666233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
