INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254360256', 'Mantecorp Glycare Control - Espuma de Limpeza 150ml', 'Espuma de limpeza para peles oleosas, acneicas e sensíveis. Mantecorp Glycare Control limpa a pele, controla a oleosidade e reduz o brilho. A Espuma de Limpeza Mantecorp Glycare Control tem em sua fórmula ativos que estimulam a renovação celular, equilibram o microbioma e reduzem acne e cravos. Além disso, deixa a derme hidratada, com aspecto saudável e mais equilibrada. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 74.9, 74.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-8260v-mk3wrqu5io7786', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254360256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
