INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206605843', 'Avène Mat Perfect Fluido Antiacne FPS60 - Protetor Solar 40g', 'Protetor solar facial para peles oleosas a acneicas. Avène Mat Perfect Fluido Antiacne conta com alta proteção solar e textura oil-free. O Protetor Solar Facial Avène Mat Perfect Fluido Antiacne possui rápida absorção, resistência à agua e proteção contra radicais livres. Sua fórmula absorve a oleosidade excessiva e mantém a pele sem brilho por até 12h, enquanto protege dos raios UVA e UVB: Um protetor solar facial ideal para peles oleosas a acneicas. Sua composição ainda é eco-friendly, já que é livre de Silicones, Octocrileno, Octil Salicilato e Benzofenona, ativos que causam impactos nos corais marinhos e fitoplânctons. Inicie sua rotina de skincare com o Gel de Limpeza Facial Cleanance, de Avène. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 125.9, 125.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-825zs-mlmhteay4c2761', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58206605843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
