INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51402040308', 'Kit Odomed Halicare Enxaguante Bucal Limpador de Língua (2 produtos)', 'Kit Odomed Halicare - Hálito Fresco e Limpeza Completa Este Kit Contém Odomed Halicare - Enxaguante Bucal Antisséptico 300ml: protege e mantém a saúde bucal, combatendo bactérias causadoras de infecções e mau hálito. Previne amigdalites, mucosites e periodontites, garantindo frescor e proteção prolongada. Odomed - Limpador de Língua: garante uma limpeza completa e suave, removendo a saburra lingual sem causar irritações. Com design ergonômico, flexível e área serrilhada, promove hálito puro e sensação de frescor. Conselho de Aplicação Enxaguante Bucal: coloque de 5 a 10 ml na boca e faça vários gargarejos. Fazer gargarejos é muito importante para o processo de limpeza da língua e da garganta. O gargarejo e/ou bochecho deve ser realizado durante um minuto. Ao final do procedimento cuspa o produto. Após realizar o procedimento, fique durante 30 minutos sem comer ou beber. O enxaguante bucal deve ser o último procedimento de sua higienização bucal.', 69.4, 47.9, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8225w-mhgq7rrosc1y74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F51402040308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46806113236', 'Livro Sensorial Bebê | Toque E Sinta O Mundo da Fazenda Texturas Para Crianças', 'Toque e Sinta – O Mundo da Fazenda O Toque e Sinta – O Mundo da Fazenda foi criado para aproximar os pequenos do universo rural de forma lúdica, educativa e encantadora. Em cada página, os animaizinhos da fazenda ganham vida por meio de historinhas fofas e texturas diferentes, que despertam a curiosidade e estimulam o desenvolvimento tátil, visual e motor. Com um formato pensado especialmente para as mãozinhas pequenas, o livro traz letras grandes e um vocabulário leve e adequado, tornando a leitura mais acessível e divertida. Seu acabamento de alta qualidade garante resistência e conforto: -Capa e páginas duras, que prolongam a vida útil do livro. -Pontas arredondadas, que oferecem total segurança. -Peso compatível com as mãos infantis, facilitando o manuseio. Além de entreter, este livro é um passatempo educativo que ajuda a reduzir a ansiedade infantil, promover a concentração e estimular o gosto pela leitura desde cedo. Um presente perfeito, que mantém as crianças longe das telinhas, pode ser levado para qualquer lugar e proporciona momentos de aprendizado e diversão que podem ser compartilhados em família. Toque e Sinta – O Mundo da Fazenda: um mergulho sensorial que transforma a leitura em uma experiência mágica!', 39.99, 21.99, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-81ztl-mklh54m9vz0hd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313968882%2F46806113236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
