INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498402486', 'Bieleta Civic 01 02 03 04 2005 2006 Axios Dianteira Direita', 'ITENS INCLUSOS: 1 Bieleta Direita Dianteira - Marca Axios; VEÍCULOS COMPATÍVEIS: Honda: • Civic 2001 Posição: Dianteira • Civic 2002 Posição: Dianteira • Civic 2003 Posição: Dianteira • Civic 2004 Posição: Dianteira • Civic 2005 Posição: Dianteira • Civic 2006 Posição: Dianteira GARANTIA: 3 meses DESCRIÇÃO: As bieletas Axios 5312193 são peças fundamentais para o sistema de suspensão do seu veículo. Fabricadas com materiais de alta qualidade, proporcionam maior estabilidade e segurança, garantindo uma condução suave e confortável. Essas bieletas são responsáveis por ligar a barra estabilizadora à suspensão, ajudando a manter a estabilidade do veículo em curvas e em situações de desníveis no terreno. Além disso, contribuem para reduzir ruídos e vibrações indesejadas, prolongando a vida útil de outros componentes da suspensão. Com as bieletas Axios 5312193, você terá a certeza de estar adquirindo um produto confiável e durável, fabricado seguindo os mais altos padrões de qualidade. Invista na segurança e no desempenho do seu veículo, contando com a tradição e excelência que a marca Axios oferece. PRINCIPAIS BENEFÍCIOS: Melhora estabilidade; Aumenta segurança; Reduz desgaste pneus; Facilita manutenção;', 119.65, 119.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rep6-m8nw6rcua7pz73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338381202%2F23498402486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093980637', 'Palheta Traseira Plus 120i 2005 até 2012', 'ITENS INCLUSOS: 1 Palheta Traseira 12" - 2M Plastic; VEÍCULOS COMPATÍVEIS: BMW: • 120i 2005 • 120i 2006 • 120i 2007 • 120i 2008 • 120i 2009 • 120i 2010 • 120i 2011 • 120i 2012 GARANTIA: 3 meses DADOS TÉCNICOS: Palheta Traseira 12" - 2M Plastic; DESCRIÇÃO: As palhetas são itens fundamentais para garantir uma visibilidade clara e segura durante a condução do veículo. Com a marca 2M PLASTIC, referência no mercado de peças automotivas, apresentamos o produto, que oferece qualidade e durabilidade. As palhetas da marca 2M PLASTIC são fabricadas com materiais de alta qualidade, garantindo uma limpeza eficiente do para-brisa e proporcionando uma visão nítida mesmo em condições climáticas adversas. PRINCIPAIS BENEFÍCIOS: Limpeza eficiente do para-brisa;', 73.82, 73.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rfgu-m9eju4a0qizt18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338381202%2F22093980637', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
