INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258464792', 'Água Micelar Facial 200ml', 'Essencial para completar seu skincare diário, a Água Micelar 10 em 1 de Vult Facial foi pensada para proporcionar uma rotina de cuidados faciais mais prática para todos os tipos de pele. Além de higienizar e retirar a maquiagem, também refresca a pele e a uniformiza com efeito Matte, deixando-a preparada para tudo. Afinal, ninguém quer ficar com a sensação de pele suada e suja, não é mesmo? Apresentando o Ácido Hialurônico como principal ativo, traz suavidade e revitalização para a pele, bem como proporciona a sensação de refrescância e hidratação para todos os dias. Conheça todos os benefícios deste produto: Limpa;Demaquila;Reequilibra;Suaviza;Refresca;Purifica;Melhora a textura;Matifica;Reduz a oleosidade;Permite que a pele respire. Ideal para usar antes da maquiagem ou do protetor solar, a Água Micelar pode ser sua aliada contra o excesso de oleosidade para uma pele luminosa e refrescada o dia todo. Nenhum produto Vult é testado em animais, ou seja, este item possui selo Cruelty Free. Produto Vegano. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 33.49, 33.49, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-81ztr-mmtf9vtu7kzm20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675526045%2F58258464792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
