INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999017947', 'Pote Hermético 5,3 litros', 'Com os Potes Herméticos a sua cozinha ganha organização e praticidade. Com fechamento hermético e vedação em silicone, o produto garante a ótima conservação dos alimentos, mantendo-os frescos por muito mais tempo. Livre de BPA, ele é produzido e pensado especificamente para o armazenamento de comidas. Disponíveis em diversos tamanhos, são perfeitos para organizar o ambiente da forma como você preferir. É fácil de limpar e de manusear, e você pode utiliza-lo no freezer. Com capacidade para 5,3L, o Pote Hermético facilitará muito o seu dia a dia. Não é indicado: utilizar produtos abrasivos, utilizar na lava louças, forno ou micro-ondas e levar diretamente ao fogo.', 53.0, 53.0, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-824hn-mfbbksap1ma127', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F22999017947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897753410', 'Calça Legging Move', 'Calça Legging de Academia com Tela confeccionado em Suplex, sendo um material leve e com boa elasticidade, sua modelagem se adere ao corpo garantindo a liberdade de seus movimentos. Possui tela dry na sua parte frontal dando aquele charme a mais na peça. ESPECIFICAÇÕES •Esta peça pode ser usada no dia a dia e para atividades físicas. •Este produto deve ser lavado apenas à mão e com sabão neutro. Prefira a secagem à sombra. Dispensa o uso de amaciante e ferro de passar. Pode haver também, variação nas cores por conta de fatores como iluminação fotográfica e brilho de cada monitor; Nossa forma é pequena, sempre aconselhamos a pegar uma numeração maior para mais conforto. COMPOSIÇÃO DA PEÇA: • 90% Poliéster / 10% Elastano • Microfibra de alta qualidade • Tecido SUPLEX TABELA DE MEDIDAS •Tamanho M: Busto (cm): 92 x 96 | Cintura (cm): 76 x 82 •Tamanho G: Busto (cm): 98 x 102 | Cintura (cm): 84 x 90 •Tamanho GG: Busto (cm): 104 x 108 | Cintura (cm): 92 x 98', 49.9, 29.9, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/sg-11134201-7rdwe-lzqjhsi5iq0c3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303874852%2F22897753410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
