INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599370241', 'BOLD CREATINA (300g) Suplemento', 'A BOLD Creatina 300g é um suplemento nutricional desenvolvido para auxiliar no desempenho físico e no ganho de massa muscular. Este produto contém creatina pura em embalagem de 300 gramas, proporcionando uma quantidade adequada para uso regular. A creatina é um composto naturalmente encontrado no organismo que auxilia no fornecimento de energia para os músculos durante exercícios de alta intensidade. Este suplemento pode ser facilmente incorporado à rotina de treinos, sendo ideal para praticantes de atividades físicas que buscam melhorar seu desempenho e recuperação muscular. A apresentação em pó permite fácil dissolução e consumo, podendo ser misturada com água ou outras bebidas de sua preferência.', 79.0, 69.0, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/br-11134207-820ls-ml7u74kz32ti7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662247567%2F22599370241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
