INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199072080', 'Kit 3 Ensure Plus Advance Baunilha 220ml', 'ENSURE PLUS ADVANCE BAUNILHA Hiperproteico. Alto teor de vitamina D. 1,5kcal/ml. Pronto para uso. Apresenta concentração exclusiva de CaHMB, proteínas e vitamina D. Contém também FOS - prebiótico. Possui alto teor de vitaminas B12, C, D, E e K, além dos minerais cálcio, ferro selênio e zinco. Fonte de vitamina A Usar somente sob orientação médica ou de nutricionista. Não utilizar em galactosemia. Não utilizar para uso intravenoso. Este produto é uma fonte de nutrição suplementar para ser usada sob supervisão médica. Não se destina a crianças a menos que recomendado por um médico ou outro profissional de saúde. NÃO CONTÉM GLÚTEN. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E DE SOJA.', 101.97, 101.97, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-823ri-mok6bib5clcc9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18199072080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20865026479', 'Kit 3 Desodorante Antitranspirante Rexona Antibacterial + Invisible Aerosol 150ml', 'Desodorante Antitranspirante Aerosol Feminino Rexona Antibacterial + Invisible 72 horas • A exclusiva fórmula do Desodorante Aerosol Feminino Rexona Antibacterial + Invisible garante 72 horas de proteção contra o suor e o mau odor ativado pelo movimento • Esse desodorante antitranspirante contém proteção antibacteriana* e antimanchas**, protegendo você contra o suor e mau odor e as suas roupas contra manchas brancas e amarelas • Desodorante feminino fácil de usar: agite e aplique nas axilas a não menos de 15 cm da pele • Sua tecnologia protege a roupa contra manchas brancas e amarelas e ainda ajuda a eliminar as bactérias que causam o mau odor nas axilas • Esse desodorante antibacteriano não contém álcool*** e não afeta a camada de Ozônio, sua lata é de alumínio 100% reciclável, feito com energia elétrica 100% renovável • O Desodorante Aerosol Feminino Rexona Antibacterial + Invisible permite que você fique sempre protegida, não importa o que aconteça. Rexona não te abandona Mais uma vez Rexona se supera e relança sua linha de desodorantes com uma fórmula inovadora. O Desodorante Aerosol Feminino Rexona Antibacterial + Invisible conta com 72 horas de proteção contra o suor e mau odor, ativado pelo movimento. Esse desodorante antibacteriano* ajuda a eliminar as bactérias que causam o mau odor nas axilas, e também conta com a proteção antimanchas**, protegendo as suas roupas contra manchas brancas e amarelas. A nova e exclusiva fórmula de Rexona Antibacterial + Invisible trabalha com um sistema de partículas menores e mais estáveis que formam uma barreira protetora mais resistente e duradoura contra a transpiração e o mau odor, mantendo você seca, refrescada e protegida a cada novo movimento e por muito mais tempo. Com o registro de 16 patentes e mais de 300 testes técnicos, está comprovado que essa nova tecnologia antitranspirante entrega um nível de proteção contra o suor como nenhuma outra proposta regular já entregou antes. Sua tecnologia protege a sua roupa contra manchas brancas e amarelas e ainda ajuda a eliminar as bactérias que causam o mau odor nas axilas. A lata usada no desodorante é feita de alumínio 100% reciclável, e o produto é feito com energia elétrica 100% renovável, não contém álcool*** e não afeta a camada de ozônio. Experimente também outros produtos da linha de desodorantes aerosol femininos Rexona e se sinta sempre protegida durante qualquer atividade, porque Rexona não te abandona. *Teste padrão in vitro realizado com S. epidermidis. Produto cosmético sem ação terapêutica **Manchas brancas e amarelas nas roupas ***Não contém álcool etílico', 47.07, 47.07, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mqlz984w505n20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20865026479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
