INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56453597043', 'Espelho Lopazzi Oval Home Design Corpo Inteiro com Moldura em Alumínio', 'A ELEGÂNCIA DAS CURVAS ATEMPORAIS PARA UM AMBIENTE MAIS LEVE E SOFISTICADO O Espelho Oval Lopazzi é a escolha definitiva para quem busca amplitude sem sobrecarregar o visual do ambiente. Seu design minimalista com bordas suaves suaviza as linhas retas da mobília, criando um espaço mais harmônico e elegante. Se você procura um espelho que une a sofisticação do alumínio com a nitidez do cristal puro, o modelo Oval é o seu novo item de desejo. Principais Benefícios: Silhueta Suave e Moderna: O formato oval é um curinga na decoração, adaptando-se do estilo clássico ao industrial com perfeição. pendurado na parede (suporte reforçado) ou apenas encostado para um ar artístico. Acabamento "Sea-Proof" (Antioxidação): Moldura em alumínio de grau industrial com pintura eletrostática. Não descasca, não enferruja e ignora a maresia. Segurança de Ponta a Ponta: Vidro temperado com película de segurança e suporte com trava anti-abertura. Ficha Técnica: Marca: Lopazzi Home & Design. Material: Vidro de Cristal (Nitidez 4K) e Moldura em Alumínio Premium. Medidas: 170x70cm, 150x60cm ou 110x50cm (Selecione a variação desejada). Cores de Moldura: Preto, Prata, Dourado, Bronze, Off-white e Marrom. Instalação: Sistema de encaixe rápido na parede Itens Inclusos: 01 Espelho Oval, kit de buchas e parafusos. Perguntas Frequentes (Quebra de Objeções): O espelho é pesado? R: É robusto porém manejável, graças à moldura em alumínio que oferece resistência com peso reduzido em comparação ao ferro. A embalagem é realmente segura? R: Sim! Utilizamos o sistema de proteção Lopazzi: Isopor reforçado, cantoneiras e caixa de papelão de alta gramatura. A cor da moldura desbota com o tempo? R: Não. A pintura eletrostática é fundida ao metal, garantindo que a cor permaneça impecável por anos. espelho oval, espelho de chao, espelho corpo inteiro, espelho decorativo, moldura aluminio, espelho luxo, lopazzi, espelho para quarto, espelho minimalista, espelho grande, espelho 170x70, espelho 150x60, decoração clean, espelho hall entrada, espelho provador, espelho sem distorção, espelho dourado, espelho preto, design interior, espelho parede', 415.9, 319.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81z1k-min3hkbatr0ia2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F56453597043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594872818', 'Kit Talheres Colher e Garfo Cabo em Silicone Buba Dino Azul', 'Kit Talheres Aço Cabo em Silicone Infantil Buba Kit Colher e garfo Buba A hora da papinha vai ficar muito mais prazerosa com o kit talher 2 peças da Buba. Ele possui design anatômico, perfeito para os bebês segurarem, permitindo que eles comam sozinho; além disso, os talheres possuem pontas arredondadas e material em aço inoxidável, tornando-os mais resistentes, higiênicos e seguros. Livre de BPA e ftalatos. A linha de alimentação da Buba traz itens práticos que facilitam a vida das mães e acompanham as diversas fases da criança, contribuindo para um crescimento saudável. Dimensões da Aproximadas da Embalagem: 3 cm x 12 cm x 20 cm (Altura x Largura x Comprimento/Profundidade)', 35.36, 31.29, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-82635-ml5h8hj5uexb70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22594872818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097687469', 'Gladius Reconstrutor Cerâmico Proteção E Brilho 500ml Vonixx', '01 - GLADIUS 500ML VONIXX 01 - TOALHA MICROFIBRA 40X40CM 220GSM GLADIUS RECONSTRUTOR CERAMICO SECANTE ABRILHANTADOR 500 ml VONIXX DESCRIÇÃO O Gladius é um reconstrutor cerâmico de alto desempenho desenvolvido para renovar e proteger a pintura do seu veículo. Os coatings cerâmicos sofrem degradação com a ação do tempo e podem sofrer ataques de produtos químicos indesejáveis. Isso faz com que a camada do produto perca parte da proteção, brilho e hidrorrepelência em superfícies vitrificadas. O produto pode ser aplicado sempre que for observada a perda de brilho e hidrorrepelência na pintura automotiva. ESPECIFICAÇÕES TÉCNICAS - Renovação e brilho - Proteção prolongada - Hidrorrepelente - Altura: 6 cm - Largura: 10 cm - Comprimento: 26,5 cm - Volume: 500 ml - Peso: 600 g MODO DE USAR 1 - Agite bem o produto antes de usar. 2 - Após lavar e secar o veículo, pulverize o produto na superfície em uma área não superior a 60x60cm. 3 - Em seguida, espalhe o produto com uma microfibra, e realize imediatamente o acabamento com outra toalha de microfibra até obter o brilho desejado. 4 - Repita o procedimento até a conclusão do veículo. APLICAÇÕES Indicado para pinturas externas do veículo, como capô, teto, portas e para-lamas. Rodas de liga leve, proporcionando um acabamento brilhante e protegendo contra sujeiras e agentes externos.', 56.6, 56.6, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ly9ifme8w5k536', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F319801107%2F22097687469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251830651', 'Kit 2x Lavitan Melatonina Sabor Morango com 90 comprimidos', 'Kit 2x Lavitam Melatonina Sabor Morango com 90 comprimidos Lavitan Melatonina é um suplemento alimentar com 0,20mg de melatonina. Comprimidos mastigáveis com rápida absorção. - Rápida Absorção; - Recomendado uso noturno; Modo de usar Ingerir 1 comprimido ao dia, 30 minutos antes de dormir.', 42.71, 37.8, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-822x8-mi4zd4daji0yd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58251830651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
