INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392921329', 'Kit 2 unidades - Fralda Geriátrica Bigfral Regular Plus XG 7 Unidades', 'Kit 2 Unidades - Fralda Geriátrica Bigfral Regular Plus XG com 7 Unidades A Fralda Geriátrica Bigfral Regular Plus XG foi desenvolvida para proporcionar proteção, conforto e segurança para adultos com incontinência urinária intensa. Com tecnologia de alta absorção, formato anatômico e sistema antiodor, é ideal para pessoas acima de 90 kg com circunferência de cintura entre 120 e 165 cm. Este kit contém 2 pacotes com 7 unidades cada, oferecendo praticidade e excelente custo-benefício para o dia a dia. Características - Tamanho XG (extra grande) - Indicado para cintura de 120 a 165 cm - Recomendado para usuários acima de 90 kg - Pacote com 7 unidades (kit com 2 pacotes) - Formato anatômico - Indicador de umidade - Barreiras antivazamento - Canais de distribuição de líquidos - Sistema antiodor Benefícios Fralda Geriátrica Bigfral Regular Plus XG - Proteção máxima contra incontinência urinária intensa - Rápida absorção que mantém a pele seca - Redução de odores com sistema antiodor - Ajuste confortável ao corpo, permitindo mobilidade - Menor risco de vazamentos com barreiras laterais - Indicador de troca que facilita o cuidado diário - Ideal para uso pós-parto, pós-operatório e rotina diária Como Usar Fralda Geriátrica Bigfral Regular Plus XG - Verifique se o tamanho é adequado ao usuário - Higienize e seque bem a região íntima antes do uso - Abra a fralda e posicione com a parte absorvente voltada para o corpo - Ajuste ao corpo de forma confortável - Fixe utilizando as abas adesivas laterais - Verifique o indicador de umidade regularmente - Realize a troca sempre que necessário ou a cada 4 a 6 horas - Descarte após o uso em local apropriado Composição Polpa de celulose, polímero superabsorvente, filme de polipropileno e outros materiais absorventes Advertências - Não utilizar em caso de alergia a qualquer componente - Trocar regularmente para evitar irritações e assaduras - Em caso de irritação, suspender o uso e procurar orientação médica - Manter fora do alcance de crianças - Armazenar em local seco, fresco e protegido da luz solar - Descartar corretamente após o uso', 58.75, 51.99, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rcct-lt73yyq5x4ngc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22392921329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597333866', 'Kit 2 Acabamento Para Válvula De Descarga Vaso Sanitário Banheiro Deca Hydra Docol Preto Fosco Black', 'KIT 2 ACABAMENTO PARA VÁLVULA DE DESCARGA PARA BANHEIRO, LAVATÓRIO, LAVABO E VASO SANITÁRIO DECA HYDRA DOCOL MAX EM ABS PRETO FOSCO BLACK MATTE. SOBRE O PRODUTO: Acabamento em ABS (Plástico de Engenharia). Resistência, preço baixo, sofisticação e vida útil por mais tempo. Você vai se impressionar com o acabamento de descarga em abs. Ele é leve, moderno e se adapta a qualquer tipo de caixa acoplada, para quem busca deixar seu banheiro ou lavatório, completo com itens de qualidade economizando, esta é uma ótima opção! Além de ser resistente e de linda estética este produto vai dar o toque especial que seu banheiro merece. ESPECIFICAÇÕES DO PRODUTO: MATERIAL: ABS. MEDIDA DO PRODUTO: 11 CM X 11 CM. PROFUNDIDADE DO PRODUTO: 4 CM. MEDIDA ENTRE FUROS: DE 7CM a 8CM. COMPOSIÇÃO DO PRODUTO: 02un- ACABAMENTO HYDRA MAX (ABS). 08un- PARAFUSOS DE INSTALAÇÃO (LATÃO). COMPATÍVEL COM VÁLVULAS DE DESCARGA HYDRA MAX (DECA) E DOCOL. DIFERECIAIS DO NOSSO PRODUTO: - Melhor acabamento do mercado. - Material resistente e de alta durabilidade. - Proporciona elegância ao seu ambiente. NOSSOS DIFERENCIAIS: - Preço de fábrica. - Envio mais rápido do Brasil. - Equipe com grande experiência para melhor atendê-los. - Produtos a pronta entrega. RECOMENDAÇÕES: - Limpe periodicamente o produto utilizando um pano macio com sabão neutro. - Contrate um profissional para a instalação. - Nunca use produtos abrasivos como alcalinos, ácidos ou solventes nos produtos. Confira nossa lista, ou entre em contato conosco, temos peças de reposição à pronta entrega e atendimento a qualquer momento.', 59.9, 41.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/br-11134207-820lu-mp3panad4wsl46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337531568%2F22597333866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
