INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492943374', 'Conjunto Feminino Infantil Love Comes', 'Descrição: Conjunto Feminino Infantil Love Comes Conjunto em moletom 70% algodão e 30% poliéster super quentinho. Casaco na cor rosa com estampa frontal, calça lisa básica também na cor rosa! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Garantia: 1 Mês - Evento: Não - Tecido Peça: Moletom - Composição: 70% Algodão e 30% Poliéster - Estação: Inverno - Tabela de Medidas: Tabela de Medidas Casaco: Tamanho | Busto | Comprimento 1 | 27CM | 38CM 2 | 29CM | 40CM 3 | 32CM | 41CM 4 | 33CM | 46CM 6 | 35CM | 48CM 8 | 36CM | 50CM 10 | 37CM | 51CM 12 | 41CM | 54CM Tabela de Medidas Calça: Tamanho | Cintura | Comprimento 1 | 19CM | 48CM 2 | 20CM | 51CM 3 | 21CM | 54CM 4 | 21CM | 63CM 6 | 23CM | 67CM 8 | 23CM | 70CM 10 | 24CM | 73CM 12 | 26CM | 76CM - Faixa Etária: 1 à 12 anos - Gênero: Feminino', 69.9, 29.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rd4q-luaz3xhurb7pbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F22492943374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998121036', 'Capacete Race Tech Sector Slash Branco', 'Produto acompanha apenas a viseira Cristal - Foto meramente ilustrativa. Famosas pelas jaquetas de alta qualidade com excelente custo/benefício, a RACE TECH tem o prazer de apresentar o SECTOR, novo capacete da marca que chega ao mercado brasileiro. Fabricado em ABS de alta pressão, o SECTOR tem entradas de ar ajustáveis integradas com o EPS de multidensidade para elevar o conforto do motociclista. Características: • Pensado urbano e rodoviário leve, pesa apenas 1.450g (+-50); • A viseira de 2,2 mm recebe tratamento UV e anti-risco para maior vida útil; • O sistema de troca é rápido, visando a praticidade e agilidade necessária no dia a dia; • A forração removível e lavável recebe inserções refletivas e tratamento antialérgico; • Bavete removível, narigueira alta e fecho micrométrico de fácil acesso mesmo com luva.', 521.88, 521.88, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra3c-m4q0qi4bqjiq5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F806887225%2F22998121036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
