INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899380324', 'Óleo Moto 10w30 Semissintético 4t Ipiranga Cg Titan Fan Cb Xre', 'Óleo Ipiranga 10w30 Semissintético 1L Óleo lubrificante semissintético para motores 4 tempos de motocicletas a gasolina, etanol ou flex de última geração, inclusive as de alta cilindrada. Possui aditivos detergentes e antioxidantes especialmente desenvolvidos para evitar a formação de depósitos e borras. Com exclusiva tecnologia Nano ARMOR™ capaz de criar uma armadura de proteção extra para desempenho otimizado e longa vida da sua motocicleta. As pequenas moléculas modificadas são adsorvidas quimicamente pelas partes metálicas, formando uma camada de interação a nível molecular, garantindo a devida proteção e cuidado que o seu veículo necessita. Especificações: - Aplicação: Lubrificantes para Motor - Qualidade: Semissintético - Tipo de motor: 4 Tempos - Viscosidade: 10W30 - Atende ou excede: SAE 10W30, API SL e JASO MA2.. (as mais exigentes classificações mundiais para motores a gasolina.) APLICAÇÃO: UTILIZADO NAS MOTOS MAIS MODERNAS DA HONDA, COMO BIZ, TITAN, CG, FAN, CB, CBX, BROS, XRE ETC. Conteúdo da Embalagem: 01 Frascos de 1 Litro de Óleo Ipiranga 10W30', 57.19, 57.19, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6qvfhxtunnrcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F20899380324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
