INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257281875', 'Tênis Infantil Bibi Roller 2.0 Azul de Dinossauro', 'O tênis infantil Roller 2.0 da Bibi acompanha os pequenos em grandes aventuras na rotina escolar. Com relevo divertido de dinossauros e combinação de cores cheia de personalidade, ele se torna o companheiro ideal para a escola, perfeito para correr, brincar e aprender com muita imaginação. Além do visual inspirado no universo dos dinos, o modelo foi desenvolvido para cuidar dos pezinhos em cada movimento. O solado exclusivo garante ótima aderência e estabilidade nas brincadeiras do dia a dia. A palmilha Fisioflex proporciona a sensação natural de caminhar descalço, favorecendo o desenvolvimento saudável dos pés. Já o cabedal em material respirável e o calce fácil deixam a rotina mais prática, ajudando as crianças a calçarem sozinhas com conforto e autonomia. Diferenciais: Calce fácil: Estrutura flexível que facilita o momento de colocar e tirar o tênis; Material respirável: Ajuda a manter os pezinhos secos e confortáveis durante todo o dia; Palmilha Fisioflex: Sensação de andar descalço, acompanhando o movimento natural do pé infantil; Solado super aderente: Leve e estável, ideal para correr, pular e explorar sem preocupações; Materiais atóxicos: Componentes seguros, pensados especialmente para o bem estar das crianças. Com o Roller 2.0, cada passo vira uma nova expedição pelo mundo dos dinossauros, unindo conforto, segurança e muita diversão na escola e nos momentos de lazer.', 219.9, 219.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mm1s391xd3ig2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F58257281875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
